// ST 正则引擎的 placement（public/scripts/extensions/regex/engine.js:281 regex_placement：USER_INPUT 1 / AI_OUTPUT 2）。
const THEATER_REGEX_PLACEMENT = { USER_INPUT: 1, AI_OUTPUT: 2 };
