    const sp = record && Number.isInteger(record.split) && record.split >= 0 ? record.split : chat.length;
    // 🎬 opts.mainFloor（数字）：主线那段再截到 mainFloor 之前（主线正在写的那一楼不喂）。
    const mf = (opts && typeof opts.mainFloor === 'number' && Number.isFinite(opts.mainFloor)) ? Math.max(0, Math.floor(opts.mainFloor)) : Infinity;
    let main = soThrHistoryFromMain({ chat: chat.slice(0, Math.min(sp, chat.length, mf)) });
    const depth = Number(opts && opts.depth);
    if (Number.isFinite(depth) && depth > 0) main = main.slice(-depth);
    else if (opts && opts.depth === 0) main = [];   // 「读最近几楼」= 0：主线那段一楼都不带（分隔线与 IF 各轮照旧）
