        const c = getCtx();
        if (c && typeof c.getTokenCountAsync === 'function') {
            const n = await c.getTokenCountAsync(list.map((m) => usage_text(m && m.content)).join('\n'));
            if (typeof n === 'number' && Number.isFinite(n) && n >= 0) return n;
        }
