        if (failed) addSystemNote(THEATER_MVU_PARSE_FAILED);
        if (soThrPanelsOn() && list === convo) soThrPanelsVarsChanged(entry, prev);   // 🎬 面板：这条 IF 的面板收到 VARIABLE_UPDATE_ENDED
