        main.type = 'button';
        main.className = 'so-thr-if-main';
        if (f.id === active) main.setAttribute('aria-current', 'true');
        const name = document.createElement('span');
        name.className = 'so-thr-if-name';
        name.textContent = String(f.name || '未命名');
