    if (!st) return;
    const copy = soThrClone(item);
    const at = st.items.findIndex((x) => x && x.id === copy.id);
    if (at >= 0) st.items[at] = copy; else st.items.push(copy);
    const key = soThrOwnerKey(copy.owner);
