                const before = s.slice(0, at).replace(/\s+$/, '');
                if ((/^<summary\b[^>]*>[\s\S]*?<\/summary\s*>$/i.test(tail) || !/<\/summary\s*>/i.test(tail)) && !/<details\b[^>]*>$/i.test(before)) cut = at;
