const THEATER_SCENE_FIRST_SYSTEM = (scene) => {
    const s = THEATER_SCENE_SPECS[scene];
    if (!s) return '';
    return `${THEATER_SCENE_COMMON}

—— 本次场景：${THEATER_SCENE_NAMES[scene]} ——
${s.app}

内容格式：
${s.format}

本场景类名：${s.classes}
本场景叫法键：${s.lex}
本场景插槽：${s.slot}`;
};
