const THEATER_RELOOK_SYSTEM = (scene) => soThrRelookSystemFrom(THEATER_RELOOK_COMMON, scene);
const THEATER_RELOOK_USER = (scene, ctxText) => `【场景】${THEATER_SCENE_NAMES[scene] || ''}\n\n${String(ctxText || '')}`;
