function soThrRelookViewable(sceneId) {
    const v = soThrSceneView;
    return !!(v && v.id === sceneId && !v.plain && !v.fellBack);
}
// → { error:'off' } | { busy:true } | { failed: why, text, token } | { cancelled:true, token } | { trial:true, token } | { pending:true, token }。
