// { adopted:true } | { outcome:{ failed, text } } = 一次的结局；{ wait: 节点 } / { writing:{ n, sec } } / { checking:true } = 指定那一行。
// 查看层没在看这个场景 / 旗关 = 什么都不做。
function soThrRelookRowPaint(sceneId, state) {
    if (!soThrRelookOn() || !win) return;
    const v = soThrSceneView;
    if (!v || v.id !== sceneId) return;
    const row = win.querySelector('#so-thr-scene-look-row');
    if (!row) return;
    const T = THEATER_RELOOK_TEXT;
    row.hidden = !!(v.plain || v.fellBack);
    const item = soThrSceneGet(sceneId);
    const fl = soThrRelookFlights.get(sceneId) || null;
    const busy = !!fl || !!v.trial;
    const btn = row.querySelector('#so-thr-scene-relook');
    btn.disabled = busy;
    btn.textContent = busy ? T.btnBusy : T.btn;
    const n = (item && Array.isArray(item.looks)) ? item.looks.length : 0;
    const act = soThrRelookActive(item);
    const stepEl = row.querySelector('#so-thr-scene-look-step');
    stepEl.hidden = n === 0;
    row.querySelector('#so-thr-scene-look-n').textContent = n ? T.step(act + 2, n + 1) + (act === -1 ? ' · ' + T.original : '') : '';
    row.querySelector('#so-thr-scene-look-prev').disabled = busy || act <= -1;
    row.querySelector('#so-thr-scene-look-next').disabled = busy || act >= n - 1;
    const line = row.querySelector('#so-thr-scene-look-line');
    line.textContent = '';
    const st = (state && typeof state === 'object') ? state : null;
    if (st && st.outcome && st.outcome.failed) {
        const t = document.createElement('span');
        t.textContent = T.notAdopted(String(st.outcome.text || st.outcome.failed));
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'so-thr-scene-mini';
        b.id = 'so-thr-scene-look-retry';
        b.textContent = THEATER_WAIT_COPY.retry;
        b.disabled = busy;
        line.append(t, ' ', b);
    } else if (st && st.adopted) line.textContent = T.adopted;
    else if (st && st.wait && typeof st.wait === 'object' && st.wait.nodeType === 1) line.appendChild(st.wait);
    else if (st && st.writing) line.textContent = T.writing(Number(st.writing.n) || 0, Number(st.writing.sec) || 0);
    else if (st && st.checking) line.textContent = T.checking;
    else if (fl && fl.waiting) line.appendChild(fl.waiting.el);
    else if (fl) line.textContent = T.writing(fl.chars, Math.round((Date.now() - fl.t0) / 1000));
    else if (v.trial) line.textContent = T.checking;
    else if (item && soThrRelookThin(soThrRelookMeasure(soThrSceneMerge(item)))) line.textContent = T.thin;
    line.hidden = !line.firstChild;
}

/* —— 💬 微谕 · Lane B 的十一块（tests/unit/_weiyu/<name>.js 原样拼入；改块文件、再跑 tests/unit/_weiyu/_splice.mjs，绝不手改这里的拷贝）—— */
/* <<WEIYU:model>> */
// [WEIYU] model — spliced verbatim into index.js by the join plan; edit HERE, re-splice, never hand-edit the copy.
//
// 微谕's phone state is ONE plain JSON object (schema v1, add-only keys). Shapes:
//   State  { v:1, booted, seq, people:{[pid]:Person}, chats:{[cid]:Chat}, opts:{steal, sync, tell, motion?, menu?, keep?, meterLine?}, deltas:Delta[], alts?:object|null }
//   Person { id, name, idLine?, sig?, area?, extra?:1, main?:1, gone?:1, remark?, blocked?:1 }   pid 'me' = the player's character
//            gone = removed from the contacts (删除联系人, only the person): the tombstone {id, name, gone:1, main?} that renders
//            their old lines (soWyDeletePerson)
//            remark = the player's 备注 for them (≤ 60; the phone shows it, NO model ever reads it — soWyShownName) · blocked = 拉黑
//            (soWySetBlocked: their new lines in his private chat with them land refused; the brief tells the model)
//            origin?: 'story'|'new' · about? = a person added by hand (2026-11-21, soWyAcAdd): 故事里的人 / 故事外的新人 and the 人物说明
//            (only for the AI — soWyBrief prints them behind args.ac); absent on everyone else
//   Chat   { id, type:'group'|'dm', name?, kind?, members:pid[], count?, notice?, why?, floor?:number|null,
//            muted?:1, dissolved?:1, msgs:Msg[], read:mid|null, sum?:{text, through, at, next?}, rank?:number, own?:1, closed?:1, pin?:1 }
//            rank = list place at 开机 · own = a group the player made (its 由来 is worded per audience, soWyChatWhy)
//            closed = a group a removed contact left with fewer than two members: read-only history (soWyChatClosed)
//            pin = 置顶 (the screen's list only, soWyScreenChats; soWyChatList keeps its order)
//   Msg    { id, t, u?, v, sec?, dur?, em?, q?:{u, v}, to?, k?, who?, targets?, prev?, added?, b, src, ai?:1, in:0|1, d?,
//            card?:{k, title, sub?, pid?}, fwd?:{from, lines:{name, v}[]}, refused?:1 }
//            card / fwd ride on t 'text' ONLY, v = the readable fallback (soWyCardText / soWyFwdText) — an older build keeps the key and
//            shows v as a plain bubble · refused = a blocked person's line in the player's private chat with them (behind 偷看)
//            phase 2 (2026-11-17): call?:{mode, st, dur?, gist?} (+ to = the callee) · pay?:{amt?, note?, to, mark?} · ans?:{ref, res, note?} —
//            t 'text' too, one of them per line (soWyCallNorm / soWyPayNorm / soWyAnsNorm) · pend?: n = how many landed requests showed this
//            line in the pending-state block (soWyPendingItems stops at 2). Person: blockNote?: 1 = a fresh block not yet shown to the story.
// Rules: ids are code-made (soWyNewId) and never reused inside one ST chat; AI-supplied strings are never used as object keys
// (look people up by name through soWyFindPerson); reducers mutate the state they are given — a caller that needs all-or-nothing
// works on soWyClone(state) and commits only on success. Unknown keys always survive a read–write round trip.

const THEATER_WEIYU_SCHEMA = 1;
const THEATER_WEIYU_ME = 'me';
const THEATER_WEIYU_TYPES = ['text', 'emoji', 'voice', 'photo', 'video', 'nudge', 'recall', 'sys', 'time'];
const THEATER_WEIYU_EVENTS = ['create', 'join', 'leave', 'rename', 'notice', 'dissolve'];
const THEATER_WEIYU_KINDS = ['friends', 'class', 'club', 'event'];
const THEATER_WEIYU_UNSAFE_IDS = ['__proto__', 'constructor', 'prototype'];

function soWyOwn(o, k) {
    return !!o && typeof o === 'object' && Object.prototype.hasOwnProperty.call(o, k);
}

function soWyIsObj(x) {
    return !!x && typeof x === 'object' && !Array.isArray(x);
}

// Copies the keys of `src` that `dst` does not have yet (unknown keys survive); unsafe keys are never copied.
function soWyKeepExtra(src, dst) {
    for (const k of Object.keys(src)) {
        if (THEATER_WEIYU_UNSAFE_IDS.includes(k) || soWyOwn(dst, k)) continue;
        dst[k] = src[k];
    }
    return dst;
}

function soWyDefaultOpts() {
    return { steal: false, sync: false, tell: false };
}

// Option keys this build no longer has. `period` = 「这个世界没有手机」, removed 2026-11-15 (Prince) before it ever shipped; a phone
// stored with it still loads, the key is dropped (load, reset, 开机's carry-over) instead of being carried like an unknown newer key.
const THEATER_WEIYU_OPTS_RETIRED = ['period'];

// The options a fresh phone takes over from an old one (reset, 开机): the defaults, then every stored key but the retired ones.
function soWyOptsCarry(opts) {
    const out = Object.assign(soWyDefaultOpts(), soWyIsObj(opts) ? JSON.parse(JSON.stringify(opts)) : {});
    for (const k of THEATER_WEIYU_OPTS_RETIRED) delete out[k];
    return out;
}

function soWyEmpty(meName, seq) {
    const n = Number(seq);
    return {
        v: THEATER_WEIYU_SCHEMA, booted: false, seq: Number.isFinite(n) && n > 0 ? Math.floor(n) : 0,
        people: { [THEATER_WEIYU_ME]: { id: THEATER_WEIYU_ME, name: String(meName == null ? '' : meName) } },
        chats: {}, opts: soWyDefaultOpts(), deltas: [],
    };
}

function soWyIsForeign(raw) {
    return soWyIsObj(raw) && Number(raw.v) > THEATER_WEIYU_SCHEMA;
}

// Numeric part of a code-made id ('m10' → 36); 0 for anything else.
function soWyIdNum(id) {
    const m = /^[a-z]([0-9a-z]+)$/.exec(String(id == null ? '' : id));
    if (!m) return 0;
    const n = parseInt(m[1], 36);
    return Number.isFinite(n) ? n : 0;
}

// Does `x` (a stored delta list / alternatives object) carry the string `id` anywhere as a value? (soWyNorm's empty-group clean-up)
function soWyMentions(x, id) {
    try {
        return x != null && JSON.stringify(x).includes(JSON.stringify(String(id)));
    } catch (e) {
        return true;
    }
}

function soWyNorm(raw, meName) {
    let src;
    try {
        if (!soWyIsObj(raw)) return null;
        src = JSON.parse(JSON.stringify(raw));
    } catch (e) {
        return null;
    }
    if (!soWyIsObj(src) || Number(src.v) !== THEATER_WEIYU_SCHEMA) return null;
    if (!soWyIsObj(src.people) || !soWyIsObj(src.chats)) return null;
    let top = 0;
    const out = { v: THEATER_WEIYU_SCHEMA, booted: !!src.booted, seq: 0, people: {}, chats: {}, opts: soWyDefaultOpts(), deltas: [] };
    // people
    for (const k of Object.keys(src.people)) {
        const p = src.people[k];
        if (THEATER_WEIYU_UNSAFE_IDS.includes(k) || !soWyIsObj(p) || p.id !== k) continue;
        if (k === THEATER_WEIYU_ME) continue;
        if (typeof p.name !== 'string' || !p.name.trim()) continue;
        out.people[k] = soWyKeepExtra(p, { id: k, name: p.name });
        top = Math.max(top, soWyIdNum(k));
    }
    const me = soWyIsObj(src.people[THEATER_WEIYU_ME]) && src.people[THEATER_WEIYU_ME].id === THEATER_WEIYU_ME ? src.people[THEATER_WEIYU_ME] : null;
    const myName = typeof meName === 'string' && meName.trim() ? meName : (me && typeof me.name === 'string' ? me.name : '');
    out.people = Object.assign({ [THEATER_WEIYU_ME]: soWyKeepExtra(me || {}, { id: THEATER_WEIYU_ME, name: myName }) }, out.people);
    // chats
    for (const k of Object.keys(src.chats)) {
        const c = src.chats[k];
        if (THEATER_WEIYU_UNSAFE_IDS.includes(k) || !soWyIsObj(c) || c.id !== k) continue;
        if (c.type !== 'group' && c.type !== 'dm') continue;
        const members = [];
        for (const pid of Array.isArray(c.members) ? c.members : []) {
            if (typeof pid === 'string' && soWyOwn(out.people, pid) && !members.includes(pid)) members.push(pid);
        }
        const msgs = [];
        for (const m of Array.isArray(c.msgs) ? c.msgs : []) {
            if (!soWyIsObj(m) || !THEATER_WEIYU_TYPES.includes(m.t) || typeof m.id !== 'string' || !m.id) continue;
            if (msgs.some((x) => x.id === m.id)) continue;
            msgs.push(soWyKeepExtra(m, {}));
            top = Math.max(top, soWyIdNum(m.id), soWyIdNum(m.b), soWyIdNum(m.d));
        }
        // an empty group of exactly two people holds nothing (the start-up shell of a two-member group, owner's report 2026-11-16 —
        // such a group is now built as the pair's private chat): dropped here, saved with the next commit. Never when it has any
        // message, when it states a head count above two (人数：41 — a quiet class group), or when a delta / alternative mentions it.
        if (c.type === 'group' && members.length === 2 && !msgs.length && !(Number(c.count) > 2) && !soWyMentions(src.deltas, k) && !soWyMentions(src.alts, k)) {
            top = Math.max(top, soWyIdNum(k));
            continue;
        }
        const read = typeof c.read === 'string' && msgs.some((m) => m.id === c.read) ? c.read : null;
        const chat = soWyKeepExtra(c, { id: k, type: c.type, members, msgs, read });
        if ('sum' in chat && !(soWyIsObj(chat.sum) && typeof chat.sum.text === 'string')) delete chat.sum;
        out.chats[k] = chat;
        top = Math.max(top, soWyIdNum(k));
    }
    // options, deltas, alternatives
    if (soWyIsObj(src.opts)) {
        for (const k of Object.keys(out.opts)) if (typeof src.opts[k] === 'boolean') out.opts[k] = src.opts[k];
        soWyKeepExtra(src.opts, out.opts);
        for (const k of THEATER_WEIYU_OPTS_RETIRED) delete out.opts[k];
    }
    if (Array.isArray(src.deltas)) {
        out.deltas = src.deltas.filter(soWyIsObj);
        for (const d of out.deltas) top = Math.max(top, soWyIdNum(d.id));
    }
    if ('alts' in src) out.alts = soWyIsObj(src.alts) ? src.alts : null;
    const seq = Number(src.seq);
    out.seq = Math.max(Number.isFinite(seq) && seq > 0 ? Math.floor(seq) : 0, top);
    return soWyKeepExtra(src, out);
}

function soWyClone(state) {
    return JSON.parse(JSON.stringify(state));
}

function soWyNewId(state, prefix) {
    const n = Number(state.seq);
    state.seq = (Number.isFinite(n) && n > 0 ? Math.floor(n) : 0) + 1;
    return String(prefix) + state.seq.toString(36);
}

function soWyPerson(state, pid) {
    return state && soWyOwn(state.people, pid) && soWyIsObj(state.people[pid]) ? state.people[pid] : null;
}

function soWyChat(state, cid) {
    return state && soWyOwn(state.chats, cid) && soWyIsObj(state.chats[cid]) ? state.chats[cid] : null;
}

function soWyNameKey(s) {
    let t = String(s == null ? '' : s).trim();
    for (let i = 0; i < 3; i++) {
        const before = t;
        t = t.replace(/^[@＠]\s*/, '').trim();
        const m = /^\*\*([\s\S]+)\*\*$/.exec(t);
        if (m) t = m[1].trim();
        if (t === before) break;
    }
    return t.replace(/\s+/g, ' ');
}

function soWyFindPerson(state, name) {
    const key = soWyNameKey(name);
    if (!key || !state || !soWyIsObj(state.people)) return null;
    const me = soWyPerson(state, THEATER_WEIYU_ME);
    if (me && soWyNameKey(me.name) === key) return THEATER_WEIYU_ME;
    for (const pid of Object.keys(state.people)) {
        if (pid === THEATER_WEIYU_ME) continue;
        const p = soWyPerson(state, pid);
        // a removed contact (gone: 1, 删除联系人) is never found by name: a later person of that name is a NEW contact
        if (p && p.gone !== 1 && soWyNameKey(p.name) === key) return pid;
    }
    return null;
}

function soWyClip(s, n) {
    const a = Array.from(String(s == null ? '' : s).trim());
    return a.length > n ? a.slice(0, n).join('') : a.join('');
}

// The length of what the player typed, as every ceiling counts it: code points of the trimmed text (an emoji = 1). The screen's over-line
// and the store's refusal both use it, so they agree on "over" (length limits 2026-11-21).
function soWyLen(s) {
    return Array.from(String(s == null ? '' : s).trim()).length;
}

function soWyAddPerson(state, o) {
    const src = soWyIsObj(o) ? o : {};
    const name = soWyNameKey(src.name);
    if (!name) return null;
    const known = soWyFindPerson(state, name);
    const fields = { idLine: 40, sig: 80, area: 80 };
    if (known) {
        const p = soWyPerson(state, known);
        for (const f of Object.keys(fields)) {
            if (p[f] == null && typeof src[f] === 'string' && src[f].trim()) p[f] = soWyClip(src[f], fields[f]);
        }
        return known;
    }
    const pid = soWyNewId(state, 'p');
    const p = { id: pid, name: soWyClip(name, 24) };
    for (const f of Object.keys(fields)) if (typeof src[f] === 'string' && src[f].trim()) p[f] = soWyClip(src[f], fields[f]);
    if (src.extra) p.extra = 1;
    state.people[pid] = p;
    return pid;
}

function soWyAddChat(state, o) {
    const src = soWyIsObj(o) ? o : {};
    if (src.type !== 'group' && src.type !== 'dm') return null;
    const members = [];
    for (const pid of Array.isArray(src.members) ? src.members : []) {
        if (soWyPerson(state, pid) && !members.includes(pid)) members.push(pid);
    }
    if (src.type === 'dm' && members.length !== 2) return null;
    const cid = soWyNewId(state, 'c');
    const chat = { id: cid, type: src.type };
    if (typeof src.name === 'string' && src.name.trim()) chat.name = soWyClip(src.name, 40);
    if (THEATER_WEIYU_KINDS.includes(src.kind)) chat.kind = src.kind;
    chat.members = members;
    const count = Number(src.count);
    if (Number.isFinite(count) && count > 0) chat.count = Math.floor(count);
    if (typeof src.notice === 'string' && src.notice.trim()) chat.notice = soWyClip(src.notice, 200);
    if (typeof src.why === 'string' && src.why.trim()) chat.why = soWyClip(src.why, 120);
    if (src.floor === null) chat.floor = null;
    else if (Number.isFinite(Number(src.floor)) && src.floor !== '' && src.floor !== undefined) chat.floor = Math.floor(Number(src.floor));
    chat.msgs = [];
    chat.read = null;
    state.chats[cid] = chat;
    return cid;
}

function soWyIsMine(chat) {
    return !!chat && Array.isArray(chat.members) && chat.members.includes(THEATER_WEIYU_ME);
}

// Owner's rule 2026-11-16: a one-to-one private chat of the player and one other person offers no 「让他们接着聊」 (a 'more' call)
// while 抢话 is off — there the only one who could keep talking is that one person alone, or the model writing the player's side.
// With 抢话 on (opts.steal === true) it is offered as before; groups (any membership) and private chats the player only watches keep
// it either way. A two-member 建群 is stored as a 'dm', so it follows the same rule. Read by the chat screen and by soWyCall.
function soWyMoreBarred(state, chat) {
    if (!soWyIsObj(chat) || chat.type !== 'dm' || !Array.isArray(chat.members) || chat.members.length !== 2 || !chat.members.includes(THEATER_WEIYU_ME)) return false;
    if (soWyDmBlocked(state, chat)) return true;   // his private chat with a contact he blocked: every line of theirs would be refused
    return !(soWyIsObj(state) && soWyIsObj(state.opts) && state.opts.steal === true);
}

// More functions phase 1 slice B (root's ruling 2026-11-17): his one-to-one private chat with a contact he BLOCKED (soWyBlocked) — sending
// there is barred (soWyCanSendIn false: the phone shows a notice with 「解除拉黑」 instead of the input; the flow refuses before any call),
// and so are 「让他们接着聊」 (soWyMoreBarred) and 重新生成 (flow 'regen'). Groups with that person are unaffected.
function soWyDmBlocked(state, chat) {
    if (!soWyIsObj(chat) || chat.type !== 'dm' || !Array.isArray(chat.members) || chat.members.length !== 2 || !chat.members.includes(THEATER_WEIYU_ME)) return false;
    const other = chat.members.find((pid) => pid !== THEATER_WEIYU_ME);
    const p = soWyIsObj(state) && soWyIsObj(state.people) ? state.people[other] : null;
    return soWyIsObj(p) && p.blocked === 1;
}

// A group the player made carries the marker own:1 instead of a 由来 text — each audience words it: the phone shows the player
// THEATER_WEIYU_TEXT.howOwn, a model reads `model` with the owner's name (the writer is not the player). `legacy` = the text
// older builds stored as `why`; such a phone still reads as the player's own group (nothing is rewritten).
// DRAFT wording (`model`) — reaches the writer through soWyBrief and the note.
const THEATER_WEIYU_OWN_WHY = { legacy: '你自己建的群。', model: '{me}自己建的群。' };

function soWyChatOwn(chat) {
    if (!soWyIsObj(chat) || chat.type !== 'group') return false;
    return chat.own === 1 || (typeof chat.why === 'string' && chat.why.trim() === THEATER_WEIYU_OWN_WHY.legacy);
}

// The 由来 as written for a model: the owner named for a player-made group, else the stored text; '' when there is none.
function soWyChatWhy(state, chat) {
    if (!soWyIsObj(chat)) return '';
    if (soWyChatOwn(chat)) {
        const p = soWyPerson(state, THEATER_WEIYU_ME);
        const n = p && typeof p.name === 'string' ? p.name.trim() : '';
        return THEATER_WEIYU_OWN_WHY.model.split('{me}').join(n || '我');
    }
    return typeof chat.why === 'string' && chat.why.trim() ? chat.why : '';
}

function soWyIsEmojiOnly(s) {
    const t = String(s == null ? '' : s).trim();
    if (!t) return false;
    const pics = t.match(/\p{Extended_Pictographic}/gu) || [];
    const rest = t.replace(/[\p{Extended_Pictographic}\p{Emoji_Modifier}\p{Variation_Selector}\s]/gu, '')
        .split(String.fromCharCode(0x200d)).join('');
    return pics.length >= 1 && pics.length <= 3 && rest === '';
}

// ---- the card message and the forward (more functions phase 1, owner's go 2026-11-17; study
// docs/superpowers/specs/2026-11-17-weiyu-more-functions-feasibility.md, "Shared mechanisms" A and section 7 option C) ----------------
// Both are {t: 'text', u, v: <readable fallback>, card | fwd} — NEVER a new t: an older build's soWyNorm deletes a message whose t it
// does not know, but keeps unknown keys, so with t 'text' it shows v as a plain bubble (weiyu-fn-card.test.mjs proves it on the previous
// build's verbatim normaliser). soWyAddMsg normalises both keys; every reader goes through soWyCardNorm / soWyFwdNorm.
//   card = {k: 'loc'|'file'|'link'|'contact'|'music', title, sub?, pid?}   pid only on a 名片 of someone on the phone (title = his name
//          then, stored, so the card keeps rendering after he is removed)
//   fwd  = {from: <the source chat's title>, lines: [{name, v}]}   1–6 lines, a snapshot made by soWyForward (never by a model)
const THEATER_WEIYU_CARD_WORDS = Object.freeze({ loc: '位置', file: '文件', link: '链接', contact: '名片', music: '音乐' });
const THEATER_WEIYU_CARD_MAX = Object.freeze({ title: 40, sub: 60 });
// The player's ceilings, code points (soWyLen): over one = refused visibly, never cut; AI text keeps CARD_MAX / EV_MAX / CALL_CAP (length limits 2026-11-21)
const THEATER_WEIYU_TYPED_MAX = Object.freeze({ text: 4000, title: 120, sub: 300, amt: 40, note: 200, group: 40 });
// name 40 (was 24; adding contacts by hand 2026-11-21): a typed name may have 40 characters and must not be cut in a forward's snapshot; only
// typed names exceed 24, so no stored forward reads differently.
const THEATER_WEIYU_FWD_MAX = Object.freeze({ lines: 6, from: 40, name: 40, v: 120, text: 300 });

// One line, single-spaced, trimmed.
function soWyLine1(s) {
    return String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
}

// The read cap is the PLAYER's ceiling (120 / 300): an AI card is cut to the model ceiling CARD_MAX in parse.js before it gets here.
function soWyCardNorm(card) {
    if (!soWyIsObj(card) || typeof card.k !== 'string' || !soWyOwn(THEATER_WEIYU_CARD_WORDS, card.k)) return null;
    const title = soWyClip(soWyLine1(card.title), THEATER_WEIYU_TYPED_MAX.title);
    if (!title) return null;
    const out = { k: card.k, title };
    const sub = soWyClip(soWyLine1(card.sub), THEATER_WEIYU_TYPED_MAX.sub);
    if (sub) out.sub = sub;
    if (card.k === 'contact' && typeof card.pid === 'string' && card.pid && !THEATER_WEIYU_UNSAFE_IDS.includes(card.pid)) out.pid = card.pid;
    return out;
}

// The readable fallback: 「[位置] 城南旧书店 · 二楼靠窗那桌」 ('' for a junk card).
function soWyCardText(card) {
    const c = soWyCardNorm(card);
    return c ? '[' + THEATER_WEIYU_CARD_WORDS[c.k] + '] ' + c.title + (c.sub ? ' · ' + c.sub : '') : '';
}

function soWyFwdNorm(fwd) {
    if (!soWyIsObj(fwd) || !Array.isArray(fwd.lines)) return null;
    const M = THEATER_WEIYU_FWD_MAX;
    const lines = [];
    for (const l of fwd.lines) {
        if (!soWyIsObj(l)) continue;
        const v = soWyClip(soWyLine1(l.v), M.v);
        if (!v) continue;
        lines.push({ name: soWyClip(soWyLine1(l.name), M.name), v });
        if (lines.length >= M.lines) break;
    }
    return lines.length ? { from: soWyClip(soWyLine1(fwd.from), M.from), lines } : null;
}

// The readable fallback: 「[转发「204干饭群」] 阿杰：…／白露：…」 (≤ 300; '' for a junk forward).
function soWyFwdText(fwd) {
    const f = soWyFwdNorm(fwd);
    if (!f) return '';
    const body = f.lines.map((l) => (l.name ? l.name + '：' : '') + l.v).join('／');
    return soWyClip((f.from ? '[转发「' + f.from + '」] ' : '[转发] ') + body, THEATER_WEIYU_FWD_MAX.text);
}

// A message in readable words, the way a forward copies it and the search shows it: a card / forward its fallback, a voice note / photo /
// video its words with the kind in front, text / emoji as they are ('' when it has none).
function soWyMsgPlain(m) {
    if (!soWyIsObj(m)) return '';
    if (m.t === 'text') {
        const card = soWyCardText(m.card);
        if (card) return card;
        const fwd = soWyFwdText(m.fwd);
        if (fwd) return fwd;
    }
    const v = soWyLine1(m.v);
    if (!v) return '';
    const pre = { voice: '[语音] ', photo: '[照片] ', video: '[视频] ' }[m.t];
    return pre ? pre + v : v;
}

// ---- calls and transfers (more functions phase 2 slice A, owner's go 2026-11-17; study §1 A + C and §4 A + C; kill switch
// ENABLE_THR_WEIYU_EVENTS in the join — these STATE helpers are flag-free so a stored line always reads) -----------------------------------
// Like the card: {t: 'text', u, v: <readable fallback>, <key>} — never a new t (an older build keeps the key and shows v).
//   call = {mode: 'voice'|'video', st: 'missed'|'cancel'|'reject'|'done', dur?, gist?}   on the CALLER's line; the callee = msg.to (a private
//          chat's other member). dur ('m:ss' / 'h:mm:ss') and gist (≤ 80) only on a connected call. Private chats only.
//   pay  = {amt?, note?, to, mark?}   a transfer; amt = free text (no number when missing — never a default), note = 附言 — his ≤ 40 / 200
//          (THEATER_WEIYU_TYPED_MAX, refused over), a character's ≤ 12 / 60 (EV_MAX, cut in parse.js),
//          to = the recipient's pid (the other member), mark = the player's manual 当作已收 / 已退 on a transfer TO A CHARACTER (soWyPayMark).
//   ans  = {ref, res: 'taken'|'back', note?}   an answer (收款 / 退回) to the transfer `ref` of the same chat.
// No wallet, no balance, no arithmetic. A transfer's STATUS IS DERIVED (soWyPayStatus) — never stored on it: open until a LATER line of the
// chat answers it; with no answer, `mark`; before the chat's summary boundary (soWySumView) = expired. So delete / undo / regenerate /
// story-sync undo / delete-chat reopen or remove it by construction.
const THEATER_WEIYU_CALL_KIND = Object.freeze({ voice: '语音通话', video: '视频通话' });
const THEATER_WEIYU_CALL_ST = Object.freeze({ missed: '未接', cancel: '已取消', reject: '已拒绝', done: '已接通' });
const THEATER_WEIYU_ANS_WORDS = Object.freeze({ taken: '已收款', back: '已退回' });
const THEATER_WEIYU_EV_MAX = Object.freeze({ gist: 80, amt: 12, note: 60 });

// The live call scene (2026-11-18) adds, on the SAME call key (additive; a record without them reads exactly as before):
//   st 'live' (only his own call, while it is connected — never a status a model line can produce) · at = connect time (ms) · turns =
//   [{u: pid, lines: [{tags?, text}], visual?, at?}] on 'live' and on a 'done' that came from a live call · end = 'me' | 'them' | 'cut' on
//   such a 'done' · why = her reason on a 'missed' / 'reject' (拒接｜原因).
function soWyCallNorm(call) {
    if (!soWyIsObj(call) || !soWyOwn(THEATER_WEIYU_CALL_KIND, call.mode)) return null;
    const live = call.st === 'live';
    if (!live && !soWyOwn(THEATER_WEIYU_CALL_ST, call.st)) return null;
    const out = { mode: call.mode, st: call.st };
    if (call.st === 'done') {
        if (typeof call.dur === 'string' && /^\d{1,3}:\d{2}(:\d{2})?$/.test(call.dur)) out.dur = call.dur;
        const gist = soWyClip(soWyLine1(call.gist), THEATER_WEIYU_EV_MAX.gist);
        if (gist) out.gist = gist;
    }
    if (live || (call.st === 'done' && Array.isArray(call.turns))) {
        if (typeof call.at === 'number' && Number.isFinite(call.at)) out.at = call.at;
        if (call.st === 'done' && THEATER_WEIYU_CALL_ENDS.includes(call.end)) out.end = call.end;
        out.turns = (Array.isArray(call.turns) ? call.turns : []).map(soWyCallTurnNorm).filter(Boolean);
    }
    if (call.st === 'missed' || call.st === 'reject') {
        const why = soWyClip(soWyLine1(call.why), THEATER_WEIYU_CALL_CAP.why);
        if (why) out.why = why;
    }
    return out;
}

// 「[语音通话] 未接」 · 「[视频通话] 通话时长 12:07」 · 「[语音通话] 已接通」 · 「[语音通话] 通话中」 (live) ('' for a junk call). The gist is not in
// the fallback (the phone keeps it behind 偷听).
function soWyCallText(call) {
    const c = soWyCallNorm(call);
    if (!c) return '';
    if (c.st === 'live') return '[' + THEATER_WEIYU_CALL_KIND[c.mode] + '] ' + THEATER_WEIYU_CALL_LIVE;
    return '[' + THEATER_WEIYU_CALL_KIND[c.mode] + '] ' + (c.st === 'done' && c.dur ? '通话时长 ' + c.dur : THEATER_WEIYU_CALL_ST[c.st]);
}

// ---- the live call scene (call scene slice A, 2026-11-18; probe gm-callscene; kill switch ENABLE_THR_WEIYU_CALLSCENE in the join — these
// STATE helpers are flag-free, so a stored call always reads) -----------------------------------------------------------------------------
// While connected, the call is ONE message of his private chat: {t: 'text', u: 'me', to: her, v: '[语音通话] 通话中', call: {mode, st: 'live',
// at, turns}}; hung up → st 'done' + dur (m:ss; his hang-up = the real time, ≥ 0:01; her hang-up / a cut = real time, never shorter than its
// spoken lines take to say) + end, the turns KEPT (the transcript). Never a new t; schema 1.
//   soWyCallDur(ms) → 'm:ss' (h:mm:ss from one hour) · soWyCallTagLong(tag, mode) / soWyCallTagsOf(line, mode) → a tag over 12 characters is
//   "long" in a VOICE call only (owner 2026-11-18: a video's action tag is fine as written) — judged, never stored.
//   soWyCallLiveIdx(chat, mid?) → index of the live call (that mid, else the newest live one) | -1
//   soWyCallClose(msg, endAt | null, end) — st 'done', dur = endAt − at (null = up to the last turn), end; v follows. end 'me' (his
//   hang-up): that real time, at least 1 s (= the clock he watched). 'them' / 'cut': never shorter than soWyCallSpeakMs (the time its
//   spoken lines take to say).
//   soWyCallHangUp(state, cid, now) → mid | null — HIS hang-up of the live call there (zero calls; the UI commits).
//   soWyCallRedo(state, cid) → bool — drop HER last turn of the live call there (never the pick-up turn) so the UI can ask again (zero calls).
//   soWyCallTail(call) → the end of the transcript a TURN request ends on: her latest turn (its 画面 first in a VIDEO call, then her spoken
//     lines) and his line(s) after it, in order — [{k: 'pic' | 'her' | 'me', tags?, text}]; [] when she has no turn. soWyCallRead's echo.
//   soWyCallSettle(state, keep: {cid, mid} | null) → how many — every live call but `keep` = a call this page no longer runs (reload, another
//     ST chat): closed as ended, dur up to its last turn, end 'cut'.
const THEATER_WEIYU_CALL_LIVE = '通话中';
// lines = spoken lines a turn keeps · tag = a voice tag's length limit · tagMax = the reader's outer bound for a （） tag · said / visual / why =
// stored lengths · turns = transcript turns one request carries · logTarget / logOther = transcript lines a later log shows (that chat the
// target / not)
const THEATER_WEIYU_CALL_CAP = Object.freeze({ lines: 4, tag: 12, tagMax: 40, said: 300, visual: 300, why: 40, turns: 40, logTarget: 40, logOther: 12 });
const THEATER_WEIYU_CALL_ENDS = ['me', 'them', 'cut'];
// The speaking time of a call's transcript (playtest 2026-11-18: a hang-up in the pick-up reply read 0:00) — soWyCallSpeakMs, read by
// soWyCallClose for her hang-up and a cut (never for his: his record = his clock). ms per character: han = a CJK character / kana / hangul / digit (~4 a second, a syllable each) · latin = any other letter
// (~14 a second) · gap = added per spoken line (the pause between sentences / turns) · floor = the least a call with anything said lasts.
// Free: punctuation, spaces, emoji, symbols, a （…） / (…) bracket inside the words (tone / action), the leading tags (stored apart), 画面.
const THEATER_WEIYU_CALL_SPEAK = Object.freeze({ han: 250, latin: 70, gap: 500, floor: 1000 });

// cap = the read cap of the line's words (absent = CALL_CAP.said): soWyCallTurnNorm passes his ceiling for his lines, said for hers — her
// later turns are stored raw, so her lines must keep reading at 300 (never map this function bare: the index would land in cap)
function soWyCallLineNorm(l, cap = THEATER_WEIYU_CALL_CAP.said) {
    if (!soWyIsObj(l) || typeof l.text !== 'string') return null;
    const text = soWyClip(soWyLine1(l.text), cap);
    const tags = (Array.isArray(l.tags) ? l.tags : []).filter((t) => typeof t === 'string')
        .map((t) => soWyClip(soWyLine1(t), THEATER_WEIYU_CALL_CAP.tagMax)).filter(Boolean);
    if (!text && !tags.length) return null;
    const out = {};
    if (tags.length) out.tags = tags;
    out.text = text;
    return out;
}

function soWyCallTurnNorm(t) {
    if (!soWyIsObj(t) || typeof t.u !== 'string' || !t.u || THEATER_WEIYU_UNSAFE_IDS.includes(t.u)) return null;
    const cap = t.u === THEATER_WEIYU_ME ? THEATER_WEIYU_TYPED_MAX.text : THEATER_WEIYU_CALL_CAP.said;
    const lines = (Array.isArray(t.lines) ? t.lines : []).map((l) => soWyCallLineNorm(l, cap)).filter(Boolean);
    const visual = soWyClip(soWyLine1(t.visual), THEATER_WEIYU_CALL_CAP.visual);
    if (!lines.length && !visual) return null;
    const out = { u: t.u, lines };
    if (visual) out.visual = visual;
    if (typeof t.at === 'number' && Number.isFinite(t.at)) out.at = t.at;
    return out;
}

function soWyCallDur(ms) {
    const n = Math.floor(Number(ms) / 1000);
    const sec = Number.isFinite(n) && n > 0 ? n : 0;
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = sec % 60;
    const two = (x) => (x < 10 ? '0' : '') + x;
    return h ? h + ':' + two(m) + ':' + two(s) : m + ':' + two(s);
}

function soWyCallTagLong(tag, mode) {
    return mode === 'voice' && Array.from(String(tag == null ? '' : tag)).length > THEATER_WEIYU_CALL_CAP.tag;
}

function soWyCallTagsOf(line, mode) {
    const tags = soWyIsObj(line) && Array.isArray(line.tags) ? line.tags.filter((t) => typeof t === 'string') : [];
    return { short: tags.filter((t) => !soWyCallTagLong(t, mode)), long: tags.filter((t) => soWyCallTagLong(t, mode)) };
}

function soWyCallLiveIdx(chat, mid) {
    if (!soWyIsObj(chat) || !Array.isArray(chat.msgs)) return -1;
    const isLive = (m) => soWyIsObj(m) && m.t === 'text' && soWyIsObj(m.call) && m.call.st === 'live' && !!soWyCallNorm(m.call);
    if (typeof mid === 'string' && mid) {
        const i = soWyMsgIndex(chat, mid);
        return i >= 0 && isLive(chat.msgs[i]) ? i : -1;
    }
    for (let i = chat.msgs.length - 1; i >= 0; i--) if (isLive(chat.msgs[i])) return i;
    return -1;
}

// ms the spoken lines of a call's transcript take to say, both sides (THEATER_WEIYU_CALL_SPEAK); 0 when nothing was said. Pure, deterministic.
function soWyCallSpeakMs(call) {
    const S = THEATER_WEIYU_CALL_SPEAK;
    const turns = soWyIsObj(call) && Array.isArray(call.turns) ? call.turns : [];
    let ms = 0;
    for (const t of turns) {
        if (!soWyIsObj(t) || !Array.isArray(t.lines)) continue;
        for (const l of t.lines) {
            if (!soWyIsObj(l) || typeof l.text !== 'string') continue;
            let n = 0;
            for (const ch of Array.from(l.text.replace(/[（(][^（）()]*[）)]/g, ''))) {
                if (/[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}\p{N}]/u.test(ch)) n += S.han;
                else if (/\p{L}/u.test(ch)) n += S.latin;
            }
            if (n) ms += n + S.gap;
        }
    }
    return ms > 0 ? Math.max(ms, S.floor) : 0;
}

function soWyCallClose(m, endAt, end) {
    const call = m.call;
    const turns = Array.isArray(call.turns) ? call.turns : (call.turns = []);
    const lastAt = turns.map((t) => (soWyIsObj(t) && typeof t.at === 'number' && Number.isFinite(t.at) ? t.at : NaN)).filter(Number.isFinite).pop();
    const at = typeof call.at === 'number' && Number.isFinite(call.at) ? call.at : (lastAt === undefined ? 0 : lastAt);
    const stop = typeof endAt === 'number' && Number.isFinite(endAt) ? endAt : (lastAt === undefined ? at : lastAt);
    call.st = 'done';
    // HIS hang-up ('me'): the real time — what the panel's running clock showed him when he pressed it (playtest 2026-11-18: the record read
    // 0:10 against his 0:06) — but never 0:00 (at least 0:01). Any other end ('them' / 'cut'): never shorter than its spoken lines take to
    // say (a hang-up in the pick-up reply, a settle of a pick-up-only call: real time 0); there the panel freezes on this recorded value.
    call.dur = soWyCallDur(end === 'me' ? Math.max(stop - at, 1000) : Math.max(stop - at, soWyCallSpeakMs(call)));
    call.end = end;
    m.v = soWyCallText(call);
}

function soWyCallHangUp(state, cid, now) {
    const chat = soWyChat(state, cid);
    const i = soWyCallLiveIdx(chat);
    if (i < 0) return null;
    soWyCallClose(chat.msgs[i], Number(now), 'me');
    soWyTouch(state, cid);
    return chat.msgs[i].id;
}

function soWyCallRedo(state, cid) {
    const chat = soWyChat(state, cid);
    const i = soWyCallLiveIdx(chat);
    if (i < 0) return false;
    const turns = chat.msgs[i].call.turns;
    if (!Array.isArray(turns) || turns.length < 2 || !soWyIsObj(turns[turns.length - 1]) || turns[turns.length - 1].u === THEATER_WEIYU_ME) return false;
    turns.pop();
    return true;
}

function soWyCallTail(call) {
    const c = soWyCallNorm(call);
    const turns = c && Array.isArray(c.turns) ? c.turns : [];
    let i = turns.length - 1;
    while (i >= 0 && turns[i].u === THEATER_WEIYU_ME) i--;
    if (i < 0) return [];
    const out = [];
    if (c.mode === 'video' && turns[i].visual) out.push({ k: 'pic', text: turns[i].visual });
    for (const l of turns[i].lines) out.push(Object.assign({ k: 'her' }, l.tags ? { tags: l.tags.slice() } : {}, { text: l.text }));
    for (const t of turns.slice(i + 1)) for (const l of t.lines) out.push({ k: 'me', text: l.text });
    return out;
}

function soWyCallSettle(state, keep) {
    let n = 0;
    if (!soWyIsObj(state) || !soWyIsObj(state.chats)) return n;
    const k = soWyIsObj(keep) ? keep : {};
    for (const cid of Object.keys(state.chats)) {
        const chat = soWyChat(state, cid);
        if (!chat || !Array.isArray(chat.msgs)) continue;
        for (const m of chat.msgs) {
            if (!soWyIsObj(m) || m.t !== 'text' || !soWyIsObj(m.call) || m.call.st !== 'live' || !soWyCallNorm(m.call)) continue;
            if (cid === k.cid && m.id === k.mid) continue;
            soWyCallClose(m, null, 'cut');
            n++;
        }
    }
    return n;
}

// The read caps of a transfer / an answer are the PLAYER's ceilings (40 / 200): a character's is cut to EV_MAX in parse.js first.
function soWyPayNorm(pay) {
    if (!soWyIsObj(pay) || typeof pay.to !== 'string' || !pay.to || THEATER_WEIYU_UNSAFE_IDS.includes(pay.to)) return null;
    const out = {};
    const amt = soWyClip(soWyLine1(pay.amt), THEATER_WEIYU_TYPED_MAX.amt);
    if (amt) out.amt = amt;
    const note = soWyClip(soWyLine1(pay.note), THEATER_WEIYU_TYPED_MAX.note);
    if (note) out.note = note;
    out.to = pay.to;
    if (pay.mark === 'taken' || pay.mark === 'back') out.mark = pay.mark;
    return out;
}

// 「[转账 200] 奶茶钱」 · 「[转账] 奶茶钱」 · 「[转账 200]」 (the amount is shown as written; none = no number).
function soWyPayText(pay) {
    const amt = soWyClip(soWyLine1(soWyIsObj(pay) ? pay.amt : ''), THEATER_WEIYU_TYPED_MAX.amt);
    const note = soWyClip(soWyLine1(soWyIsObj(pay) ? pay.note : ''), THEATER_WEIYU_TYPED_MAX.note);
    return '[转账' + (amt ? ' ' + amt : '') + ']' + (note ? ' ' + note : '');
}

function soWyAnsNorm(ans) {
    if (!soWyIsObj(ans) || typeof ans.ref !== 'string' || !ans.ref || (ans.res !== 'taken' && ans.res !== 'back')) return null;
    const out = { ref: ans.ref, res: ans.res };
    const note = soWyClip(soWyLine1(ans.note), THEATER_WEIYU_TYPED_MAX.note);
    if (note) out.note = note;
    return out;
}

// 「[已收款] 行，两清」 · 「[已退回]」.
function soWyAnsText(ans) {
    const res = soWyIsObj(ans) && soWyOwn(THEATER_WEIYU_ANS_WORDS, ans.res) ? ans.res : '';
    if (!res) return '';
    const note = soWyClip(soWyLine1(ans.note), THEATER_WEIYU_TYPED_MAX.note);
    return '[' + THEATER_WEIYU_ANS_WORDS[res] + ']' + (note ? ' ' + note : '');
}

// The comparable form of an amount (follow-up (c), the duplicate-transfer guard): one line, no white space, full-width digits / point as
// ASCII, no currency sign in front, no 元 / 块 / 块钱 / 人民币 / rmb behind. '' stays '' (two transfers without an amount compare equal).
function soWyPayAmtKey(amt) {
    return soWyLine1(amt).replace(/\s+/g, '')
        .replace(/[０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xfee0)).replace(/．/g, '.')
        .replace(/^[¥￥$]+/, '').replace(/(?:块钱|元|块|人民币|rmb)$/i, '');
}

// Which event a stored line is: 'call' | 'pay' | 'ans' | '' (only on t 'text'; a card / forward is none of them).
function soWyEvKind(m) {
    if (!soWyIsObj(m) || m.t !== 'text') return '';
    if (soWyCallNorm(m.call)) return 'call';
    if (soWyPayNorm(m.pay)) return 'pay';
    if (soWyAnsNorm(m.ans)) return 'ans';
    return '';
}

function soWyAddMsg(state, cid, msg, meta) {
    const chat = soWyChat(state, cid);
    const src = soWyIsObj(msg) ? msg : {};
    if (!chat || !THEATER_WEIYU_TYPES.includes(src.t)) return null;
    const m = { id: soWyNewId(state, 'm'), t: src.t };
    if (typeof src.u === 'string') m.u = src.u;
    m.v = String(src.v == null ? '' : src.v);
    // a card or a forward rides on a text line only (it is never read as an emoji line); an empty v takes the readable fallback
    const card = m.t === 'text' ? soWyCardNorm(src.card) : null;
    const fwd = m.t === 'text' && !card ? soWyFwdNorm(src.fwd) : null;
    if (card) m.card = card;
    if (fwd) m.fwd = fwd;
    if ((card || fwd) && !m.v.trim()) m.v = card ? soWyCardText(card) : soWyFwdText(fwd);
    // a call / a transfer / an answer (phase 2): one key per line, the same rules as a card
    const plainText = m.t === 'text' && !card && !fwd;
    const call = plainText ? soWyCallNorm(src.call) : null;
    const pay = plainText && !call ? soWyPayNorm(src.pay) : null;
    const ans = plainText && !call && !pay ? soWyAnsNorm(src.ans) : null;
    if (call) m.call = call;
    if (pay) m.pay = pay;
    if (ans) m.ans = ans;
    if (!m.v.trim()) {
        if (call) m.v = soWyCallText(call);
        else if (pay) m.v = soWyPayText(pay);
        else if (ans) m.v = soWyAnsText(ans);
    }
    if (m.t === 'text' && !card && !fwd && !call && !pay && !ans && soWyIsEmojiOnly(m.v)) m.t = 'emoji';
    if (src.refused === 1) m.refused = 1;
    const sec = Number(src.sec);
    if (Number.isFinite(sec) && sec > 0) m.sec = Math.floor(sec);
    for (const f of ['dur', 'em', 'to', 'k', 'who', 'prev']) if (typeof src[f] === 'string') m[f] = src[f];
    if (soWyIsObj(src.q) && typeof src.q.u === 'string') m.q = { u: src.q.u, v: String(src.q.v == null ? '' : src.q.v) };
    for (const f of ['targets', 'added']) if (Array.isArray(src[f])) m[f] = src[f].filter((x) => typeof x === 'string');
    if (src.ai) m.ai = 1;
    const mt = soWyIsObj(meta) ? meta : {};
    m.b = String(mt.b == null ? '' : mt.b);
    m.src = String(mt.src == null ? '' : mt.src);
    if (typeof mt.d === 'string' && mt.d) m.d = mt.d;
    m.in = soWyIsMine(chat) || mt.wasIn ? 1 : 0;
    chat.msgs.push(m);
    return m.id;
}

function soWyApplyEvent(state, cid, ev, meta) {
    const chat = soWyChat(state, cid);
    const e = soWyIsObj(ev) ? ev : {};
    if (!chat || chat.type !== 'group' || chat.dissolved || chat.closed === 1 || !THEATER_WEIYU_EVENTS.includes(e.k)) return null;
    const who = typeof e.who === 'string' && soWyPerson(state, e.who) ? e.who : undefined;
    const wasIn = soWyIsMine(chat);
    const line = { t: 'sys', k: e.k, v: '' };
    if (who) line.who = who;
    if (e.k === 'join') {
        const targets = [];
        for (const pid of Array.isArray(e.targets) ? e.targets : []) {
            if (soWyPerson(state, pid) && !targets.includes(pid)) targets.push(pid);
        }
        const added = targets.filter((pid) => !chat.members.includes(pid));
        if (!added.length) return null;
        chat.members.push(...added);
        line.targets = targets;
        line.added = added;
    } else if (e.k === 'leave') {
        if (!who || !chat.members.includes(who)) return null;
        chat.members = chat.members.filter((pid) => pid !== who);
    } else if (e.k === 'rename' || e.k === 'notice') {
        const v = soWyClip(e.v, e.k === 'rename' ? 40 : 200);
        if (!v) return null;
        const f = e.k === 'rename' ? 'name' : 'notice';
        line.prev = typeof chat[f] === 'string' ? chat[f] : '';
        line.v = v;
        chat[f] = v;
    } else if (e.k === 'dissolve') {
        chat.dissolved = 1;
    }
    return soWyAddMsg(state, cid, line, Object.assign({}, soWyIsObj(meta) ? meta : {}, { wasIn }));
}

// Removes messages; sys lines are undone newest first (join → members in `added` go, leave → `who` comes back at the end,
// rename / notice → `prev`, dissolve → live again). A read mark on a removed line moves to the nearest earlier kept line.
function soWyUnapplyMsgs(state, cid, mids) {
    const chat = soWyChat(state, cid);
    if (!chat || !Array.isArray(mids)) return 0;
    const gone = new Set(mids.filter((x) => typeof x === 'string'));
    const hit = chat.msgs.filter((m) => gone.has(m.id));
    if (!hit.length) return 0;
    for (const m of hit.slice().reverse()) {
        if (m.t !== 'sys') continue;
        if (m.k === 'join' && Array.isArray(m.added)) chat.members = chat.members.filter((pid) => !m.added.includes(pid));
        else if (m.k === 'leave' && m.who && !chat.members.includes(m.who)) chat.members.push(m.who);
        else if (m.k === 'rename' || m.k === 'notice') {
            const f = m.k === 'rename' ? 'name' : 'notice';
            if (typeof m.prev === 'string' && m.prev) chat[f] = m.prev;
            else delete chat[f];
        } else if (m.k === 'dissolve') delete chat.dissolved;
    }
    if (chat.read && gone.has(chat.read)) {
        const i = chat.msgs.findIndex((m) => m.id === chat.read);
        let read = null;
        for (let j = i - 1; j >= 0; j--) if (!gone.has(chat.msgs[j].id)) { read = chat.msgs[j].id; break; }
        chat.read = read;
    }
    chat.msgs = chat.msgs.filter((m) => !gone.has(m.id));
    return hit.length;
}

function soWySize(state) {
    const json = JSON.stringify(state);
    let msgs = 0;
    const chats = soWyIsObj(state && state.chats) ? Object.keys(state.chats) : [];
    for (const cid of chats) msgs += Array.isArray(state.chats[cid].msgs) ? state.chats[cid].msgs.length : 0;
    return {
        bytes: new TextEncoder().encode(json).length, msgs, chats: chats.length,
        people: soWyIsObj(state && state.people) ? Object.keys(state.people).length : 0,
    };
}

// ---- Task 3: lists, read marks, the player's zero-call actions -------------------------------------------------------------

function soWyPersonName(state, pid, meWord) {
    if (pid === THEATER_WEIYU_ME && meWord) return meWord;
    const p = soWyPerson(state, pid);
    return p ? p.name : '?';
}

// soWyPersonName for the PHONE'S OWN wording (more functions phase 1 slice B): the remark first (soWyShownName). The screens pass it as
// the optional `nameOf` of soWyChatTitle / soWyPreview / soWySysText / soWyNudgeText; a request never does (those calls keep two
// arguments, so every model-facing text reads the real name — weiyu-fn-house pins it).
function soWyShownWord(state, pid, meWord) {
    if (pid === THEATER_WEIYU_ME && meWord) return meWord;
    return soWyPerson(state, pid) ? soWyShownName(state, pid) : '?';
}

function soWyChatTitle(state, chat, nameOf) {
    const nm = typeof nameOf === 'function' ? nameOf : soWyPersonName;
    if (!chat) return '';
    if (chat.type === 'group') return chat.name || '';
    const members = Array.isArray(chat.members) ? chat.members : [];
    if (members.includes(THEATER_WEIYU_ME)) {
        const other = members.find((pid) => pid !== THEATER_WEIYU_ME);
        return other ? nm(state, other) : '';
    }
    return members.map((pid) => nm(state, pid)).join(' ↔ ');
}

// Newest first by the largest message id of each chat (= its last message in normal order; an empty chat ranks by its own id).
// Root ruling (list order after 开机): a chat built by 开机 carries `rank` (soWyBootBuild) = its place in the reply, first written
// highest, every value ≤ the seq at boot — its src:'boot' lines are represented by that number, so any later line (send, hold, sync,
// regen: ids above the boot seq) moves it to the top as before. No (or a non-numeric) rank = the plain ranking (older data).
function soWyChatList(state) {
    if (!state || !soWyIsObj(state.chats)) return [];
    const rank = (cid) => {
        const c = state.chats[cid];
        const boot = typeof c.rank === 'number' && Number.isFinite(c.rank) ? c.rank : null;
        let top = boot == null ? 0 : boot;
        for (const m of Array.isArray(c.msgs) ? c.msgs : []) {
            if (boot != null && m && m.src === 'boot') continue;
            // a refused line (a blocked person's, behind 偷看) was never delivered: it moves nothing (gm-block "Product nits", root 2026-11-17)
            if (m && m.refused === 1) continue;
            top = Math.max(top, soWyIdNum(m && m.id));
        }
        return top || soWyIdNum(cid);
    };
    return Object.keys(state.chats).map((cid) => [cid, rank(cid), soWyIdNum(cid)])
        .sort((x, y) => (y[1] - x[1]) || (y[2] - x[2])).map((x) => x[0]);
}

function soWyReadIndex(chat) {
    if (!chat || !Array.isArray(chat.msgs) || typeof chat.read !== 'string') return -1;
    return chat.msgs.findIndex((m) => m && m.id === chat.read);
}

// A refused line (a blocked person's, soWyRefuses) never counts: it sits behind 偷看, it was not delivered.
function soWyCountsAsUnread(m) {
    return !!m && m.t !== 'time' && m.t !== 'sys' && m.src !== 'me' && m.refused !== 1;
}

function soWyUnread(chat) {
    if (!chat || !Array.isArray(chat.msgs)) return 0;
    let n = 0;
    for (let i = soWyReadIndex(chat) + 1; i < chat.msgs.length; i++) if (soWyCountsAsUnread(chat.msgs[i])) n++;
    return n;
}

function soWyTotalUnread(state) {
    if (!state || !soWyIsObj(state.chats)) return 0;
    let n = 0;
    for (const cid of Object.keys(state.chats)) if (!state.chats[cid].muted) n += soWyUnread(state.chats[cid]);
    return n;
}

// ---- @ (more functions phase 1, study section 5): ONE tokeniser for the bubble's highlight (ui soWyAtNodes), the list marker
// (soWyAtMe), "jump to the @" (soWyAtFirst) and who a line addresses (soWyAtOf) — so they always agree. Derived from the words every
// time, never stored (a rename cannot stale it).
// soWyAtSpans(state, text) → [{s} | {s, at: 1, name}]: "@" or "＠" followed by 所有人 or a person's name on the phone (removed contacts
// too — their old lines still highlight), longest name first; an unknown @name stays text. Consecutive text is one span.
function soWyAtSpans(state, text) {
    const s = String(text == null ? '' : text);
    const names = ['所有人'];
    for (const p of Object.values(state && soWyIsObj(state.people) ? state.people : {})) {
        if (p && typeof p.name === 'string' && p.name && !names.includes(p.name)) names.push(p.name);
    }
    names.sort((a, b) => b.length - a.length);
    const out = [];
    let buf = '';
    let i = 0;
    while (i < s.length) {
        if (s[i] === '@' || s[i] === '＠') {
            const rest = s.slice(i + 1);
            const hit = names.find((n) => rest.startsWith(n));
            if (hit) {
                if (buf) out.push({ s: buf });
                buf = '';
                out.push({ s: s[i] + hit, at: 1, name: hit });
                i += 1 + hit.length;
                continue;
            }
        }
        buf += s[i];
        i += 1;
    }
    if (buf) out.push({ s: buf });
    return out;
}

// soWyAtOf(state, chat, msg) → {ids: pid[], all: boolean} — the people a line @-s (in text order, once each; when `chat` is given, only
// its members) and whether it @-s 所有人. A card / forward / refused line addresses nobody (its v is a fallback, not words).
function soWyAtOf(state, chat, msg) {
    const out = { ids: [], all: false };
    if (!soWyIsObj(msg) || msg.refused === 1 || (msg.t === 'text' && (soWyCardNorm(msg.card) || soWyFwdNorm(msg.fwd) || soWyEvKind(msg)))) return out;
    const members = soWyIsObj(chat) && Array.isArray(chat.members) ? chat.members : null;
    for (const x of soWyAtSpans(state, msg.v)) {
        if (!x.at) continue;
        if (x.name === '所有人') { out.all = true; continue; }
        const pid = soWyFindPerson(state, x.name);
        if (pid && !out.ids.includes(pid) && (!members || members.includes(pid))) out.ids.push(pid);
    }
    return out;
}

// Does an unread line of a chat the player is in @ him (by name or 所有人)? The list marker T.atMe.
function soWyAtMe(state, chat) {
    return soWyAtFirst(state, chat) !== null;
}

// The id of the OLDEST unread line that @-s the player in a chat he is in (chat object or id), else null — "jump to the @".
function soWyAtFirst(state, chat) {
    const c = typeof chat === 'string' ? soWyChat(state, chat) : chat;
    if (!soWyIsMine(c) || !Array.isArray(c.msgs)) return null;
    for (let i = soWyReadIndex(c) + 1; i < c.msgs.length; i++) {
        const m = c.msgs[i];
        if (!soWyCountsAsUnread(m)) continue;
        const a = soWyAtOf(state, c, m);
        if (a.all || a.ids.includes(THEATER_WEIYU_ME)) return m.id;
    }
    return null;
}

function soWyMarkRead(state, cid) {
    const chat = soWyChat(state, cid);
    if (!chat) return false;
    const last = chat.msgs[chat.msgs.length - 1];
    const read = last ? last.id : null;
    if (chat.read === read) return false;
    chat.read = read;
    return true;
}

function soWySetMute(state, cid, on) {
    const chat = soWyChat(state, cid);
    if (!chat) return false;
    if (on) chat.muted = 1;
    else delete chat.muted;
    return true;
}

// What the player's character knows: he was a member when the line landed AND has read up to it (Stage 3 reads this).
function soWyKnown(chat, index) {
    if (!chat || !Array.isArray(chat.msgs)) return false;
    const m = chat.msgs[index];
    return !!m && m.in === 1 && index <= soWyReadIndex(chat);
}

// The phone's wording of a grey system line (modern, DRAFT); the player shows as 你.
function soWySysText(state, msg, nameOf) {
    if (!msg) return '';
    const nm = (pid) => (typeof nameOf === 'function' ? nameOf : soWyPersonName)(state, pid, '你');
    const who = msg.who ? nm(msg.who) : '';
    const list = (Array.isArray(msg.targets) && msg.targets.length ? msg.targets : (msg.added || [])).map(nm).join('、');
    switch (msg.k) {
        case 'join': return who ? who + ' 邀请 ' + list + ' 加入了群聊' : list + ' 加入了群聊';
        case 'leave': return (who || '有人') + ' 退出了群聊';
        case 'rename': return who ? who + ' 修改群名为「' + msg.v + '」' : '群名已修改为「' + msg.v + '」';
        case 'notice': return who ? who + ' 更新了群公告' : '群公告已更新';
        case 'dissolve': return who ? '群主 ' + who + ' 解散了这个群' : '这个群已解散';
        case 'create': return who ? who + ' 创建了群聊' : '群聊已创建';
        case 'friend': return THEATER_WEIYU_FRIEND_LINE; // soWyAddContact (the stored v is the same words, for older builds)
        default: return String(msg.v == null ? '' : msg.v);
    }
}

function soWyNudgeText(state, msg, nameOf) {
    if (!msg) return '';
    const nm = (pid) => (typeof nameOf === 'function' ? nameOf : soWyPersonName)(state, pid, '你');
    return nm(msg.u) + ' 拍了拍 ' + nm(msg.to) + (msg.v ? ' ' + msg.v : '');
}

// List-row preview of the last non-time line. Sentences that already name the person (recall / nudge / sys) get no prefix.
function soWyPreview(state, chat, nameOf) {
    const nm = typeof nameOf === 'function' ? nameOf : soWyPersonName;
    if (!chat || !Array.isArray(chat.msgs)) return '';
    if (chat.dissolved) return '该群已解散';
    let last = null;
    // a refused line (behind 偷看) is never the preview
    for (let i = chat.msgs.length - 1; i >= 0; i--) if (chat.msgs[i] && chat.msgs[i].t !== 'time' && chat.msgs[i].refused !== 1) { last = chat.msgs[i]; break; }
    if (!last) return '';
    if (last.t === 'sys') return soWySysText(state, last, nameOf);
    if (last.t === 'nudge') return soWyNudgeText(state, last, nameOf);
    if (last.t === 'recall') return nm(state, last.u, '你') + ' 撤回了一条消息';
    const body = { voice: '[语音]', photo: '[图片]', video: '[视频]' }[last.t] || String(last.v == null ? '' : last.v);
    const prefix = (chat.type === 'group' || !soWyIsMine(chat)) && last.u && last.u !== THEATER_WEIYU_ME;
    return prefix ? nm(state, last.u) + '：' + body : body;
}

function soWyTouch(state, cid) {
    let n = 0;
    for (const d of Array.isArray(state && state.deltas) ? state.deltas : []) {
        if (!soWyIsObj(d) || d.final || !Array.isArray(d.chats) || !d.chats.includes(cid)) continue;
        if (d.touched !== 1) n++;
        d.touched = 1;
    }
    return n;
}

function soWyOpenDm(state, pid) {
    if (pid === THEATER_WEIYU_ME || !soWyPerson(state, pid) || soWyGone(state, pid)) return null;
    for (const cid of Object.keys(state.chats)) {
        const c = state.chats[cid];
        if (c.type === 'dm' && c.members.length === 2 && c.members.includes(THEATER_WEIYU_ME) && c.members.includes(pid)) return cid;
    }
    return soWyAddChat(state, { type: 'dm', members: [THEATER_WEIYU_ME, pid] });
}

function soWyCreateGroup(state, pids, name) {
    const picked = [];
    for (const pid of Array.isArray(pids) ? pids : []) {
        if (pid !== THEATER_WEIYU_ME && soWyPerson(state, pid) && !picked.includes(pid)) picked.push(pid);
    }
    if (picked.length < 2) return null;
    // a TYPED name over his ceiling is refused, never cut (the code-made default name below is still cut by soWyAddChat, as before)
    if (typeof name === 'string' && soWyLen(name) > THEATER_WEIYU_TYPED_MAX.group) return null;
    const title = typeof name === 'string' && name.trim() ? name.trim() : picked.slice(0, 3).map((pid) => soWyPersonName(state, pid)).join('、');
    const cid = soWyAddChat(state, { type: 'group', name: title, members: [THEATER_WEIYU_ME, ...picked], floor: null });
    if (!cid) return null;
    state.chats[cid].own = 1; // the 由来 marker (soWyChatOwn / soWyChatWhy), never audience-specific prose
    soWyApplyEvent(state, cid, { k: 'create', who: THEATER_WEIYU_ME }, { b: soWyNewId(state, 'b'), src: 'sys' });
    return cid;
}

function soWyInvite(state, cid, pids) {
    const chat = soWyChat(state, cid);
    if (!chat || chat.type !== 'group' || chat.dissolved || soWyChatClosed(state, chat) || !soWyIsMine(chat)) return null;
    const mid = soWyApplyEvent(state, cid, { k: 'join', who: THEATER_WEIYU_ME, targets: pids }, { b: soWyNewId(state, 'b'), src: 'me' });
    if (mid) soWyTouch(state, cid);
    return mid;
}

function soWyLeave(state, cid) {
    const chat = soWyChat(state, cid);
    if (!chat || chat.type !== 'group' || chat.dissolved || soWyChatClosed(state, chat) || !soWyIsMine(chat)) return null;
    const mid = soWyApplyEvent(state, cid, { k: 'leave', who: THEATER_WEIYU_ME }, { b: soWyNewId(state, 'b'), src: 'me' });
    if (mid) soWyTouch(state, cid);
    return mid;
}

// The player's own line: stored verbatim as ONE text message — never parsed, whatever it looks like. Over his ceiling
// (THEATER_WEIYU_TYPED_MAX.text) → null, nothing stored — never cut (the screen says so first).
function soWySendLine(state, cid, text, quote) {
    const chat = soWyChat(state, cid);
    if (!chat || !soWyCanSendIn(state, chat)) return null;   // = live, his, and not his private chat with someone he blocked
    if (soWyLen(text) > THEATER_WEIYU_TYPED_MAX.text) return null;
    const v = soWyClip(text, THEATER_WEIYU_TYPED_MAX.text);
    if (!v) return null;
    const msg = { t: 'text', u: THEATER_WEIYU_ME, v };
    if (soWyIsObj(quote) && soWyPerson(state, quote.u)) msg.q = { u: quote.u, v: soWyClip(quote.v, 120) };
    const mid = soWyAddMsg(state, cid, msg, { b: soWyNewId(state, 'b'), src: 'me' });
    if (!mid) return null;
    soWyMarkRead(state, cid);
    soWyTouch(state, cid);
    return mid;
}

// ---- the player's own special messages (owner 2026-11-17, redesign Lane D slice D1): 语音 / 照片 / 视频 / 拍一拍 are HIS SEND (one
// 'send' call, soWyCall); 撤回 of his own line is a zero-call player edit. Each kind keeps the stored shape the characters' lines
// already have, with u: 'me' — nothing new in the schema.

// What the model reads for the player's own recall instead of its words (probe gm-playerkind R2, root ruling 2026-11-17): soWyLogLine
// prints `<his name>〔撤回〕：` + this; the main-story note fills its frozen recall label with it (soWyNoteMsg).
const THEATER_WEIYU_RECALL_ME = '撤回了一条消息';
const THEATER_WEIYU_SAID = ['text', 'emoji', 'voice', 'photo', 'video'];

// A voice note's length is computed, never typed: ceil(characters / 3), clamped 2–60 (probe gm-playerkind: 26 characters → 9 s read fine).
function soWyVoiceSec(text) {
    const n = Array.from(String(text == null ? '' : text).trim()).length;
    return Math.min(60, Math.max(2, Math.ceil(n / 3)));
}

// A live chat the player is in (the only place he can send anything) — never his private chat with a contact he blocked (soWyDmBlocked).
function soWyCanSendIn(state, chat) {
    return soWyIsObj(chat) && !chat.dissolved && !soWyChatClosed(state, chat) && soWyIsMine(chat) && !soWyDmBlocked(state, chat);
}

// 拍一拍 the real way: another living member of a live chat the player is in (a private chat: the other person; a group: the avatar's
// owner while still a member). Never himself.
function soWyCanNudge(state, chat, pid) {
    if (!soWyCanSendIn(state, chat) || typeof pid !== 'string' || pid === THEATER_WEIYU_ME) return false;
    const p = soWyPerson(state, pid);
    return !!p && p.gone !== 1 && chat.members.includes(pid);
}

// 撤回: his own said line (never a line the AI wrote for him — the ai mark), in a live chat he is in.
function soWyCanRecall(state, chat, msg) {
    return soWyCanSendIn(state, chat) && soWyIsObj(msg) && msg.u === THEATER_WEIYU_ME && !msg.ai && THEATER_WEIYU_SAID.includes(msg.t)
        && !soWyEvKind(msg);
}

// o = {t: 'voice', v} | {t: 'photo', v, em?} | {t: 'video', v, em?, dur} | {t: 'nudge', to} | {t: 'card', k, title, sub?, pid?}.
// voice: v = his words, sec computed
// (soWyVoiceSec; any given sec is ignored). photo / video: v = what the camera shows; em = the tile's emoji (kept only when it is one
// emoji); dur 'm:ss', required for a video (1 s – 99:59). nudge: to = soWyCanNudge. card (more functions phase 1): k = 'loc' | 'file' |
// 'link' | 'contact' | 'music' (位置 / 文件 / 链接 / 名片 / 音乐), title required (one line, ≤ 120), sub optional (≤ 300); a 名片 of someone
// on the phone passes pid (a living person, the player included) and takes his name as the title, any other 名片 is free text. Stored
// as {t: 'text', u: 'me', v: soWyCardText(card), card}. Phase 2: {t: 'call', mode: 'voice'|'video'} (his 已取消 call, to = the other
// member) and {t: 'pay', amt?, note?} (his transfer) — his own private chat only (soWyEvPeer). Stored like soWySendLine (src 'me', read, touched),
// never parsed. Each typed field over its ceiling (THEATER_WEIYU_TYPED_MAX: words 4000, card 120 / 300, transfer 40 / 200) → null, never cut.
// → the new id, or null (nothing changed).
function soWySendKind(state, cid, o) {
    const chat = soWyChat(state, cid);
    const x = soWyIsObj(o) ? o : {};
    if (!soWyCanSendIn(state, chat) || !['voice', 'photo', 'video', 'nudge', 'card', 'call', 'pay'].includes(x.t)) return null;
    let msg = { t: x.t, u: THEATER_WEIYU_ME, v: '' };
    if (x.t === 'call' || x.t === 'pay') {
        // phase 2: his call (1C — he rang and hung up: always 已取消) / his transfer, in his private chat only, to the other member. The
        // flag (ENABLE_THR_WEIYU_EVENTS) is checked by soWyCall ('gone') and by the screens (soWyCanCall / soWyCanPay), not here.
        const to = soWyEvPeer(state, chat);
        if (!to) return null;
        if (x.t === 'call') {
            if (!soWyOwn(THEATER_WEIYU_CALL_KIND, x.mode)) return null;
            const call = { mode: x.mode, st: 'cancel' };
            msg = { t: 'text', u: THEATER_WEIYU_ME, to, v: soWyCallText(call), call };
        } else {
            if (soWyLen(soWyLine1(x.amt)) > THEATER_WEIYU_TYPED_MAX.amt || soWyLen(soWyLine1(x.note)) > THEATER_WEIYU_TYPED_MAX.note) return null;
            const pay = soWyPayNorm({ amt: x.amt, note: x.note, to });
            msg = { t: 'text', u: THEATER_WEIYU_ME, v: soWyPayText(pay), pay };
        }
    } else if (x.t === 'card') {
        let title = x.title;
        let pid;
        if (x.k === 'contact' && typeof x.pid === 'string' && x.pid) {
            const p = soWyPerson(state, x.pid);
            if (!p || p.gone === 1) return null;
            pid = x.pid;
            title = p.name;
        }
        if (soWyLen(soWyLine1(title)) > THEATER_WEIYU_TYPED_MAX.title || soWyLen(soWyLine1(x.sub)) > THEATER_WEIYU_TYPED_MAX.sub) return null;
        const card = soWyCardNorm({ k: x.k, title, sub: x.sub, pid });
        if (!card) return null;
        msg = { t: 'text', u: THEATER_WEIYU_ME, v: soWyCardText(card), card };
    } else if (x.t === 'nudge') {
        if (!soWyCanNudge(state, chat, x.to)) return null;
        msg.to = x.to;
    } else {
        if (soWyLen(x.v) > THEATER_WEIYU_TYPED_MAX.text) return null;
        msg.v = soWyClip(x.v, THEATER_WEIYU_TYPED_MAX.text);
        if (!msg.v) return null;
        if (x.t === 'voice') msg.sec = soWyVoiceSec(msg.v);
        if (x.t !== 'voice' && typeof x.em === 'string' && soWyIsEmojiOnly(x.em) && Array.from(x.em.match(/\p{Extended_Pictographic}/gu) || []).length === 1) msg.em = x.em.trim();
        if (x.t === 'video') {
            const m = /^(\d{1,2}):([0-5]\d)$/.exec(typeof x.dur === 'string' ? x.dur : '');
            if (!m || Number(m[1]) * 60 + Number(m[2]) < 1) return null;
            msg.dur = x.dur;
        }
    }
    const mid = soWyAddMsg(state, cid, msg, { b: soWyNewId(state, 'b'), src: 'me' });
    if (!mid) return null;
    soWyMarkRead(state, cid);
    soWyTouch(state, cid);
    return mid;
}

// 撤回 in place: the line becomes the recall notice (same id and place; its words stay in v so the phone can show him what he recalled
// — a model never reads them); the picture / voice / quote fields go. Zero calls; a player edit under the "touched" rule. → true | false.
function soWyRecallMsg(state, cid, mid) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0 || !soWyCanRecall(state, chat, chat.msgs[i])) return false;
    const m = chat.msgs[i];
    m.t = 'recall';
    // a recalled card / forward is a plain recall line (its fallback stays in v for the phone)
    for (const f of ['q', 'sec', 'em', 'dur', 'card', 'fwd']) delete m[f];
    soWyTouch(state, cid);
    return true;
}

function soWySetOpt(state, key, value) {
    if (!['steal', 'sync', 'tell'].includes(key) || !state) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    state.opts[key] = !!value;
    return true;
}

// 动画 (owner 2026-11-17, redesign slice 1): the phone's own motion setting. Stored as opts.motion = 'on' | 'off'; absent = 跟随系统
// (old phones, the default — soWyDefaultOpts is unchanged, so a player who never touches it stores nothing new). Any other stored value
// reads as 跟随系统 and is kept as stored (like any unknown key, soWyKeepExtra). The UI resolves it with the system's reduced-motion
// setting into ONE root flag (soWyApplyMotion, ui-core).
const THEATER_WEIYU_MOTION = Object.freeze(['auto', 'on', 'off']);

function soWyMotionOpt(state) {
    const v = soWyIsObj(state) && soWyIsObj(state.opts) ? state.opts.motion : undefined;
    return v === 'on' || v === 'off' ? v : 'auto';
}

// 'auto' (跟随系统) deletes the key; 'on' / 'off' store it; anything else is refused.
function soWySetMotion(state, value) {
    if (!state || !THEATER_WEIYU_MOTION.includes(value)) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    if (value === 'auto') delete state.opts.motion;
    else state.opts.motion = value;
    return true;
}

// The resolved flag: 开 / 关 win over the system; 跟随系统 = off exactly when the system asks for reduced motion.
function soWyMotionResolve(opt, systemReduced) {
    if (opt === 'on' || opt === 'off') return opt;
    return systemReduced ? 'off' : 'on';
}

// 消息菜单 (owner 2026-11-17, redesign Lane D slice D2): where a message's menu opens. 'more' = a ⋯ beside the message (the default —
// absent key, so old phones and a player who never touches it store nothing new); 'hold' = press and hold the bubble (no ⋯). The setting
// REPLACES: in 'more' a long press opens nothing, in 'hold' no ⋯ is drawn; right click and Enter open it in both. Junk reads as 'more'
// and is kept as stored (soWyKeepExtra), like opts.motion.
const THEATER_WEIYU_MENU_MODES = Object.freeze(['more', 'hold']);

function soWyMenuModeOpt(state) {
    const v = soWyIsObj(state) && soWyIsObj(state.opts) ? state.opts.menu : undefined;
    return v === 'hold' ? 'hold' : 'more';
}

// 'more' (点 ⋯) deletes the key; 'hold' (长按气泡) stores it; anything else is refused.
function soWySetMenuMode(state, value) {
    if (!state || !THEATER_WEIYU_MENU_MODES.includes(value)) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    if (value === 'more') delete state.opts.menu;
    else state.opts.menu = value;
    return true;
}

// A numeric option (the memory slice, 2026-11-18: opts.keep, opts.meterLine — additive keys, schema stays 1): the stored number clamped to
// {min, max}; missing / not a finite number → `def`. Never throws.
function soWyNumOpt(state, key, def, clamp) {
    const v = soWyIsObj(state) && soWyIsObj(state.opts) ? state.opts[key] : undefined;
    if (typeof v !== 'number' || !Number.isFinite(v)) return def;
    return Math.min(clamp.max, Math.max(clamp.min, Math.round(v)));
}

// Stores a finite number clamped to {min, max}; the default deletes the key (a phone that never changes it stores nothing new). Anything
// else (a string, NaN, Infinity, no state) is refused → false.
function soWySetNumOpt(state, key, value, def, clamp) {
    if (!state || typeof value !== 'number' || !Number.isFinite(value)) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    const n = Math.min(clamp.max, Math.max(clamp.min, Math.round(value)));
    if (n === def) delete state.opts[key];
    else state.opts[key] = n;
    return true;
}

// ---- 每几次回复更新一次 · story sync every N replies (owner #160, 2026-11-21; design docs/superpowers/specs/2026-11-21-weiyu-sync-every-design.md) ---
// opts.syncEvery = N, a whole number ≥ 1, per chat next to opts.sync; absent = 1 = today (a sync after every story reply). soWyDefaultOpts is
// unchanged, so a phone that never sets it stores nothing new. The flag gate lives in the UI (env.stages.syncEvery) and the join
// (ENABLE_THR_WEIYU_SYNC_EVERY); these are pure and never throw. Nothing is clamped: what the player types is taken or refused (owner's rule).
function soWySyncEvery(state) {
    const v = soWyIsObj(state) && soWyIsObj(state.opts) ? state.opts.syncEvery : undefined;
    return Number.isSafeInteger(v) && v >= 1 ? v : 1;
}

// The typed text → {ok: true, n} | {ok: false, why: 'bad' | 'big'}. Taken: digits only (ASCII or full-width), spaces around ignored, value ≥ 1.
// 'bad' = anything else (empty, 0, a sign, a decimal point, letters); 'big' = more than the largest whole number the phone counts exactly
// (Number.MAX_SAFE_INTEGER, 9007199254740991) — the only ceiling, and it is said, never applied silently.
function soWySyncEveryParse(text) {
    const t = String(text == null ? '' : text).trim().replace(/[０-９]/g, (c) => String(c.charCodeAt(0) - 0xFF10));
    if (!/^[0-9]+$/.test(t)) return { ok: false, why: 'bad' };
    const n = Number(t);
    if (!(n >= 1)) return { ok: false, why: 'bad' };
    if (!Number.isSafeInteger(n)) return { ok: false, why: 'big' };
    return { ok: true, n };
}

// 1 deletes the key (= today); any other safe whole number ≥ 1 is stored as it is; anything else is refused → false.
function soWySetSyncEvery(state, n) {
    if (!soWyIsObj(state) || !Number.isSafeInteger(n) || n < 1) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    if (n === 1) delete state.opts.syncEvery;
    else state.opts.syncEvery = n;
    return true;
}

// ---- AI 自动回复 · the AI auto-reply switch (owner 2026-11-20; spec 2026-11-20-weiyu-hold-reply-design.md §5 / §6) -------------------
// ONE switch for the whole phone: opts.autoReply — absent = ON (today: every send asks for a reply; a player who never touches it stores
// nothing new, soWyDefaultOpts is unchanged), false = OFF (what he sends is stored and shown, no request; the UI's 「AI 现在回复」 asks once).
// Anything else stored reads as ON and is kept as stored (soWyKeepExtra), like opts.motion. The flag gate lives in the UI / engine
// (env.stages.autoReply / deps.autoReply); these readers are pure and never throw.
function soWyArOpt(state) {
    return !(soWyIsObj(state) && soWyIsObj(state.opts) && state.opts.autoReply === false);
}

// on true → the key goes (ON = absent); false → opts.autoReply = false. Creates opts (the defaults) when missing; no state → false.
// → true when the stored option changed.
function soWyArSet(state, on) {
    if (!soWyIsObj(state)) return false;
    if (!soWyIsObj(state.opts)) state.opts = soWyDefaultOpts();
    const had = soWyOwn(state.opts, 'autoReply');
    const was = state.opts.autoReply;
    if (on) delete state.opts.autoReply;
    else state.opts.autoReply = false;
    return on ? had : !(had && was === false);
}

// One of HIS items a reply has not answered yet: his own send (src 'me'), not a line the AI wrote for him (ai), not refused. A time line is
// neither (skipped); anything else (a character's line, a sys / event line, a line from a story sync) ends the run.
function soWyArItem(m) {
    return soWyIsObj(m) && m.u === THEATER_WEIYU_ME && m.src === 'me' && !m.ai && m.refused !== 1;
}

// What waits for a reply at the END of a chat he can send in (derived from the chat, nothing stored — it survives reload, undo and sync):
// walking back from the end, time lines skipped, every item of his (soWyArItem) is taken until anything else. ids = the run, oldest first;
// last = the newest taken (it may be a recall or a call record — the request shows everything); n = the taken items that are not a recall,
// not a call record and not his 收款 / 退回 answer to her transfer (root ruling 2026-11-20: that tap asks for nothing today, so it alone
// never makes 「AI 现在回复」 appear). → {n, last, ids} when n ≥ 1, else null (also for a chat he only watches, a dissolved / closed / blocked one).
function soWyWaiting(state, cid) {
    try {
        const chat = soWyChat(state, cid);
        if (!chat || !Array.isArray(chat.msgs) || !soWyCanSendIn(state, chat)) return null;
        const ids = [];
        let n = 0;
        for (let i = chat.msgs.length - 1; i >= 0; i--) {
            const m = chat.msgs[i];
            if (soWyIsObj(m) && m.t === 'time') continue;
            if (!soWyArItem(m)) break;
            ids.unshift(m.id);
            const ek = soWyEvKind(m);
            if (m.t !== 'recall' && ek !== 'call' && ek !== 'ans') n++;
        }
        return n >= 1 ? { n, last: ids[ids.length - 1], ids } : null;
    } catch (e) {
        return null;
    }
}

// 重新回复 on one of his items inside an unbroken run of his items (time lines skipped) acts on the run's LAST item — else the model would not
// see the later ones and the replies would land between them. → that newest id; `mid` itself when it is not such an item. Never throws.
function soWyArRunEnd(state, cid, mid) {
    try {
        const chat = soWyChat(state, cid);
        const i = soWyMsgIndex(chat, mid);
        if (i < 0 || !soWyArItem(chat.msgs[i])) return mid;
        let end = mid;
        for (let j = i + 1; j < chat.msgs.length; j++) {
            const m = chat.msgs[j];
            if (soWyIsObj(m) && m.t === 'time') continue;
            if (!soWyArItem(m)) break;
            end = m.id;
        }
        return end;
    } catch (e) {
        return mid;
    }
}

// Options and the id counter survive a reset; people / chats / deltas / alts do not. Pictures are never stored here.
function soWyReset(state) {
    const me = soWyPerson(state, THEATER_WEIYU_ME);
    const r = soWyEmpty(me ? me.name : '', state && state.seq);
    if (state && soWyIsObj(state.opts)) r.opts = soWyOptsCarry(state.opts);
    return r;
}

// ---- Task 4: edit, delete with undo, regenerate ranges ---------------------------------------------------------------------

// Grey lines (nudge / sys / time) are delete-only. So are a card / a forward (their words are a fallback over a structure — editing v
// would split the two) and a refused line (behind 偷看, never delivered).
function soWyCanEdit(msg) {
    if (!msg || msg.refused === 1 || (msg.t === 'text' && (soWyCardNorm(msg.card) || soWyFwdNorm(msg.fwd) || soWyEvKind(msg)))) return false;
    return ['text', 'emoji', 'voice', 'photo', 'video', 'recall'].includes(msg.t);
}

function soWyMsgIndex(chat, mid) {
    return chat && Array.isArray(chat.msgs) ? chat.msgs.findIndex((m) => m && m.id === mid) : -1;
}

function soWyEditMsg(state, cid, mid, text) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0 || !soWyCanEdit(chat.msgs[i])) return false;
    const v = String(text == null ? '' : text).trim();
    if (!v) return false;
    const m = chat.msgs[i];
    // over his ceiling AND longer than the line it replaces → refused (an AI line can be longer than 4000: he may still shorten it)
    if (soWyLen(v) > THEATER_WEIYU_TYPED_MAX.text && soWyLen(v) > soWyLen(m.v)) return false;
    m.v = v;
    if (m.t === 'text' || m.t === 'emoji') m.t = soWyIsEmojiOnly(v) ? 'emoji' : 'text';
    soWyTouch(state, cid);
    return true;
}

// Removes the line only — a deleted sys line does NOT undo its membership change. The read mark and the summary boundary
// (sum.through) on that line move back to the nearest earlier line (null at the start); the undo record remembers which moved
// (read / sum = the summary's text then) so soWyUndoDelete can put them back. sum.next stays as the second line of defence.
function soWyDeleteMsg(state, cid, mid) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0) return null;
    const after = i > 0 ? chat.msgs[i - 1].id : null;
    const msg = chat.msgs.splice(i, 1)[0];
    const undo = { cid, after, msg };
    if (chat.read === mid) { chat.read = after; undo.read = 1; }
    if (soWyIsObj(chat.sum) && chat.sum.through === mid) {
        chat.sum.through = after;
        undo.sum = typeof chat.sum.text === 'string' ? chat.sum.text : '';
    }
    soWyTouch(state, cid);
    return undo;
}

// A mark moved by the delete comes back only while it still sits where the delete put it (and, for the summary, while it is the
// same summary) — a mark that moved on since is left alone.
function soWyUndoDelete(state, undo) {
    if (!soWyIsObj(undo) || !soWyIsObj(undo.msg)) return false;
    const chat = soWyChat(state, undo.cid);
    if (!chat || soWyMsgIndex(chat, undo.msg.id) >= 0) return false;
    let at;
    if (undo.after == null) at = 0;
    else {
        const j = soWyMsgIndex(chat, undo.after);
        at = j < 0 ? chat.msgs.length : j + 1;
    }
    chat.msgs.splice(at, 0, undo.msg);
    const was = undo.after == null ? null : undo.after;
    if (undo.read === 1 && chat.read === was) chat.read = undo.msg.id;
    if (typeof undo.sum === 'string' && soWyIsObj(chat.sum) && chat.sum.through === was && chat.sum.text === undo.sum) {
        chat.sum.through = undo.msg.id;
    }
    return true;
}

// What a regenerate of `mid` replaces (pure). The player's own line keeps itself and re-asks the run of replies after it;
// any other speaker's line goes together with the rest of its batch.
function soWyRegenPlan(state, cid, mid) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0) return null;
    const m = chat.msgs[i];
    if (m.t === 'time' || m.t === 'sys' || typeof m.u !== 'string') return null;
    if (m.src === 'boot' && soWyIsObj(chat.sum)) {
        // the last summarised line: `through`; when that is gone (a phone saved by an older build), the line before `next`
        let t = typeof chat.sum.through === 'string' ? soWyMsgIndex(chat, chat.sum.through) : -1;
        if (t < 0 && typeof chat.sum.next === 'string') {
            const n = soWyMsgIndex(chat, chat.sum.next);
            if (n >= 0) t = n - 1;
        }
        if (t >= i) return null;
    }
    if (m.u === THEATER_WEIYU_ME && !m.ai) {
        const drop = [];
        const first = chat.msgs[i + 1];
        const run = ['ai', 'sync', 'sys'];
        if (first && run.includes(first.src)) {
            for (let j = i + 1; j < chat.msgs.length; j++) {
                const x = chat.msgs[j];
                if (!run.includes(x.src) || x.b !== first.b) break;
                drop.push(x.id);
            }
        }
        return { cid, anchor: mid, drop, asMe: true };
    }
    const drop = [];
    for (let j = i; j < chat.msgs.length; j++) if (j === i || chat.msgs[j].b === m.b) drop.push(chat.msgs[j].id);
    return { cid, anchor: i > 0 ? chat.msgs[i - 1].id : null, drop, asMe: false };
}

// Removes the planned range (membership changes inside it ARE undone); false — state untouched — when the phone moved on.
function soWyRegenCut(state, plan) {
    if (!soWyIsObj(plan) || !Array.isArray(plan.drop)) return false;
    const chat = soWyChat(state, plan.cid);
    if (!chat) return false;
    if (plan.anchor != null && soWyMsgIndex(chat, plan.anchor) < 0) return false;
    if (plan.drop.some((id) => soWyMsgIndex(chat, id) < 0)) return false;
    soWyUnapplyMsgs(state, plan.cid, plan.drop);
    soWyTouch(state, plan.cid);
    return true;
}

// ---- 删除聊天 / 删除联系人 (owner's requests 2026-11-16/17; root's rulings): zero calls, PLAYER edits ---------------------------------
//
// soWyDeleteChat(state, cid) → {cid, chat} (the undo record) | null — the chat object goes (its history and summary with it); people and
//   every other chat stay. soWyUndoDeleteChat(state, undo) puts the same object back in place while nothing took its place.
// soWyDeletePerson(state, pid, withLines) → {removed: cid[]} | null — never the player. withLines false (A): the person becomes the
//   tombstone {id, name, gone: 1, main?} (their lines render as before), leaves every group's member list silently; a group left with
//   fewer than two members is closed (read-only history); private chats with them stay and are read-only (soWyChatClosed). withLines
//   true (B): as (A), and every line they sent (their 拍一拍 either way, their sys lines) goes, a join line keeps the other people it
//   names, quote chips at them go (the replying line stays), private chats with them go, a group left with < 2 members goes when it
//   has no message left (else closed), the record goes.
// Both keep the story-sync undo from bringing anything back (soWyUndoGuard): every live delta that mentions the chat / person is
// touched (the existing rule for a player edit: never reverted as a whole), every stashed alternative that mentions it is dropped (a
// swipe back to it then leaves the phone as it is, the documented fallback). Name lookups skip a tombstone (soWyFindPerson), so a later
// person of the same name — a story sync or a model reply declaring them — is a NEW contact.

function soWyGone(state, pid) {
    const p = soWyPerson(state, pid);
    return !!p && p.gone === 1;
}

// Read-only history: a group closed by soWyDeletePerson, or a private chat with a removed contact. No input, no hold, no regenerate,
// no model line lands there (the resolver reads it as dissolved; soWyDeltaReplayable skips it).
function soWyChatClosed(state, chat) {
    if (!soWyIsObj(chat)) return false;
    if (chat.closed === 1) return true;
    return chat.type === 'dm' && Array.isArray(chat.members) && chat.members.some((pid) => pid !== THEATER_WEIYU_ME && soWyGone(state, pid));
}

// Story-sync undo vs a player edit: live deltas mentioning any of `refs` (ids / a name) are touched, stashed alternatives mentioning
// them are dropped. → how many it changed.
function soWyUndoGuard(state, refs) {
    const list = (Array.isArray(refs) ? refs : []).filter((r) => typeof r === 'string' && r);
    if (!state || !list.length) return 0;
    const hit = (x) => list.some((r) => soWyMentions(x, r));
    let n = 0;
    for (const d of Array.isArray(state.deltas) ? state.deltas : []) {
        if (!soWyIsObj(d) || d.final || !hit(d)) continue;
        if (d.touched !== 1) n++;
        d.touched = 1;
    }
    if (soWyIsObj(state.alts) && soWyIsObj(state.alts.bySwipe)) {
        for (const k of Object.keys(state.alts.bySwipe)) {
            if (!hit(state.alts.bySwipe[k])) continue;
            delete state.alts.bySwipe[k];
            n++;
        }
    }
    return n;
}

function soWyDeleteChat(state, cid) {
    if (typeof cid !== 'string') return null;
    const chat = soWyChat(state, cid);
    if (!chat) return null;
    delete state.chats[cid];
    soWyUndoGuard(state, [cid]);
    return { cid, chat };
}

function soWyUndoDeleteChat(state, undo) {
    if (!state || !soWyIsObj(state.chats) || !soWyIsObj(undo) || typeof undo.cid !== 'string' || !soWyIsObj(undo.chat)) return false;
    if (soWyOwn(state.chats, undo.cid) || THEATER_WEIYU_UNSAFE_IDS.includes(undo.cid)) return false;
    const c = undo.chat;
    const members = Array.isArray(c.members) ? c.members : [];
    if (!members.every((pid) => soWyPerson(state, pid))) return false;
    if (c.type === 'dm' && Object.values(state.chats).some((x) => soWyIsObj(x) && x.type === 'dm' && Array.isArray(x.members)
        && x.members.length === members.length && members.every((pid) => x.members.includes(pid)))) return false;
    state.chats[undo.cid] = JSON.parse(JSON.stringify(c));
    return true;
}

// (B) One chat without the lines of `pid`; a read mark / summary boundary on a removed line moves back to the nearest earlier kept
// line (as a deleted line's does). → how many lines went.
function soWyDropLinesOf(chat, pid) {
    const msgs = soWyIsObj(chat) && Array.isArray(chat.msgs) ? chat.msgs : [];
    const out = new Set();
    for (const m of msgs) {
        if (!soWyIsObj(m)) continue;
        if (m.u === pid || m.to === pid || m.who === pid) { out.add(m.id); continue; }
        if (soWyIsObj(m.q) && m.q.u === pid) delete m.q;
        const named = (Array.isArray(m.targets) && m.targets.includes(pid)) || (Array.isArray(m.added) && m.added.includes(pid));
        if (m.t !== 'sys' || !named) continue;
        for (const f of ['targets', 'added']) if (Array.isArray(m[f])) m[f] = m[f].filter((x) => x !== pid);
        if (!(Array.isArray(m.targets) && m.targets.length) && !(Array.isArray(m.added) && m.added.length)) out.add(m.id);
    }
    if (!out.size) return 0;
    const back = (id) => {
        const i = msgs.findIndex((m) => soWyIsObj(m) && m.id === id);
        for (let j = i - 1; j >= 0; j--) if (soWyIsObj(msgs[j]) && !out.has(msgs[j].id)) return msgs[j].id;
        return null;
    };
    if (typeof chat.read === 'string' && out.has(chat.read)) chat.read = back(chat.read);
    if (soWyIsObj(chat.sum) && typeof chat.sum.through === 'string' && out.has(chat.sum.through)) chat.sum.through = back(chat.sum.through);
    chat.msgs = msgs.filter((m) => !(soWyIsObj(m) && out.has(m.id)));
    return out.size;
}

function soWyDeletePerson(state, pid, withLines) {
    if (typeof pid !== 'string' || pid === THEATER_WEIYU_ME || !state || !soWyIsObj(state.chats)) return null;
    const p = soWyPerson(state, pid);
    if (!p || p.gone === 1) return null;
    const all = !!withLines;
    const removed = [];
    for (const cid of Object.keys(state.chats)) {
        const c = state.chats[cid];
        if (!soWyIsObj(c)) continue;
        const members = Array.isArray(c.members) ? c.members : [];
        if (all) soWyDropLinesOf(c, pid);
        if (!members.includes(pid)) continue;
        if (c.type === 'dm') {
            if (all) removed.push(cid);
            continue;
        }
        c.members = members.filter((x) => x !== pid);
        if (c.members.length < 2) {
            if (all && !(Array.isArray(c.msgs) && c.msgs.length)) removed.push(cid);
            else c.closed = 1;
        }
    }
    for (const cid of removed) delete state.chats[cid];
    if (all) delete state.people[pid];
    else {
        const t = { id: pid, name: p.name, gone: 1 };
        if (p.main === 1) t.main = 1;
        state.people[pid] = t;
    }
    soWyUndoGuard(state, [pid, typeof p.name === 'string' ? p.name : ''].concat(removed));
    return { removed };
}

// ---- more functions, phase 1 (owner's go 2026-11-17; study docs/superpowers/specs/2026-11-17-weiyu-more-functions-feasibility.md) ----
// Zero-call player actions unless noted. Owner's rulings: remark names are hidden from the AI · a blocked contact: the AI knows (one fact
// in soWyBrief), they still speak in groups and in chats he only watches · their refused lines stay behind 「偷看」 · no stranger
// friend requests, but a group's background member can be added (soWyAddContact).
//   soWyForward(state, fromCid, mids, toCid) → mid | null      his SEND (soWySendPut runs it inside soWyCall('send', {cid, fwd}))
//   soWySetPin(state, cid, on) → bool · soWyScreenChats(state) → cid[] (pinned first, then soWyChatList's order — the screen only)
//   soWySetRemark(state, pid, text) → bool · soWyShownName(state, pid) → the remark, else the name (the phone only)
//   soWySetBlocked(state, pid, on) → bool · soWyBlocked(state, pid) → bool · soWyRefuses(state, chat, pid) → bool
//   soWySearch(state, query, limit?) → {people: [{pid, name, remark?}], chats: [{cid}], msgs: [{cid, mid, text}]}
//   soWyAddContact(state, pid) → the private chat's id | null
// Story-sync undo ("touched"): the forward (like any send) touches its chat; soWyAddContact touches the private chat and every live
// delta that mentions the person (the sync that brought him is then never reverted under the new contact). Pin / remark / block are
// state ABOUT a chat or a person (like 免打扰): no delta is touched — a reverted sync that made the chat / person takes it with them.

// The per-line rule of every forward: a said line (text / emoji / voice / photo / video, cards and forwards included) with words, never
// recalled, never refused, never a grey / time line, never a call / transfer / answer record. Phase 3 (a character's forward by reference)
// uses it as is — a member of the source chat saw every line there.
function soWyFwdable(m) {
    return soWyIsObj(m) && m.refused !== 1 && typeof m.u === 'string' && THEATER_WEIYU_SAID.includes(m.t) && !soWyEvKind(m) && !!soWyMsgPlain(m);
}

// A line the player may forward: soWyFwdable, and he saw it land in a chat he was in (in: 1).
function soWyCanForward(m) {
    return soWyIsObj(m) && m.in === 1 && soWyFwdable(m);
}

// ---- a character's forward BY REFERENCE (more functions phase 3, 2026-11-17; study §7 option A) ---------------------------------------
// The model writes 乙〔转发 「北区204干饭群」 3〕：一句话 — a reference, never the lines: the resolver (parse.js) checks it and soWyApplyOps copies
// the source's last N forwardable lines AS STORED when the line lands (soWyFwdSnap), into EXACTLY the player's stored shape
// {t: 'text', u, v: soWyFwdText(fwd), fwd: {from, lines}} — so the record card, search, preview, the log line and the note read it unchanged.
// N: missing → def; out of range → clamped to min..max.
const THEATER_WEIYU_FWD_REF = Object.freeze({ min: 2, max: 6, def: 3 });

function soWyFwdRefN(n) {
    const R = THEATER_WEIYU_FWD_REF;
    const k = n === null || n === undefined || n === '' ? NaN : Math.floor(Number(n));
    return Number.isFinite(k) ? Math.min(R.max, Math.max(R.min, k)) : R.def;
}

// The record's title for a character's forward: a group → its name; a private chat → both names, the sender (`by`) first 「甲 ↔ 乙」
// (soWyChatTitle would name the player's private chat after the OTHER person — read as 「林小满」's record when 林小满 herself forwards it).
function soWyFwdRefFrom(state, chat, by) {
    if (!soWyIsObj(chat)) return '';
    if (chat.type === 'group') return chat.name || '';
    const ms = Array.isArray(chat.members) ? chat.members.slice() : [];
    ms.sort((a, b) => (b === by ? 1 : 0) - (a === by ? 1 : 0));
    return ms.map((pid) => soWyPersonName(state, pid)).join(' ↔ ');
}

// → {from, lines} (soWyFwdNorm) of the last `n` (soWyFwdRefN) forwardable lines of `chat` as they are stored now, real names, words in
// their readable form (soWyMsgPlain) — or null when it has none. `by` = the sender (the title of a private chat names them first).
function soWyFwdSnap(state, chat, n, by) {
    if (!soWyIsObj(chat) || !Array.isArray(chat.msgs)) return null;
    const lines = chat.msgs.filter(soWyFwdable).slice(-soWyFwdRefN(n));
    return soWyFwdNorm({ from: soWyFwdRefFrom(state, chat, by), lines: lines.map((m) => ({ name: soWyPersonName(state, m.u), v: soWyMsgPlain(m) })) });
}

// The player forwards 1–6 lines of a chat HE IS IN (never one he only watches) to another chat he can send in (soWyCanSendIn): one
// message of his there, {t: 'text', u: 'me', v: soWyFwdText(fwd), fwd: {from: the source's title, lines: [{name, v}]}} — names (the
// REAL names, never a remark) and words copied now, in the source chat's order, special kinds in their readable form (soWyMsgPlain).
// Any bad id refuses the whole forward. Stored like soWySendKind (src 'me', read, touched). → the new id | null (nothing changed).
function soWyForward(state, fromCid, mids, toCid) {
    const from = soWyChat(state, fromCid);
    const to = soWyChat(state, toCid);
    if (!from || !to || fromCid === toCid || !soWyIsMine(from) || !Array.isArray(from.msgs) || !soWyCanSendIn(state, to)) return null;
    const ids = (Array.isArray(mids) ? mids : []).filter((x, i, a) => typeof x === 'string' && a.indexOf(x) === i);
    if (ids.length < 1 || ids.length > THEATER_WEIYU_FWD_MAX.lines) return null;
    const picked = [];
    for (const id of ids) {
        const i = soWyMsgIndex(from, id);
        if (i < 0 || !soWyCanForward(from.msgs[i])) return null;
        picked.push(i);
    }
    picked.sort((a, b) => a - b);
    const fwd = soWyFwdNorm({
        from: soWyChatTitle(state, from),
        lines: picked.map((i) => ({ name: soWyPersonName(state, from.msgs[i].u), v: soWyMsgPlain(from.msgs[i]) })),
    });
    if (!fwd || fwd.lines.length !== picked.length) return null;
    const mid = soWyAddMsg(state, toCid, { t: 'text', u: THEATER_WEIYU_ME, v: soWyFwdText(fwd), fwd }, { b: soWyNewId(state, 'b'), src: 'me' });
    if (!mid) return null;
    soWyMarkRead(state, toCid);
    soWyTouch(state, toCid);
    return mid;
}

// 置顶: view state like 免打扰.
function soWySetPin(state, cid, on) {
    const chat = soWyChat(state, cid);
    if (!chat) return false;
    if (on) chat.pin = 1;
    else delete chat.pin;
    return true;
}

// The chat list as the SCREEN shows it: pinned chats first, each part in soWyChatList's order. soWyChatList itself never looks at pins
// — it also orders the prompts, the sync headings and the main-story note, which a pin must not move.
function soWyScreenChats(state) {
    const all = soWyChatList(state);
    const pinned = (cid) => soWyIsObj(state.chats[cid]) && state.chats[cid].pin === 1;
    return all.filter(pinned).concat(all.filter((cid) => !pinned(cid)));
}

const THEATER_WEIYU_REMARK_MAX = 60;

// 备注: one line, ≤ 60 characters (over → false, nothing changed — never cut); empty (or the name itself) clears it. Never the player, never
// a removed contact.
function soWySetRemark(state, pid, text) {
    const p = soWyPerson(state, pid);
    if (!p || pid === THEATER_WEIYU_ME || p.gone === 1) return false;
    if (soWyLen(soWyLine1(text)) > THEATER_WEIYU_REMARK_MAX) return false;
    const r = soWyClip(soWyLine1(text), THEATER_WEIYU_REMARK_MAX);
    if (r && r !== p.name) p.remark = r;
    else delete p.remark;
    return true;
}

// The name the PHONE shows (list, bubbles, profile — the real name goes beneath): the remark when set, else the name. Model-facing text
// never calls this: soWyBrief / soWyLogLine / the sync headings / the note / quotes / a forward's names all use soWyPersonName.
function soWyShownName(state, pid) {
    const p = soWyPerson(state, pid);
    if (!p) return '?';
    return pid !== THEATER_WEIYU_ME && typeof p.remark === 'string' && p.remark.trim() ? p.remark : p.name;
}

// 拉黑: contacts only (not the player, not a removed contact, not a group's background member — add him first; a background person has
// no 【人】 line for the brief to carry the fact on). Off deletes the key; refused lines stay refused (unblocking delivers nothing old).
function soWySetBlocked(state, pid, on) {
    const p = soWyPerson(state, pid);
    if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.extra) return false;
    if (on) {
        // phase 2 (root, gm-block): a fresh block leaves ONE one-time beat for the pending-state block (soWyPendingItems k 'block'),
        // cleared by soWyCall when a request that carried it landed; re-blocking an already blocked person sets nothing new
        if (p.blocked !== 1) p.blockNote = 1;
        p.blocked = 1;
    } else {
        delete p.blocked;
        delete p.blockNote;
    }
    return true;
}

function soWyBlocked(state, pid) {
    const p = soWyPerson(state, pid);
    return !!p && p.blocked === 1;
}

// Is a line by `pid` landing in `chat` refused? Only in the player's own private chat with a person he blocked. soWyApplyOps marks such
// a line refused: 1 (kept for 偷看, not unread, not in any log / preview / note / search) — a refused line is not a dropped one, so it
// never counts against the batch. Groups and chats he only watches deliver as usual.
function soWyRefuses(state, chat, pid) {
    return soWyIsObj(chat) && chat.type === 'dm' && Array.isArray(chat.members) && chat.members.length === 2
        && chat.members.includes(THEATER_WEIYU_ME) && typeof pid === 'string' && pid !== THEATER_WEIYU_ME && chat.members.includes(pid) && soWyBlocked(state, pid);
}

// 搜索 (zero prompt impact): contacts by name or remark (not the player, background members or removed contacts), chats by their title
// (a private chat of his also by the other's remark), messages by their words — a card's title / sub, a forward's lines — newest first.
// Refused, recalled and grey lines are not searched. Case-insensitive; each list capped at `limit` (default 50). → ids for the jump.
function soWySearch(state, query, limit) {
    const out = { people: [], chats: [], msgs: [] };
    const q = soWyLine1(query).toLowerCase();
    if (!q || !soWyIsObj(state) || !soWyIsObj(state.people) || !soWyIsObj(state.chats)) return out;
    const n = Number(limit) > 0 ? Math.floor(Number(limit)) : 50;
    const has = (s) => typeof s === 'string' && s.toLowerCase().includes(q);
    for (const pid of Object.keys(state.people)) {
        const p = soWyPerson(state, pid);
        if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.extra) continue;
        if (!has(p.name) && !has(p.remark)) continue;
        const hit = { pid, name: p.name };
        if (typeof p.remark === 'string' && p.remark) hit.remark = p.remark;
        out.people.push(hit);
        if (out.people.length >= n) break;
    }
    for (const cid of soWyScreenChats(state)) {
        const chat = soWyChat(state, cid);
        const other = chat && chat.type === 'dm' && soWyIsMine(chat) ? soWyPerson(state, chat.members.find((x) => x !== THEATER_WEIYU_ME)) : null;
        if (!chat || !(has(soWyChatTitle(state, chat)) || (other && has(other.remark)))) continue;
        out.chats.push({ cid });
        if (out.chats.length >= n) break;
    }
    const found = [];
    for (const cid of Object.keys(state.chats)) {
        const chat = soWyChat(state, cid);
        for (const m of chat && Array.isArray(chat.msgs) ? chat.msgs : []) {
            if (!soWyIsObj(m) || m.refused === 1 || !THEATER_WEIYU_SAID.includes(m.t)) continue;
            const card = m.t === 'text' ? soWyCardNorm(m.card) : null;
            const fwd = m.t === 'text' && !card ? soWyFwdNorm(m.fwd) : null;
            const words = card ? [card.title, card.sub] : (fwd ? fwd.lines.map((l) => l.name + '：' + l.v) : [m.v]);
            if (!words.some(has)) continue;
            found.push({ cid, mid: m.id, text: soWyMsgPlain(m), at: soWyIdNum(m.id) });
        }
    }
    found.sort((a, b) => b.at - a.at);
    out.msgs = found.slice(0, n).map((x) => ({ cid: x.cid, mid: x.mid, text: x.text }));
    return out;
}

// DRAFT (slice B's wording table owns it later) — the grey line in the private chat after 添加到通讯录.
const THEATER_WEIYU_FRIEND_LINE = '你们已经是好友了';

// 添加到通讯录 for a group's background member (extra: 1 — someone who arrived through a group): extra goes (a contact now: the brief
// shows his 【人】 line and the private chat), his private chat with the player is found or made, one grey line {t: 'sys', k: 'friend'}
// (soWySysText; no model reads it — soWyLogLine / the note have no line for it). Zero calls; a player edit: the chat and every live
// delta that mentions him are touched. → the private chat's id | null (nothing changed).
function soWyAddContact(state, pid) {
    const p = soWyPerson(state, pid);
    if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.extra !== 1) return null;
    delete p.extra;
    const cid = soWyOpenDm(state, pid);
    if (!cid) {
        p.extra = 1;
        return null;
    }
    soWyAddMsg(state, cid, { t: 'sys', k: 'friend', v: THEATER_WEIYU_FRIEND_LINE }, { b: soWyNewId(state, 'b'), src: 'me' });
    soWyMarkRead(state, cid);
    soWyTouch(state, cid);
    for (const d of Array.isArray(state.deltas) ? state.deltas : []) {
        if (soWyIsObj(d) && !d.final && soWyMentions(d, pid)) d.touched = 1;
    }
    return cid;
}

// ---- adding contacts by hand (2026-11-21; spec 2026-11-21-weiyu-add-contact-design.md) ----------------------------------------------------
// Two additive Person keys: origin ('story' = a story person the player added · 'new' = 故事外的新人, invented by him) and about (the 人物说明,
// only for the AI — soWyBrief prints both behind args.ac). A person without them is today's person, byte for byte. The TYPED path validates
// first and REFUSES (never soWyAddPerson / soWyClip: what he typed is stored as typed, ends trimmed); AI-made people keep their own caps.
//   soWyAcName(state, name, max = AC_MAX.name) → {why: 'empty'|'long'(+m)|'lead'|'chars'|'me'} | {why: 'contact', pid} | {why: 'group', g} |
//     {ok: true, info?: 'extra'|'gone', pid?, m} — THE name check (the typed form with 40, the find list with 24), in this order.
//   soWyAcCheck(state, f) → {ok, name, over: {name?, sig?, area?, about?: m}, need}   f = {name, origin, about?, sig?, area?}
//   soWyAcAdd(state, f) → {pid, cid} | null · soWyAcPromote(state, pid) → bool · soWyAcEdit(state, pid, f) → bool
const THEATER_WEIYU_AC_MAX = Object.freeze({ name: 40, sig: 200, area: 200, about: 2000 });
// The characters the reader splits on (names 、，, · fields ｜| · speakers ：: · tags 〔〕[] · records 【】 and line breaks), both widths.
const THEATER_WEIYU_AC_BAD_RE = /[、，,｜\|：:〔〕\[\]【】\r\n]/;

// The group a person of this name would collide with ('' = none): ANY group, dissolved or closed included, by the exact key or the
// resolver's tolerant key (soWyChatKey: no spaces, no trailing member count) — a 【聊天】 heading resolves to a group first.
function soWyAcGroupClash(state, name) {
    const k = soWyNameKey(name);
    if (!k || !state || !soWyIsObj(state.chats)) return '';
    const t = soWyChatKey(name);
    for (const c of Object.values(state.chats)) {
        if (!soWyIsObj(c) || c.type !== 'group') continue;
        const nm = typeof c.name === 'string' ? c.name : '';
        if (!soWyNameKey(nm)) continue;
        if (soWyNameKey(nm) === k || (t && soWyChatKey(nm) === t)) return nm;
    }
    return '';
}

function soWyAcName(state, name, max) {
    const raw = String(name == null ? '' : name).trim();
    if (!raw) return { why: 'empty' };
    const cap = Number(max) > 0 ? Math.floor(Number(max)) : THEATER_WEIYU_AC_MAX.name;
    const m = soWyLen(raw);
    if (m > cap) return { why: 'long', m };
    if (/^[@＠]/.test(raw) || /^\*\*/.test(raw)) return { why: 'lead' };
    if (THEATER_WEIYU_AC_BAD_RE.test(raw)) return { why: 'chars' };
    const pid = soWyFindPerson(state, raw);
    if (pid === THEATER_WEIYU_ME) return { why: 'me' };
    const p = pid ? soWyPerson(state, pid) : null;
    if (p && !p.extra) return { why: 'contact', pid };
    const g = soWyAcGroupClash(state, raw);
    if (g) return { why: 'group', g };
    if (p) return { ok: true, info: 'extra', pid, m };
    const key = soWyNameKey(raw);
    const gone = soWyIsObj(state && state.people) && Object.values(state.people).some((x) => soWyIsObj(x) && x.gone === 1 && soWyNameKey(x.name) === key);
    return gone ? { ok: true, info: 'gone', m } : { ok: true, m };
}

function soWyAcCheck(state, f) {
    const x = soWyIsObj(f) ? f : {};
    const M = THEATER_WEIYU_AC_MAX;
    const name = soWyAcName(state, x.name, M.name);
    const over = {};
    if (name.why === 'long') over.name = name.m;
    for (const k of ['sig', 'area', 'about']) {
        const m = soWyLen(x[k]);
        if (m > M[k]) over[k] = m;
    }
    const need = x.origin === 'new' && !soWyLen(x.about);
    const ok = name.ok === true && !Object.keys(over).length && !need && (x.origin === 'story' || x.origin === 'new');
    return { ok, name, over, need };
}

// The typed add: a NEW person {id, name, sig?, area?, about?, origin, extra: 1} or the background member of that name (his typed non-empty
// fields set — the player's words win), then soWyAddContact (extra goes, the private chat with the grey 你们已经是好友了). Nothing on refusal.
function soWyAcAdd(state, f) {
    if (!state || !soWyIsObj(state.people) || !soWyIsObj(state.chats)) return null;
    const chk = soWyAcCheck(state, f);
    if (!chk.ok) return null;
    const typed = {};
    for (const k of ['sig', 'area', 'about']) {
        const v = typeof f[k] === 'string' ? f[k].trim() : '';
        if (v) typed[k] = v;
    }
    let pid = chk.name.info === 'extra' ? chk.name.pid : '';
    if (pid) {
        Object.assign(state.people[pid], typed, { origin: f.origin });
    } else {
        pid = soWyNewId(state, 'p');
        state.people[pid] = Object.assign({ id: pid, name: String(f.name).trim() }, typed, { origin: f.origin, extra: 1 });
    }
    const cid = soWyAddContact(state, pid);
    return cid ? { pid, cid } : null;
}

// The list's add of a background member (no chat — the owner's decision 3): soWyAddContact's first half. extra goes, every live delta that
// mentions him is touched (same pid, so every group line stays). A contact / removed person / the player → false.
function soWyAcPromote(state, pid) {
    const p = soWyPerson(state, pid);
    if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.extra !== 1) return false;
    delete p.extra;
    for (const d of Array.isArray(state.deltas) ? state.deltas : []) {
        if (soWyIsObj(d) && !d.final && soWyMentions(d, pid)) d.touched = 1;
    }
    return true;
}

// 编辑资料 of a hand-added / list-added person (origin or about set; a 开机 contact has no edit page → false): the keys present in f among
// about / sig / area (ends trimmed; empty deletes the key) and origin. Over a ceiling, an unknown origin or 故事外的新人 without a 人物说明 →
// false, nothing changed. A player edit: live deltas mentioning him are touched.
function soWyAcEdit(state, pid, f) {
    const p = soWyPerson(state, pid);
    const x = soWyIsObj(f) ? f : {};
    if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.extra) return false;
    if (!(p.origin === 'story' || p.origin === 'new' || (typeof p.about === 'string' && p.about.trim()))) return false;
    const next = {};
    for (const k of ['sig', 'area', 'about']) {
        if (!soWyOwn(x, k)) continue;
        const v = typeof x[k] === 'string' ? x[k].trim() : '';
        if (soWyLen(v) > THEATER_WEIYU_AC_MAX[k]) return false;
        next[k] = v;
    }
    if (soWyOwn(x, 'origin') && x.origin !== 'story' && x.origin !== 'new') return false;
    const origin = soWyOwn(x, 'origin') ? x.origin : p.origin;
    const about = soWyOwn(next, 'about') ? next.about : (typeof p.about === 'string' ? p.about.trim() : '');
    if (origin === 'new' && !about) return false;
    for (const k of Object.keys(next)) {
        if (next[k]) p[k] = next[k];
        else delete p[k];
    }
    if (soWyOwn(x, 'origin')) p.origin = origin;
    for (const d of Array.isArray(state.deltas) ? state.deltas : []) {
        if (soWyIsObj(d) && !d.final && soWyMentions(d, pid)) d.touched = 1;
    }
    return true;
}

// ---- 从故事里找人: matching, the code-made excerpt, the list's add (adding contacts by hand, pass B; spec §5 / §6) ----------------------
// The find request's records are a DRAFT: soWyFindMatch reads them against the phone and the text actually sent and NEVER changes the state;
// only the player's 添加 on one row (soWyAcAddFound, on a clone the UI commits) adds anyone.
//   src = {floors: [{n, text}]} — the story messages the request carried (n = the chat index; the join's soThrWeiyuFindSource, read once
//     at press time). Story prose only (the owner, 2026-11-21): a person only the card or the world book names is never listed.
//   soWyFindEx(src, name) → {floor: n | null, text} | null — where the text mentions the name: the NEWEST floor containing it (floor null
//     only for a floor without a usable index); text = up to THEATER_WEIYU_FIND_EX code points each side of the first occurrence, whitespace
//     flattened, … at a cut end. Occurrence = the exact name as a substring, case-insensitive (Latin letters). null = not in the sent floors.
//   soWyAcNear(state, name) → the first living contact's / background member's name that is near this one ('' = none): one contains the
//     other (both ≥ 2 code points), or the same length ≥ 3 with exactly one code point different (spec: ≥ 2; at 2 every pair sharing a
//     surname — 苏朗 / 苏晚 — would be "near"). A tag only — never a merge.
//   soWyFindMatch(state, recs, src) → {rows, have, drop}: per record in order — a repeat → drop.dup; soWyAcName with the typed ceiling
//     (THEATER_WEIYU_AC_MAX.name, root's ruling: a found name may be as long as a typed one) — empty / long / lead / chars / me → drop[why];
//     a living contact → have (his name, once); not in the sent text → drop.unfound; a group's name → an un-addable row {add: 'none', why:
//     'group', g}; else a row {add: 'new'} or, for a background member, {add: 'promote', pid}. Tags in order:
//     extra (在群里出现过), gone (以前删除过), near {w}. 来自 / 签名 come clipped to the AI caps (80) — what the row shows is what 添加 stores.
//     Row = {name, sig?, area?, tags: [{k, w?}], add, why?, g?, pid?, ex: {floor, text}}.
//   soWyAcAddFound(state, row) → pid | null — re-checked against the phone as it is NOW (a contact meanwhile / a group clash / any refusal →
//     null, nothing changed). New (a removed name included: a NEW person) → soWyAddPerson (AI caps 24 / 80 / 80; the name itself kept whole,
//     ≤ 40) + origin 'story', NO chat. Background member → his empty 签名 / 来自 filled from the row, soWyAcPromote (same pid: every group line
//     stays; NO chat), origin 'story'.
const THEATER_WEIYU_FIND_EX = 24;

// The first occurrence of `name` in `text` (case-insensitive) → its code-point index and length, or null.
function soWyFindAt(text, name) {
    const t = String(text == null ? '' : text);
    const n = String(name == null ? '' : name);
    if (!n || !t) return null;
    let m = null;
    try {
        m = new RegExp(n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'iu').exec(t);
    } catch (e) {
        m = null;
    }
    if (!m) return null;
    return { i: Array.from(t.slice(0, m.index)).length, len: Array.from(m[0]).length };
}

function soWyFindEx(src, name) {
    const s = soWyIsObj(src) ? src : {};
    const n = soWyNameKey(name);
    if (!n) return null;
    const flat = (v) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
    const cut = (text, at) => {
        const cps = Array.from(text);
        const a = Math.max(0, at.i - THEATER_WEIYU_FIND_EX);
        const b = Math.min(cps.length, at.i + at.len + THEATER_WEIYU_FIND_EX);
        return (a > 0 ? '…' : '') + cps.slice(a, b).join('') + (b < cps.length ? '…' : '');
    };
    const floors = Array.isArray(s.floors) ? s.floors : [];
    for (let i = floors.length - 1; i >= 0; i--) {
        const f = floors[i];
        if (!soWyIsObj(f)) continue;
        const text = flat(f.text);
        const at = soWyFindAt(text, n);
        if (at) return { floor: Number.isFinite(Number(f.n)) ? Math.floor(Number(f.n)) : null, text: cut(text, at) };
    }
    return null;
}

function soWyAcNear(state, name) {
    const k = soWyNameKey(name);
    const a = Array.from(k);
    if (a.length < 2 || !state || !soWyIsObj(state.people)) return '';
    for (const pid of Object.keys(state.people)) {
        if (pid === THEATER_WEIYU_ME) continue;
        const p = soWyPerson(state, pid);
        if (!p || p.gone === 1) continue;
        const o = soWyNameKey(p.name);
        const b = Array.from(o);
        if (o === k || b.length < 2) continue;
        if (k.includes(o) || o.includes(k)) return p.name;
        if (a.length >= 3 && a.length === b.length && a.filter((c, i) => c !== b[i]).length === 1) return p.name;
    }
    return '';
}

function soWyFindMatch(state, recs, src) {
    const out = { rows: [], have: [], drop: {} };
    const drop = (why) => { out.drop[why] = (out.drop[why] || 0) + 1; };
    const seen = new Set();
    for (const rec of Array.isArray(recs) ? recs : []) {
        if (!soWyIsObj(rec)) continue;
        const name = soWyNameKey(rec.name);
        const key = name.toLowerCase();
        if (name && seen.has(key)) {
            drop('dup');
            continue;
        }
        if (name) seen.add(key);
        const r = soWyAcName(state, name, THEATER_WEIYU_AC_MAX.name);
        if (r.why === 'contact') {
            const p = soWyPerson(state, r.pid);
            const shown = p && typeof p.name === 'string' ? p.name : name;
            if (!out.have.includes(shown)) out.have.push(shown);
            continue;
        }
        if (!r.ok && r.why !== 'group') {
            drop(r.why || 'empty');
            continue;
        }
        const ex = soWyFindEx(src, name);
        if (!ex) {
            drop('unfound');
            continue;
        }
        const row = { name, tags: [], add: 'new', ex };
        if (typeof rec.sig === 'string' && rec.sig.trim()) row.sig = soWyClip(rec.sig, 80);
        if (typeof rec.area === 'string' && rec.area.trim()) row.area = soWyClip(rec.area, 80);
        if (r.why === 'group') {
            Object.assign(row, { add: 'none', why: 'group', g: r.g });
            out.rows.push(row);
            continue;
        }
        if (r.info === 'extra') {
            row.tags.push({ k: 'extra' });
            row.add = 'promote';
            row.pid = r.pid;
        }
        if (r.info === 'gone') row.tags.push({ k: 'gone' });
        const w = soWyAcNear(state, name);
        if (w) row.tags.push({ k: 'near', w });
        out.rows.push(row);
    }
    return out;
}

function soWyAcAddFound(state, row) {
    if (!state || !soWyIsObj(state.people) || !soWyIsObj(row) || typeof row.name !== 'string') return null;
    const r = soWyAcName(state, row.name, THEATER_WEIYU_AC_MAX.name);
    if (!r.ok) return null;
    const fill = { name: row.name };
    if (typeof row.sig === 'string' && row.sig.trim()) fill.sig = row.sig;
    if (typeof row.area === 'string' && row.area.trim()) fill.area = row.area;
    if (r.info === 'extra') {
        if (soWyAddPerson(state, fill) !== r.pid || !soWyAcPromote(state, r.pid)) return null;
        state.people[r.pid].origin = 'story';
        return r.pid;
    }
    const pid = soWyAddPerson(state, fill);
    if (!pid || soWyPerson(state, pid).extra) return null;
    state.people[pid].name = soWyNameKey(row.name);
    state.people[pid].origin = 'story';
    return pid;
}

// ---- calls and transfers: the player's side and the derived status (phase 2 slice A; shapes above soWyCallNorm) -----------------------
//   soWyCanCall(state, chat, on) / soWyCanPay(state, chat, on) → bool   on = the join's ENABLE_THR_WEIYU_EVENTS (anything but true → false):
//     his own live private chat with a living contact he has not blocked. The send itself = soWyCall('send', {cid, msg: {t: 'call', mode}})
//     or {t: 'pay', amt?, note?} — ONE model call (soWySendKind stores his line first).
//   soWyPayStatus(state, chat|cid, mid) → {st: 'open'|'taken'|'back'|'expired', by?: mid} | null (not a transfer)
//   soWyCanPayAnswer(state, cid, mid) / soWyPayAnswer(state, cid, mid, 'taken'|'back') → his 收款 / 退回 of an open transfer TO HIM: one line
//     {t: 'text', u: 'me', v, ans: {ref, res}} (src 'me', read, touched). ZERO model calls — the screen commits; the model reads it next time.
//   soWyPayMark(state, cid, mid, 'taken'|'back'|null) → bool — the manual 当作已收 / 已退 on an open transfer TO A CHARACTER whose answer
//     came in prose only (study §4 risks); null clears it. Zero calls; touches the chat.
//   soWyCallMissedFirst(state, chat|cid) → the oldest UNREAD missed / cancelled call TO the player (a chat he is in) | null;
//     soWyCallMissed(state, chat) = that !== null (the list marker 「[未接来电]」 beside T.atMe).

// The other member of the player's own live private chat (soWyCanSendIn: never his blocked one), a living person; else null.
function soWyEvPeer(state, chat) {
    if (!soWyCanSendIn(state, chat) || chat.type !== 'dm' || !Array.isArray(chat.members) || chat.members.length !== 2) return null;
    const other = chat.members.find((pid) => pid !== THEATER_WEIYU_ME);
    const p = soWyPerson(state, other);
    return p && p.gone !== 1 ? other : null;
}

function soWyCanCall(state, chat, on) {
    return on === true && !!soWyEvPeer(state, chat);
}

function soWyCanPay(state, chat, on) {
    return on === true && !!soWyEvPeer(state, chat);
}

function soWyPayStatus(state, chat, mid) {
    const c = typeof chat === 'string' ? soWyChat(state, chat) : chat;
    const i = soWyMsgIndex(c, mid);
    if (i < 0) return null;
    const pay = c.msgs[i].t === 'text' ? soWyPayNorm(c.msgs[i].pay) : null;
    if (!pay) return null;
    for (let j = i + 1; j < c.msgs.length; j++) {
        const a = c.msgs[j];
        if (!soWyIsObj(a) || a.refused === 1 || a.t !== 'text') continue;
        const ans = soWyAnsNorm(a.ans);
        if (ans && ans.ref === mid) return { st: ans.res, by: a.id };
    }
    if (pay.mark) return { st: pay.mark };
    return { st: i < soWySumView(c).from ? 'expired' : 'open' };
}

function soWyCanPayAnswer(state, cid, mid) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0 || !soWyCanSendIn(state, chat)) return false;
    const pay = chat.msgs[i].t === 'text' ? soWyPayNorm(chat.msgs[i].pay) : null;
    if (!pay || pay.to !== THEATER_WEIYU_ME || chat.msgs[i].refused === 1) return false;
    const s = soWyPayStatus(state, chat, mid);
    return !!s && s.st === 'open';
}

function soWyPayAnswer(state, cid, mid, res) {
    if ((res !== 'taken' && res !== 'back') || !soWyCanPayAnswer(state, cid, mid)) return null;
    const ans = { ref: mid, res };
    const id = soWyAddMsg(state, cid, { t: 'text', u: THEATER_WEIYU_ME, v: soWyAnsText(ans), ans }, { b: soWyNewId(state, 'b'), src: 'me' });
    if (!id) return null;
    soWyMarkRead(state, cid);
    soWyTouch(state, cid);
    return id;
}

function soWyPayMark(state, cid, mid, res) {
    const chat = soWyChat(state, cid);
    const i = soWyMsgIndex(chat, mid);
    if (i < 0 || (res !== null && res !== 'taken' && res !== 'back')) return false;
    const m = chat.msgs[i];
    const pay = m.t === 'text' ? soWyPayNorm(m.pay) : null;
    if (!pay || pay.to === THEATER_WEIYU_ME) return false;
    if (res === null) {
        if (!soWyIsObj(m.pay) || !('mark' in m.pay)) return false;
        delete m.pay.mark;
    } else {
        const s = soWyPayStatus(state, chat, mid);
        if (!s || s.st !== 'open') return false;
        m.pay.mark = res;
    }
    soWyTouch(state, cid);
    return true;
}

function soWyCallMissedFirst(state, chat) {
    const c = typeof chat === 'string' ? soWyChat(state, chat) : chat;
    if (!soWyIsMine(c) || !Array.isArray(c.msgs)) return null;
    for (let i = soWyReadIndex(c) + 1; i < c.msgs.length; i++) {
        const m = c.msgs[i];
        if (!soWyCountsAsUnread(m) || m.u === THEATER_WEIYU_ME || m.to !== THEATER_WEIYU_ME) continue;
        const call = m.t === 'text' ? soWyCallNorm(m.call) : null;
        if (call && (call.st === 'missed' || call.st === 'cancel')) return m.id;
    }
    return null;
}

function soWyCallMissed(state, chat) {
    return soWyCallMissedFirst(state, chat) !== null;
}

// ---- Task 10: pictures — the index, file names, default avatars, and the import interface ---------------------------------
//
// Pictures are FILES (so-weiyu-*.png|jpg|webp, SO's user-files folder; the so- prefix is what soMediaDelete accepts), referenced by
// name — never image data, never in a prompt or the note, never inside the phone state (so 「reset keeps pictures」 holds).
// Root ruling 2026-11-15: pictures are remembered PER CHARACTER CARD; the player's own picture is GLOBAL. The join keeps ONE store,
// outside chat metadata (storage injected):
//   PicStore { v:1, me: file|null, cards: [{card: string, v:1, byName: {name, file}[], bg: file|null}] }
//            arrays only — a card key or a person's name is never used as an object key
//   Pics     { v:1, byName: {name, file}[], bg: file|null } — one card's entry (a store entry also carries `card`); keyed by the
//            person's NAME because pids change after a reset
//   soWyPicStoreNorm(raw): PicStore|null       never throws; unknown keys and bad files are dropped; the first entry of a card wins;
//                                              null = written by a NEWER build (soWyPicStoreForeign) — show defaults, never write back
//   soWyPicCard(store, card): entry|null        get or create that card's entry (null for a non-string / empty key or a bad store)
//   soWyPicMeGet(store): file|null · soWyPicMeSet(store, file): replaced|null · soWyPicMeClear(store): file|null
//   soWyPicsNorm(raw): Pics · soWyPicFileOk(name) · soWyPicNewName(rand, ext?)
//   soWyPicGet(pics, name): file|null · soWyPicSet(pics, name, file): replaced|null · soWyPicClear(pics, name): file|null
//   soWyBgSet(pics, file|null): replaced|null   — every setter returns the file it replaced, so the caller can io.remove() it;
//                                                 a name that fails soWyPicFileOk is refused (returns null, stores nothing)
//   soWyAvatarOf(state, pics, pid, io, me?): {kind:'img', src} | {kind:'tile', ch, hue}
//     `me` = OPTIONAL 5th argument (root ruling; the plan's 4-argument calls still work) — the player's global file, i.e.
//     soWyPicMeGet(store). Order: imported picture (pid 'me' → `me` only; anyone else → soWyPicGet(pics, name)) via io.url(file)
//     → pid 'me': io.stAvatar('user') · a person with main:1: io.stAvatar('char') → a tile: ch = the name's first code point,
//     hue = a stable hash of the name % 12.
// picIO — the interface the join satisfies:
//   pick(kind: 'avatar'|'background'): Promise<{file: string}|null>   file picker → type check → crop dialog → upload; null when
//                                                                     cancelled or failed, after telling the player why
//   url(file): string · remove(file): Promise<void> · stAvatar(who: 'char'|'user'): string ('' when none)

const THEATER_WEIYU_PIC_RE = /^so-weiyu-[a-z0-9]{6,16}\.(png|jpg|webp)$/;
const THEATER_WEIYU_PIC_SCHEMA = 1;

function soWyPicFileOk(name) {
    return typeof name === 'string' && THEATER_WEIYU_PIC_RE.test(name);
}

function soWyPicNewName(rand, ext) {
    const r = typeof rand === 'function' ? rand : Math.random;
    let s = '';
    for (let i = 0; i < 10; i++) {
        let x = 0;
        try { x = Number(r()); } catch (e) { x = 0; }
        if (!Number.isFinite(x)) x = 0;
        s += Math.min(35, Math.max(0, Math.floor(x * 36))).toString(36);
    }
    const e = String(ext == null ? '' : ext).toLowerCase().replace(/^\./, '');
    const fx = e === 'jpeg' ? 'jpg' : (['png', 'jpg', 'webp'].includes(e) ? e : 'png');
    return 'so-weiyu-' + s + '.' + fx;
}

function soWyPicsNorm(raw) {
    const out = { v: 1, byName: [], bg: null };
    try {
        if (!soWyIsObj(raw)) return out;
        for (const e of Array.isArray(raw.byName) ? raw.byName : []) {
            if (!soWyIsObj(e) || !soWyPicFileOk(e.file)) continue;
            const name = soWyClip(soWyNameKey(e.name), 40);
            if (!name || out.byName.some((x) => x.name === name)) continue;
            out.byName.push({ name, file: e.file });
        }
        if (soWyPicFileOk(raw.bg)) out.bg = raw.bg;
        return out;
    } catch (e) {
        return { v: 1, byName: [], bg: null };
    }
}

function soWyPicIndex(pics, name) {
    if (!soWyIsObj(pics) || !Array.isArray(pics.byName)) return -1;
    const k = soWyNameKey(name);
    if (!k) return -1;
    return pics.byName.findIndex((x) => soWyIsObj(x) && soWyNameKey(x.name) === k);
}

function soWyPicGet(pics, name) {
    const i = soWyPicIndex(pics, name);
    return i >= 0 && soWyPicFileOk(pics.byName[i].file) ? pics.byName[i].file : null;
}

function soWyPicSet(pics, name, file) {
    if (!soWyIsObj(pics) || !soWyPicFileOk(file)) return null;
    const k = soWyClip(soWyNameKey(name), 40);
    if (!k) return null;
    if (!Array.isArray(pics.byName)) pics.byName = [];
    const i = soWyPicIndex(pics, k);
    if (i < 0) {
        pics.byName.push({ name: k, file });
        return null;
    }
    const old = pics.byName[i].file;
    pics.byName[i].file = file;
    return soWyPicFileOk(old) && old !== file ? old : null;
}

function soWyPicClear(pics, name) {
    const i = soWyPicIndex(pics, name);
    if (i < 0) return null;
    const x = pics.byName.splice(i, 1)[0];
    return soWyPicFileOk(x.file) ? x.file : null;
}

function soWyBgSet(pics, file) {
    if (!soWyIsObj(pics) || (file !== null && !soWyPicFileOk(file))) return null;
    const old = pics.bg;
    pics.bg = file;
    return soWyPicFileOk(old) && old !== file ? old : null;
}

// A store written by a NEWER build: detectable, never rewritten (same rule as the phone state's soWyNorm / soWyIsForeign).
// soWyPicStoreNorm returns null for it; a caller holding null cannot write (every reader / setter answers null).
function soWyPicStoreForeign(raw) {
    return soWyIsObj(raw) && Number(raw.v) > THEATER_WEIYU_PIC_SCHEMA;
}

function soWyPicStoreNorm(raw) {
    const out = { v: THEATER_WEIYU_PIC_SCHEMA, me: null, cards: [] };
    try {
        if (soWyPicStoreForeign(raw)) return null;
        if (!soWyIsObj(raw)) return out;
        if (soWyPicFileOk(raw.me)) out.me = raw.me;
        for (const c of Array.isArray(raw.cards) ? raw.cards : []) {
            if (!soWyIsObj(c) || typeof c.card !== 'string' || !c.card || out.cards.some((x) => x.card === c.card)) continue;
            out.cards.push(Object.assign({ card: c.card }, soWyPicsNorm(c)));
        }
        return out;
    } catch (e) {
        return { v: 1, me: null, cards: [] };
    }
}

function soWyPicCard(store, card) {
    if (!soWyIsObj(store) || typeof card !== 'string' || !card) return null;
    if (!Array.isArray(store.cards)) store.cards = [];
    const hit = store.cards.find((c) => soWyIsObj(c) && c.card === card);
    if (hit) return hit;
    const entry = { card, v: 1, byName: [], bg: null };
    store.cards.push(entry);
    return entry;
}

function soWyPicMeGet(store) {
    return soWyIsObj(store) && soWyPicFileOk(store.me) ? store.me : null;
}

function soWyPicMeSet(store, file) {
    if (!soWyIsObj(store) || !soWyPicFileOk(file)) return null;
    const old = store.me;
    store.me = file;
    return soWyPicFileOk(old) && old !== file ? old : null;
}

function soWyPicMeClear(store) {
    if (!soWyIsObj(store)) return null;
    const old = store.me;
    store.me = null;
    return soWyPicFileOk(old) ? old : null;
}

function soWyAvatarOf(state, pics, pid, io, me) {
    const x = soWyIsObj(io) ? io : {};
    const call = (fn, arg) => {
        try {
            return typeof fn === 'function' ? String(fn(arg) || '') : '';
        } catch (e) {
            return '';
        }
    };
    const person = soWyPerson(state, pid);
    const name = person && typeof person.name === 'string' ? person.name : '';
    const file = pid === THEATER_WEIYU_ME ? (soWyPicFileOk(me) ? me : null) : soWyPicGet(pics, name);
    if (file) {
        const src = call(x.url, file);
        if (src) return { kind: 'img', src };
    }
    if (pid === THEATER_WEIYU_ME || (person && person.main)) {
        const src = call(x.stAvatar, pid === THEATER_WEIYU_ME ? 'user' : 'char');
        if (src) return { kind: 'img', src };
    }
    const chars = Array.from(name.trim());
    let h = 7;
    for (const c of chars) h = (h * 31 + c.codePointAt(0)) >>> 0;
    return { kind: 'tile', ch: chars[0] || '?', hue: h % 12 };
}

// (pure) The letters of a letter avatar (refined list, owner 2026-11-17 — the way work messengers draw them). TWO characters where the
// name allows, else one:
//   · a middle dot anywhere (艾伦·耶格尔, Jean·Luc — a transliterated / Western full name) → its first character;
//   · all Chinese characters: a trailing title (THEATER_WEIYU_AV_TITLES: 学姐, 老师, …) is dropped first when something is left
//     (白露学姐 → 白露, 王老师 → 王); then 1 → it, 2 → both (程野), 3 → the given name = the last two (苏芷宁 → 芷宁), 4+ → the last two
//     (上官婉儿 → 婉儿, 宫水三叶 → 三叶);
//   · Latin letters only (with spaces, - ' .): the initials, upper case — one word → one, two or more → first + last (Ada Lovelace → AL);
//   · anything else (mixed scripts, kana, an emoji) → the first character (a Latin one upper-cased); empty → '?'.
// Mosaic tiles never use this (one character per tile: soWyAvatarOf's ch).
const THEATER_WEIYU_AV_TITLES = Object.freeze(['学姐', '学长', '学妹', '学弟', '师姐', '师兄', '师妹', '师弟', '老师', '同学', '前辈', '先生', '小姐', '阿姨', '叔叔', '医生', '教授', '班长', '社长']);

function soWyAvLabel(name) {
    const s = typeof name === 'string' ? name.trim() : '';
    const chars = Array.from(s);
    if (!chars.length) return '?';
    const up = (c) => (/\p{Script=Latin}/u.test(c) ? c.toUpperCase() : c);
    if (/[·・•‧･]/.test(s)) return up(chars.find((c) => !/[·・•‧･\s]/.test(c)) || chars[0]);
    if (/^\p{Script=Han}+$/u.test(s)) {
        let han = chars;
        const title = THEATER_WEIYU_AV_TITLES.find((x) => s.length > x.length && s.endsWith(x));
        if (title) han = Array.from(s.slice(0, s.length - title.length));
        return han.length <= 2 ? han.join('') : han.slice(-2).join('');
    }
    if (/\p{Script=Latin}/u.test(s) && /^[\p{Script=Latin}\s'’.\-]+$/u.test(s)) {
        const words = s.split(/\s+/).map((w) => Array.from(w).find((c) => /\p{Script=Latin}/u.test(c))).filter(Boolean);
        if (!words.length) return up(chars[0]);
        return words.length === 1 ? up(words[0]) : up(words[0]) + up(words[words.length - 1]);
    }
    return up(chars[0]);
}
