const THEATER_WEIYU_PEND_FMT_PAY = '写法：收下写 甲〔收款〕：一句话，退回写 甲〔退回〕：一句话；甲是收钱的人。';
// FROZEN 2026-11-17 after probe gm-events (root's addition 1, from probe gm-block: a standing fact is inert or overboard, so the notice
// is ONE code-triggered beat; gm-events AMEND-1's 「…｜{name}还没反应」 ending was rejected). The item line of a contact the player just blocked; {me} = the owner, {name} = the blocked person.
const THEATER_WEIYU_PEND_BLOCK = '拉黑｜{me} 把 {name} 拉黑了｜{name}刚发现：发给{me}的私聊被拒收';
// FROZEN 2026-11-17 after probe gm-events (with it the notice met the bar 8 of 8 on Gemini, without it 3 of 3 were overboard — it must
// stay on in the product). The restraint line, only when a block item is present (several: the names joined with 、); a rig turns it off
// with soWyPendingText(…, {hold: false}).
const THEATER_WEIYU_PEND_BLOCK_HOLD = '写法：{name}顶多一两句带过，旁人不必接话。';

// DRAFT (round 5, 2026-11-15) — the very last line of a send / more / regen request ({chat} = the target's 【聊天】 reference, the
// string soWyChatRef writes in that chat's log header and the parser takes back). W-reply-v4: 3 / 8 replies went into ANOTHER chat —
// the kind texts point at the target only by position (「最后列出的那个聊天」) and the 抢话-off block sat between that log and the end.
// Not for group (proven as is in W-reply-v2 / W-sync-v2…v4), sync (many chats by nature; it ends with P_SYNC_FORM), boot / sum. FROZEN 2026-11-15 (W-reply-v5:
// off-chat 0 / 8; the composition accepted by Prince; sha256 pinned).
const THEATER_WEIYU_P_TARGET = '这份回复的每一行都属于「{chat}」这个聊天，其他聊天这一次保持原样。';

// FROZEN 2026-11-15 (sha256 pinned in weiyu-prompts-pin.test.mjs; a byte change = re-run its probe)
const THEATER_WEIYU_P_STEAL_ON ='回复里可以有几条「{me}」自己发的消息，口吻像他平时，只占这批消息的少数；要他拿主意的回答（答应、拒绝、约定）留给玩家来发。';

// The owner's name as the prompts write it ('我' when the state has none).
function soWyPromptMe(state) {
    try {
        const p = soWyPerson(state, THEATER_WEIYU_ME);
        const n = p && typeof p.name === 'string' ? soWyFlat(p.name) : '';
        return n || '我';
    } catch (e) {
        return '我';
    }
}

// The kind's own text (regen → P_SEND for the player's own line, P_MORE otherwise); '' for an unknown kind.
function soWyPromptKind(kind, plan) {
    switch (kind) {
        case 'boot': return THEATER_WEIYU_P_BOOT;
        case 'send': return THEATER_WEIYU_P_SEND;
        case 'more': return THEATER_WEIYU_P_MORE;
        case 'group': return THEATER_WEIYU_P_GROUP;
        case 'regen': return plan && plan.asMe ? THEATER_WEIYU_P_SEND : THEATER_WEIYU_P_MORE;
        case 'sync': return THEATER_WEIYU_P_SYNC;
        case 'sum': return THEATER_WEIYU_P_SUM;
        default: return '';
    }
}

// The dice paragraph for the rolled kinds (args.kinds), '' when nothing (known) was rolled or the kind takes none: sync → the
// sync tail (who and in which chat), send / more / regen → the one-chat tail; boot (2026-11-18) → the sync tail; group / sum → empty always. Unknown kinds are
// skipped, a repeat counts once; the order is the roll's. words (optional, trailing; world wording step 2): the phone-stage set — each
// moment's prose through its overlay rows (rows 8–14; the 「（写成 …）」 tails, HEAD / JOIN / TAIL and the other moments as today).
function soWyDiceText(kind, kinds, words) {
    try {
        const w = soWyPhoneWords(words);
        // 开机 (owner 2026-11-18, "allow it"): the sync tail — many chats, who and in which chat (the frozen texts, untouched)
        const tail = kind === 'sync' || kind === 'boot' ? THEATER_WEIYU_DICE_TAIL.sync
            : (kind === 'send' || kind === 'more' || kind === 'regen' ? THEATER_WEIYU_DICE_TAIL.reply : '');
        if (!tail || !Array.isArray(kinds)) return '';
        const list = [];
        // phase 2: an event kind's moment comes from THEATER_WEIYU_DICE_EV_MOMENTS (frozen); the live kinds read the pinned table as before
        // phase 3: `fwd` from THEATER_WEIYU_DICE_EV_MOMENTS_P3 (frozen after probe gm-fwd)
        const moment = (k) => (soWyOwn(THEATER_WEIYU_DICE_MOMENTS, k) ? soWyWordsAt('THEATER_WEIYU_DICE_MOMENTS.' + k, THEATER_WEIYU_DICE_MOMENTS[k], w)
            : (soWyOwn(THEATER_WEIYU_DICE_EV_MOMENTS, k) ? soWyWordsAt('THEATER_WEIYU_DICE_EV_MOMENTS.' + k, THEATER_WEIYU_DICE_EV_MOMENTS[k], w)
                : (soWyOwn(THEATER_WEIYU_DICE_EV_MOMENTS_P3, k) ? soWyWordsAt('THEATER_WEIYU_DICE_EV_MOMENTS_P3.' + k, THEATER_WEIYU_DICE_EV_MOMENTS_P3[k], w) : '')));
        for (const k of kinds) if (typeof k === 'string' && moment(k) && !list.includes(k)) list.push(k);
        if (!list.length) return '';
        return THEATER_WEIYU_DICE_HEAD + '可以' + list.map(moment).join(THEATER_WEIYU_DICE_JOIN) + tail;
    } catch (e) {
        return '';
    }
}

// ---- the pending-state block (more functions phase 2 slice A; study "Shared mechanisms" B + root's addition 1) ----------------------
// soWyPendingItems(state, scope) → item[] (pure; [] when nothing is pending):
//   scope = a chat id (send / more / regen: that chat's items only) or null (a sync: every chat).
//   {k: 'block', pid}                 a contact the player blocked since this build (p.blocked + p.blockNote): in scope in a sync, or when the
//                                     target chat has them as a member — never his blocked private chat with them. Shown ONCE: soWyCall
//                                     deletes blockNote when a request that carried it landed.
//   {k: 'pay', cid, mid}              an open transfer (soWyPayStatus) TO a character (never to the player: his to answer, on the phone)
//   {k: 'call', cid, mid}             a missed / cancelled call TO a character whose callee has said nothing in that chat since
//   {k: 'at', cid, mid, to}           the PLAYER's own @ of a character (in a group) who has not spoken since, while someone else has (his @
//                                     in the request's own last line is its own cue); never an @ of the player (study §5)
//   Message items: lines made after 开机 only (src 'boot' = history), not refused, shown fewer than twice (m.pend, counted by soWyCall when
//   the reply landed). Chats dissolved / closed are skipped. Order: block · pay · call · @ (each newest first); at most 4.
// soWyPendingText(state, scope, opts?) → '' | the block: THEATER_WEIYU_PEND_HEAD, one line per item, then THEATER_WEIYU_PEND_FMT_PAY when a
//   transfer is there and THEATER_WEIYU_PEND_BLOCK_HOLD when a block item is there (opts.hold === false leaves that line out — the probe
//   rig's toggle). opts.items = render these items instead of computing them (soWyCall passes the list it counts).
// The request carries it as args.pending (soWyPrompt: send / more / regen right after the log, before the 抢话-off block — gm-events
// AMEND-2 "V1"; sync before the dice and the form); a request carrying it rolls no dice (soWyCall).
const THEATER_WEIYU_PEND_MAX = 4;

function soWyPendingItems(state, scope) {
    const out = [];
    try {
        if (!soWyIsObj(state) || !soWyIsObj(state.people) || !soWyIsObj(state.chats)) return out;
        const one = typeof scope === 'string' ? scope : null;
        const live = (c) => soWyIsObj(c) && !c.dissolved && !soWyChatClosed(state, c) && Array.isArray(c.msgs) && Array.isArray(c.members);
        const target = one ? soWyChat(state, one) : null;
        if (one && !live(target)) return out;
        const block = [];
        for (const pid of Object.keys(state.people)) {
            const p = soWyPerson(state, pid);
            if (!p || pid === THEATER_WEIYU_ME || p.gone === 1 || p.blocked !== 1 || p.blockNote !== 1) continue;
            if (target && (!target.members.includes(pid) || soWyRefuses(state, target, pid))) continue;
            block.push({ k: 'block', pid });
        }
        const msgItems = { pay: [], call: [], at: [] };
        for (const cid of one ? [one] : soWyChatList(state)) {
            const chat = soWyChat(state, cid);
            if (!live(chat)) continue;
            const msgs = chat.msgs;
            const saidAfter = (i, pid) => msgs.slice(i + 1).some((x) => soWyIsObj(x) && x.u === pid && x.refused !== 1 && x.t !== 'sys' && x.t !== 'time');
            for (let i = 0; i < msgs.length; i++) {
                const m = msgs[i];
                if (!soWyIsObj(m) || m.refused === 1 || m.src === 'boot' || (Number(m.pend) || 0) >= 2) continue;
                const at = soWyIdNum(m.id);
                const kind = soWyEvKind(m);
                if (kind === 'pay') {
                    const pay = soWyPayNorm(m.pay);
                    const s = soWyPayStatus(state, chat, m.id);
                    if (pay.to !== THEATER_WEIYU_ME && s && s.st === 'open' && chat.members.includes(pay.to)) msgItems.pay.push({ k: 'pay', cid, mid: m.id, at });
                } else if (kind === 'call') {
                    const call = soWyCallNorm(m.call);
                    if ((call.st === 'missed' || call.st === 'cancel') && typeof m.to === 'string' && m.to !== THEATER_WEIYU_ME
                        && chat.members.includes(m.to) && !saidAfter(i, m.to)) msgItems.call.push({ k: 'call', cid, mid: m.id, at });
                } else if (chat.type === 'group' && m.u === THEATER_WEIYU_ME && !m.ai && m.src === 'me' && THEATER_WEIYU_SAID.includes(m.t)) {
                    const later = msgs.slice(i + 1).some((x) => soWyIsObj(x) && x.refused !== 1 && x.t !== 'time' && x.t !== 'sys');
                    if (!later) continue;
                    for (const to of soWyAtOf(state, chat, m).ids) {
                        const p = soWyPerson(state, to);
                        if (to === THEATER_WEIYU_ME || !p || p.gone === 1 || saidAfter(i, to)) continue;
                        msgItems.at.push({ k: 'at', cid, mid: m.id, to, at });
                    }
                }
            }
        }
        const newest = (a, b) => b.at - a.at;
        return block.concat(msgItems.pay.sort(newest), msgItems.call.sort(newest), msgItems.at.sort(newest)).slice(0, THEATER_WEIYU_PEND_MAX)
            .map((x) => { const y = Object.assign({}, x); delete y.at; return y; });
    } catch (e) {
        return [];
    }
}

function soWyPendingText(state, scope, opts) {
    try {
        const o = soWyIsObj(opts) ? opts : {};
        const items = Array.isArray(o.items) ? o.items : soWyPendingItems(state, scope);
        if (!items.length) return '';
        const me = soWyField(soWyPromptMe(state));
        const nm = (pid) => soWyField(soWyPersonName(state, pid));
        const I = THEATER_WEIYU_PEND_ITEM;
        const lines = [THEATER_WEIYU_PEND_HEAD];
        const held = [];
        let paid = false;
        for (const it of items) {
            if (!soWyIsObj(it)) continue;
            if (it.k === 'block') {
                lines.push(soWyTpl(THEATER_WEIYU_PEND_BLOCK, { me, name: nm(it.pid) }));
                held.push(nm(it.pid));
                continue;
            }
            const chat = soWyChat(state, it.cid);
            const m = chat ? chat.msgs[soWyMsgIndex(chat, it.mid)] : null;
            if (!m) continue;
            const ref = '「' + soWyField(soWyChatRef(state, chat)) + '」';
            if (it.k === 'pay') {
                const pay = soWyPayNorm(m.pay);
                lines.push(soWyTpl(I.pay, { chat: ref, from: nm(m.u), to: nm(pay.to),
                    amt: pay.amt ? soWyTpl(I.amt, { amt: soWyField(pay.amt) }) : '', note: pay.note ? soWyTpl(I.note, { note: soWyField(pay.note) }) : '' }));
                paid = true;
            } else if (it.k === 'call') {
                const call = soWyCallNorm(m.call);
                lines.push(soWyTpl(I.call, { chat: ref, from: nm(m.u), to: nm(m.to), mode: THEATER_WEIYU_CALL_KIND[call.mode], st: call.st === 'cancel' ? I.cancel : I.missed }));
            } else if (it.k === 'at') {
                lines.push(soWyTpl(I.at, { chat: ref, from: nm(m.u), to: nm(it.to) }));
            }
        }
        if (lines.length < 2) return '';
        if (paid) lines.push(THEATER_WEIYU_PEND_FMT_PAY);
        if (held.length && o.hold !== false) lines.push(soWyTpl(THEATER_WEIYU_PEND_BLOCK_HOLD, { name: held.join('、') }));
        return lines.join('\n');
    } catch (e) {
        return '';
    }
}

// The heading lines a sync hands over: 【聊天】<reference> per chat that is not dissolved, in the list order.
function soWySyncHeads(state) {
    return soWyChatList(state).map((cid) => soWyChat(state, cid)).filter((ch) => ch && !ch.dissolved && !soWyChatClosed(state, ch)).map((ch) => '【聊天】' + soWyChatRef(state, ch));
}

function soWyPromptBuild(kind, state, a) {
    if (kind === 'call') return soWyCallPrompt(state, a);   // the live call scene (2026-11-18): its own focused request, below
    const me = soWyPromptMe(state);
    const mem = a.mem === true;   // the memory slice (ENABLE_THR_WEIYU_MEMORY → deps.mem → args.mem); not true = the request as before
    // world wording step 2 (ENABLE_THR_WEIYU_WORDS_PHONE → deps.words → args.words): a phone-stage set, else null = the request as before.
    // P_COMMON (rows 1–4), P_BOOT (5), P_SYNC (6), the owner line (7, brief / 开机 / 总结) and the dice moments (8–14) are overlaid as TEMPLATES,
    // before {me} / {chat} and every name, log, summary and notice are filled in by the code below. 总结 included (root's ruling A6).
    const words = soWyPhoneWords(a.words);
    // adding contacts by hand (deps.ac → args.ac): the 【人】 rows of hand-added people carry their marker / 人物说明; not true = the brief as before
    const ac = a.ac === true ? { ac: true } : undefined;
    const plan = kind === 'regen' ? soWyRegenPlan(state, a.cid, a.mid) : null;
    const own = soWyPromptKind(kind, plan);
    if (!own) return { system: '', user: '' };
    // sync every N (args.n ≥ 2, only from the join's ENABLE_THR_WEIYU_SYNC_EVERY path): the multi-floor variant (soWySyncLead / soWySyncForm);
    // args.at (a chat index) = the story history carries the divider → its lead; absent → the whole-history lead. n = 1 / absent → 0 here =
    // the frozen lead and form, byte for byte
    const multi = kind === 'sync' && Number.isSafeInteger(a.n) && a.n >= 2 ? a.n : 0;
    const ownAt = kind === 'boot' ? 'THEATER_WEIYU_P_BOOT' : (kind === 'sync' ? (multi ? 'THEATER_WEIYU_P_SYNC_MULTI' : 'THEATER_WEIYU_P_SYNC') : '');
    const ownText = multi ? soWySyncLead(multi, Number.isSafeInteger(a.at)) : own;
    const parts = words ? [soWyWordsAt('THEATER_WEIYU_P_COMMON', THEATER_WEIYU_P_COMMON, words), THEATER_WEIYU_P_FORMAT, ownAt ? soWyWordsAt(ownAt, ownText, words) : ownText]
        : [THEATER_WEIYU_P_COMMON, THEATER_WEIYU_P_FORMAT, ownText];
    const bound = kind === 'send' || kind === 'more' || kind === 'group' || kind === 'regen';
    const chat = bound ? soWyChat(state, a.cid) : null;
    if (chat && Array.isArray(chat.members) && !chat.members.includes(THEATER_WEIYU_ME)) parts.push(THEATER_WEIYU_P_UNSEEN);
    // 抢话 on → P_STEAL_ON closes `system`; 抢话 off → the 抢话-off block closes `user` (= the end of the request, round 4; a sync's
    // block is P_STEAL_SYNC, probe gm-ask's T2 since 2026-11-16 — the dice paragraph and the form block still follow it)
    let offBlock = '';
    if (kind !== 'boot' && kind !== 'sum') {
        const steal = soWyIsObj(state) && soWyIsObj(state.opts) && state.opts.steal === true;
        if (steal) parts.push(THEATER_WEIYU_P_STEAL_ON);
        else offBlock = (kind === 'sync' ? THEATER_WEIYU_P_STEAL_SYNC : THEATER_WEIYU_P_STEAL_OFF).split('{me}').join(me);
    }
    const system = parts.join('\n\n').split('{me}').join(me);
    const owner = soWyWordsAt('THEATER_WEIYU_OWNER_LINE', THEATER_WEIYU_OWNER_LINE, words).split('{me}').join(me);
    let user = '';
    if (kind === 'boot') {
        user = owner;
    } else if (kind === 'sync') {
        user = [soWyBrief(state, words, ac)].concat(soWyChatList(state).filter((cid) => !soWyChatClosed(state, soWyChat(state, cid)))
            .map((cid) => soWyLog(state, cid, { keep: mem ? THEATER_WEIYU_SYNC_KEEP : 8, callLines: THEATER_WEIYU_CALL_CAP.logOther }))).filter(Boolean).join('\n\n');
    } else if (kind === 'sum') {
        const sp = typeof soWySumPlan === 'function' ? soWySumPlan(state) : null;
        const items = soWyIsObj(sp) && Array.isArray(sp.items) ? sp.items : [];
        user = [owner].concat(items.map((it) => soWyLog(state, it.cid, { upTo: it.through, keep: it.count }))).filter(Boolean).join('\n\n');
    } else if (mem) {
        // the memory slice: the target's last soWyMemKeepOpt lines word for word + every chat its characters were ever in (their windows)
        const pids = soWyMemFor(state, chat);
        const keep = soWyMemKeepOpt(state);
        const log = kind === 'regen' && plan ? soWyLogMem(state, a.cid, { keep, upTo: plan.anchor }) : soWyLogMem(state, a.cid, { keep });
        user = [soWyBriefMem(state, a.cid, pids, words, ac), soWyOthersMem(state, a.cid, pids), log].filter(Boolean).join('\n\n');
    } else {
        const log = kind === 'regen' && plan ? soWyLog(state, a.cid, { upTo: plan.anchor }) : soWyLog(state, a.cid);
        user = [soWyBrief(state, words, ac), soWyOthers(state, a.cid), log].filter(Boolean).join('\n\n');
    }
    // the dice (args.kinds, rolled once per call by soWyCall): [] / missing = no paragraph = the request byte for byte without it
    const dice = soWyDiceText(kind, a.kinds, words);
    // phase 2: the pending-state block (args.pending, soWyPendingText — built by soWyCall, or by a rig): sync — right before the dice;
    // send / more / regen — right after the log (follow-up (d), below). sync / send / more / regen only. Missing / '' = byte for byte without it.
    const pend = typeof a.pending === 'string' && (kind === 'sync' || kind === 'send' || kind === 'more' || kind === 'regen') ? a.pending : '';
    if (kind === 'sync') {
        // round 3 "the form": the heading hand-over · the sync 防抢话 block (抢话 off) · the dice · the strict form, LAST
        const heads = [THEATER_WEIYU_P_SYNC_HEADS_INTRO].concat(soWySyncHeads(state), [THEATER_WEIYU_P_SYNC_HEADS_NEW]).join('\n');
        user = [user, heads.split('{me}').join(me), offBlock, pend, dice, soWySyncForm(multi).split('{me}').join(me)].filter(Boolean).join('\n\n');
        return { system, user };
    }
    // round 5: send / more / regen close the request by naming the target chat (after the 抢话-off block when 抢话 is off); the
    // dice paragraph, when rolled, follows it
    const ref = kind === 'send' || kind === 'more' || kind === 'regen' ? soWyChatRef(state, chat) : '';
    const target = ref ? THEATER_WEIYU_P_TARGET.split('{chat}').join(ref) : '';
    // follow-up (d), probe gm-events AMEND-2 "V1" (root 2026-11-17): the pending block right after the chat log, BEFORE the 抢话-off block —
    // the request then ends exactly as one with nothing pending (DeepSeek wrote lines as the player with the block at the very end)
    user = [user, pend, offBlock, target, dice].filter(Boolean).join('\n\n');
    return { system, user };
}

function soWyPrompt(kind, state, args) {
    const a = soWyIsObj(args) ? args : {};
    let out;
    try {
        out = soWyPromptBuild(kind, state, a);
    } catch (e) {
        out = { system: '', user: '' };
    }
    try {
        if (typeof window !== 'undefined' && typeof window.__soWyArm === 'function') {
            const v = window.__soWyArm(kind, state, a, { system: out.system, user: out.user });
            if (v && typeof v === 'object') return v;
        }
    } catch (e) { /* a broken battery seam never breaks a call */ }
    return out;
}

// ---- the live call scene (call scene slice A, 2026-11-18; probe gm-callscene, tests/unit/_weiyu/_probes/gm-callscene/) -------------------
// soWyPrompt('call', state, {cid, mode}) = START (it rings) · {cid, mid} = TURN (the live call `mid` of that chat; the transcript so far). The
// probe's FOCUSED shape, byte for byte its feeds (weiyu-call-prompt.test.mjs): no P_COMMON / P_FORMAT / P_SEND / P_STEAL_OFF / P_TARGET, no
// dice, no pending block — the phone's mechanics stay out; hard guarantees live in code (soWyCallRead, soWyCall's call branch).
//   system = CALL_LEAD ({me} / {name} / {mode} filled; the engine appends the card, the story floors ride as for a send)
//   user   = soWyBriefFor(state, [her]) · soWyOthersFor(state, cid, [her], Infinity) (every un-summarised line + the 「（此前：…）」 line of each
//            chat SHE is a member of; the player's membership alone never counts) · soWyLog(state, cid) (this private chat as the product shows
//            it, keep 40) · the call paragraph: CALL_HEAD with 正在响铃 (START) / 已接通 + the transcript (TURN: her lines with tags, his lines,
//            画面 lines of a video; the last THEATER_WEIYU_CALL_CAP.turns turns, ending on his newest line) · CALL_FORM[mode], LAST.
//   A TURN's request is built on the phone WITHOUT the live call message (it rides only in the call paragraph — no echo, no reordering of
//   the brief's rows by the call's own activity).
// FROZEN 2026-11-18 after probe gm-callscene (sha256 pinned in weiyu-prompts-pin.test.mjs "ninth freeze"; a byte change = re-run gm-callscene):
// CALL_LEAD, CALL_FORM.video (= the winner Bp, REPORT.md), CALL_FORM.voice (= T1 of the voice-tag follow-up, REPORT-TAGS.md — only its tag
// slot differs from Bp: 六个字以内), CALL_HEAD, CALL_STEP. Each form is ONE line below, so a later replacement is that line + its pin line.
const THEATER_WEIYU_CALL_LEAD = '这一次是「{me}」打给「{name}」的{mode}，不是打字聊天。';
const THEATER_WEIYU_CALL_FORM = {
    voice: '这份回复照下面的样子写，〈〉连同里面的字换成实际内容：\n{name}：（〈语气或听得到的声音，六个字以内，可省〉）〈说出口的话〉\n话 1–4 行，口语，不带表情符号、图片和打字的习惯；（）不必每行都有。\n电话还在响时不接，只写一行：未接，或 拒接｜〈原因〉\n通话由「{me}」来挂；「{name}」只有此刻非走不可，才在最后一行写：挂断\n回复里没有「{me}」的话。',
    video: '这份回复照下面的样子写，〈〉连同里面的字换成实际内容：\n画面：〈「{me}」屏幕上此刻看到的；手机在「{name}」自己手里或架着〉\n{name}：（〈几个字的语气或听得到的声音，可省〉）〈说出口的话〉\n话 1–4 行，口语，不带表情符号、图片和打字的习惯；（）不必每行都有。\n电话还在响时不接，只写一行：未接，或 拒接｜〈原因〉\n通话由「{me}」来挂；「{name}」只有此刻非走不可，才在最后一行写：挂断\n回复里没有「{me}」的话。',
};
const THEATER_WEIYU_CALL_HEAD = '〔{mode}〕{me} → {name}｜{st}';
const THEATER_WEIYU_CALL_STEP = { ring: '正在响铃', live: '已接通' };
// DRAFT 2026-11-18 (root's ruling on what later requests see; not model-probed): a video turn's picture in a LATER log is its own line in
// （） — a bare 「画面：…」 there would read as a speaker named 画面 in the 名字：话 log format; in the live request it stays the probe's 画面：….
const THEATER_WEIYU_CALL_PIC = '（画面：{v}）';

// ---- world words, step 2: the phone's own requests (ENABLE_THR_WEIYU_WORDS_PHONE; spec 2026-11-18-world-wording-design.md §2.2 S1–S15 / §3.1;
// plan 2026-11-18-world-wording-2 C3 / C4) ----------------------------------------------------------------------------------------------
// DRAFT until gm-words step 2 (root Task RP2) — sha256 pinned in weiyu-words-phone-pin.test.mjs; after that check a byte change = re-run it.
// The phone overlay: rows {at, find, put, n: 1, stage: 2 (= THEATER_WEIYU_WORDS_STAGE.phone), dir, fid} applied by note.js soWyOverlay — for a
// phone-stage set only, to a per-render COPY of the frozen constant's template text, BEFORE today's code fills {me} / {name} / {mode} with
// names; the frozen constants keep their bytes, and with no set (现代) no row ever runs (the request is the constant itself). `put` holds
// {w:<TermId>} (the set's word through soWyWordsSafe) and {w:<grammar key>} (the set's phrase as soWyWordsBuild built it). dir = a direction
// line (the rows the gm-words step-2 check reads closely); fid = filled with the 现代 words the row gives back today's phrase — every row
// but the tone line (tone line A, root's call: no 现代 words rebuild 「无论故事在什么年代…」; 现代 never runs the overlay, so no request
// depends on it). Never a row: P_FORMAT, P_SYNC_FORM / _HEADS, PEND_*, BLOCKED_FACT, CALL_HEAD / _STEP / _PIC, CALL_FORM's answer lines, any
// 「（写成 …）」 tail, 群 / 私聊, and the ordinary words 聊天 / 消息 / 发 / 回复 (spec §2.2). A separate table from step 1's
// THEATER_WEIYU_WORD_OVERLAY (that one is pinned as the note check's evidence; plan A2).
const THEATER_WEIYU_WORD_OVERLAY_PHONE = Object.freeze([
    ['THEATER_WEIYU_P_COMMON', '角色们手机上的私人聊天', '角色们{w:device}上的私人聊天', false, true],
    ['THEATER_WEIYU_P_COMMON', '这部手机的主人', '这{w:deviceMw}{w:device}的主人', false, true],
    ['THEATER_WEIYU_P_COMMON', '无论故事在什么年代、什么世界，这里的消息都是现代人的手机聊天：短、随口、好笑。', '这里的消息是这个世界的人用{w:device}随手发的闲聊：短、随口、好笑。', true, false],
    ['THEATER_WEIYU_P_COMMON', '照片和视频都是发的人自己举着手机拍的：说明只写镜头里看到的东西；拍的人自己不在画面里，除非是自拍。',
        '{w:photo}和{w:video}都是发的人自己举着{w:device}{w:capture}的：说明只写{w:lens}里看到的东西；{w:capturer}自己不在画面里，除非是{w:selfie}。', true, true],
    ['THEATER_WEIYU_P_BOOT', '这部手机此刻的全貌', '这{w:deviceMw}{w:device}此刻的全貌', false, true],
    ['THEATER_WEIYU_P_SYNC', '这一楼在手机上带来的变化', '这一楼在{w:device}上带来的变化', false, true],
    ['THEATER_WEIYU_OWNER_LINE', '这部手机的主人', '这{w:deviceMw}{w:device}的主人', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.voice', '有人发一段语音', '有人发一段{w:voice}', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.voice', '懒得打', '懒得{w:typeVerb}', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.photo', '有人发一张照片', '有人发一{w:photoMw}{w:photo}', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.video', '有人发一小段视频', '有人发一小段{w:video}', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.recall', '又撤回', '又{w:recall}', false, true],
    ['THEATER_WEIYU_DICE_MOMENTS.nudge', '有人拍一拍别人', '有人{w:nudgeAct}别人', false, true],
    ['THEATER_WEIYU_DICE_EV_MOMENTS.call', '有人打语音或视频通话', '有人{w:callEither}', false, true],
    ['THEATER_WEIYU_CALL_LEAD', '打给「{name}」的{mode}，不是打字聊天', '{w:callTo}的{mode}，不是{w:typedChat}', false, true],
    ['THEATER_WEIYU_CALL_FORM.voice', '电话还在响时不接', '{w:ringing}不接', false, true],
    ['THEATER_WEIYU_CALL_FORM.video', '电话还在响时不接', '{w:ringing}不接', false, true],
    ['THEATER_WEIYU_CALL_FORM.video', '〈「{me}」屏幕上此刻看到的；手机在「{name}」自己手里或架着〉', '〈「{me}」{w:screenAt}此刻看到的；{w:holder}在「{name}」自己手里或架着〉', true, true],
].map(([at, find, put, dir, fid]) => Object.freeze({ at, find, put, n: 1, stage: 2, dir, fid })));

// FROZEN 2026-11-22 with the multi-floor sync variant (THEATER_WEIYU_P_SYNC_MULTI + THEATER_WEIYU_SYNC_DIVIDER; SY3 + SYB): the device word
// of both leads ("…在手机上带来的变化" = the P_SYNC row above, the same word in the same place; "手机还没跟上") and of the divider. A table of its
// own so the pinned THEATER_WEIYU_WORD_OVERLAY_PHONE keeps its bytes; note.js soWyOverlay reads it after that one (its `at`s are only ever the
// variant's and the divider's). sha256 pinned in weiyu-sync-every-pin.test.mjs; a byte change = re-run the gm-sync rounds (and gm-words).
const THEATER_WEIYU_WORD_OVERLAY_SYNC_MULTI = Object.freeze([
    ['THEATER_WEIYU_P_SYNC_MULTI', '在手机上带来的变化', '在{w:device}上带来的变化', false, true],
    ['THEATER_WEIYU_P_SYNC_MULTI', '手机还没跟上', '{w:device}还没跟上', false, true],
    ['THEATER_WEIYU_P_SYNC_MULTI', '手机都还没跟上', '{w:device}都还没跟上', false, true],
    ['THEATER_WEIYU_SYNC_DIVIDER', '手机已经跟上', '{w:device}已经跟上', false, true],
    ['THEATER_WEIYU_SYNC_DIVIDER', '手机还没跟上', '{w:device}还没跟上', false, true],
].map(([at, find, put, dir, fid]) => Object.freeze({ at, find, put, n: 1, stage: 2, dir, fid })));

// A call's transcript as lines: her spoken lines with their tags in （）, his lines, a VIDEO turn's picture before her words (how 'live' =
// the probe's 画面：… for the call request; 'log' = THEATER_WEIYU_CALL_PIC for later views). A voice call never prints a picture.
function soWyCallSaid(state, call, how) {
    const out = [];
    const c = soWyCallNorm(call);
    if (!c || !Array.isArray(c.turns)) return out;
    const live = how === 'live';
    const nm = (pid) => (live && pid === THEATER_WEIYU_ME ? soWyPromptMe(state) : soWyFlat(soWyPersonName(state, pid)));
    for (const t of c.turns) {
        if (c.mode === 'video' && t.visual && t.u !== THEATER_WEIYU_ME) {
            out.push(live ? '画面：' + soWyFlat(t.visual) : soWyTpl(THEATER_WEIYU_CALL_PIC, { v: soWyFlat(t.visual) }));
        }
        for (const l of t.lines) out.push(nm(t.u) + '：' + (l.tags || []).map((x) => '（' + soWyFlat(x) + '）').join('') + soWyFlat(l.text));
    }
    return out;
}

// soWyOthersFor(state, cid, pids, n): pids = [] → soWyOthers(state, cid, n) itself (today's view, byte for byte). Otherwise probe gm-callscene's
// membership view (cells.mjs AMEND-2/3/4, ported as is): soWyOthers restricted to the chats EVERY pid is a member of (the player's membership
// alone never counts) — same order, same skips (the target, dissolved, closed, empty) — with the lines after the chat's summary boundary and
// its 「（此前：…）」 line; n = Infinity = every such line; at most 12 chats. A chat outside the filter is absent.
function soWyOthersFor(state, cid, pids, n) {
    const p = Array.isArray(pids) ? pids.filter((x) => typeof x === 'string') : [];
    if (!p.length) return soWyOthers(state, cid, n);
    try {
        if (!soWyIsObj(state) || !soWyIsObj(state.chats)) return '';
        const k = n === Infinity ? Infinity : (Number.isFinite(n) && n >= 0 ? Math.floor(n) : 3);
        if (k === 0) return '';
        const out = [];
        let shown = 0;
        for (const id of soWyChatList(state)) {
            if (id === cid) continue;
            const chat = soWyChat(state, id);
            if (!chat || chat.dissolved || soWyChatClosed(state, chat) || !Array.isArray(chat.msgs) || !Array.isArray(chat.members)) continue;
            if (!p.every((x) => chat.members.includes(x))) continue;
            const view = soWySumView(chat);
            const lines = chat.msgs.slice(view.from).map((m) => soWyLogLine(state, m)).filter(Boolean).slice(-k);
            if (!lines.length && !view.sum) continue;
            out.push('【聊天】' + soWyChatRef(state, chat), ...(view.sum ? ['（此前：' + soWyFlat(view.sum) + '）'] : []), ...lines);
            if (++shown >= 12) break;
        }
        return out.join('\n');
    } catch (e) {
        return '';
    }
}

// soWyBriefFor(state, pids): pids = [] → soWyBrief(state) itself. Otherwise soWyBrief's rows kept only where every pid is concerned (probe
// gm-callscene, ported as is): the owner line; a 【人】 row of a pid or of anyone who shares a (live) chat with every pid; a 【群】 / 【私聊】 row
// of a chat every pid is a member of.
// words (optional): the phone-stage set, handed to soWyBrief (the owner row). o (optional, trailing): handed to soWyBrief ({ac: true}).
function soWyBriefFor(state, pids, words, o) {
    const p = Array.isArray(pids) ? pids.filter((x) => typeof x === 'string') : [];
    if (!p.length) return soWyBrief(state, words, o);
    try {
        const rows = soWyBrief(state, words, o).split('\n');
        const live = soWyChatList(state).map((id) => soWyChat(state, id)).filter((c) => c && !c.dissolved && !soWyChatClosed(state, c) && Array.isArray(c.members));
        const theirs = live.filter((c) => p.every((x) => c.members.includes(x)));
        const names = new Set();
        for (const c of theirs) for (const m of c.members) names.add(soWyFlat(soWyPersonName(state, m)));
        for (const x of p) names.add(soWyFlat(soWyPersonName(state, x)));
        const groups = new Set(theirs.filter((c) => c.type === 'group').map((c) => soWyFlat(c.name)));
        const dms = new Set(theirs.filter((c) => c.type === 'dm').map((c) => c.members.map((m) => soWyFlat(soWyPersonName(state, m))).join('、')));
        return rows.filter((r, i) => {
            if (i === 0) return true;
            if (r.startsWith('【人】')) return names.has(r.slice(3).split('｜')[0]);
            if (r.startsWith('【群】')) return groups.has(r.slice(3).split('｜')[0]);
            if (r.startsWith('【私聊】')) return dms.has(r.slice(4));
            return false;
        }).join('\n');
    } catch (e) {
        return '';
    }
}

function soWyCallPrompt(state, a) {
    const none = { system: '', user: '' };
    const chat = soWyChat(state, a.cid);
    if (!chat) return none;
    let view = state;
    let mode = a.mode;
    let her = '';
    let turns = null;
    if (typeof a.mid === 'string' && a.mid) {
        const i = soWyCallLiveIdx(chat, a.mid);
        if (i < 0) return none;
        const m = chat.msgs[i];
        const call = soWyCallNorm(m.call);
        mode = call.mode;
        her = typeof m.to === 'string' ? m.to : '';
        turns = call.turns;
        view = soWyClone(state);
        view.chats[a.cid].msgs.splice(i, 1);
    } else {
        if (!soWyOwn(THEATER_WEIYU_CALL_KIND, mode)) return none;
        her = soWyEvPeer(state, chat) || '';
    }
    if (!her || !soWyPerson(view, her)) return none;
    const vals = { me: soWyPromptMe(view), name: soWyFlat(soWyPersonName(view, her)), mode: THEATER_WEIYU_CALL_KIND[mode] };
    const head = soWyTpl(THEATER_WEIYU_CALL_HEAD, Object.assign({ st: turns ? THEATER_WEIYU_CALL_STEP.live : THEATER_WEIYU_CALL_STEP.ring }, vals));
    const said = turns ? soWyCallSaid(view, { mode, st: 'live', turns: turns.slice(-THEATER_WEIYU_CALL_CAP.turns) }, 'live') : [];
    // the memory slice (args.mem, root's ruling 2026-11-18): her chats through the membership windows ("ever a member"), the private chat's
    // last soWyMemKeepOpt lines; the call paragraph and the form are unchanged. Not true → the probe gm-callscene shape, byte for byte.
    // world wording step 2 (args.words, a phone-stage set; null = the request as before): the owner row (7), CALL_LEAD (15) and CALL_FORM's
    // 「电话还在响时」 / video picture slot (16–18) overlaid as templates. The {mode} split: the LEAD alone takes the set's call word; CALL_HEAD
    // (〔语音通话〕…, a record the reader reads) and CALL_FORM keep THEATER_WEIYU_CALL_KIND.
    const words = soWyPhoneWords(a.words);
    const ac = a.ac === true ? { ac: true } : undefined;   // adding contacts by hand: the 【人】 rows' marker / 人物说明 (not true = as before)
    const ctx = a.mem === true
        ? [soWyBriefMem(view, a.cid, [her], words, ac), soWyOthersMem(view, a.cid, [her]), soWyLogMem(view, a.cid, { keep: soWyMemKeepOpt(view) })]
        : [soWyBriefFor(view, [her], words, ac), soWyOthersFor(view, a.cid, [her], Infinity), soWyLog(view, a.cid)];
    if (!words) {
        const user = ctx.concat([[head].concat(said).join('\n'), soWyTpl(THEATER_WEIYU_CALL_FORM[mode], vals)]).filter(Boolean).join('\n\n');
        return { system: soWyTpl(THEATER_WEIYU_CALL_LEAD, vals), user };
    }
    const callWord = soWyIsObj(words.terms) ? soWyWordsSafe(words.terms[mode === 'video' ? 'videoCall' : 'voiceCall']) : '';
    const lead = Object.assign({}, vals, { mode: callWord || THEATER_WEIYU_CALL_KIND[mode] });
    const form = soWyTpl(soWyWordsAt('THEATER_WEIYU_CALL_FORM.' + mode, THEATER_WEIYU_CALL_FORM[mode], words), vals);
    const user = ctx.concat([[head].concat(said).join('\n'), form]).filter(Boolean).join('\n\n');
    return { system: soWyTpl(soWyWordsAt('THEATER_WEIYU_CALL_LEAD', THEATER_WEIYU_CALL_LEAD, words), lead), user };
}

// ---- world words: the naming request (ENABLE_THR_WEIYU_WORDS_AI; DRAFT until gm-words step 1b) ----------------------------------------------
// 「✨ 让 AI 按这个世界起名」 (spec 2026-11-18-world-wording-design.md §7.2 / §7.3; plan C6). NOT a phone request: no P_COMMON / P_FORMAT, no
// dice, no history, no preset — the join sends exactly [system, user] (soWyWordsCall in flow.js drives it). Hard guarantees live in code
// (note.js soWyWordsRead / soWyWordsLand: the save-time validator; at most ONE automatic repair).
// DRAFT until the gm-words 1b direction check (sha256 pinned in weiyu-words-pin.test.mjs; after that check a byte change = re-run it):
// LEAD, FORM ({banned} = the banned line), the two section heads, BANNED_LINE ({list} = note.js soWyWordsBannedList()), FIX ({accepted}
// {list} {failed} {blanks}) and FIX_WHY (the repair's reasons; {key} = the other item's zh key, {w} = a word; prefixOf is plan-drafted).
// FORM round 2 (2026-11-18, owner: "ask the AI to give their best estimate"): the 接近 line and the closing instruction ask for the world's
// most likely word / base; 无 only for a thing the world cannot have (round 1: 16 of 21 register misses were 无). Still DRAFT until 1b round 2.
//   soWyWordsBannedLine() → BANNED_LINE with today's list.
//   soWyWordsPrompt(lore: {lore, desc}) → {system: LEAD, user: [HEAD_LORE + \n + lore, HEAD_CARD + \n + desc (each only when non-empty),
//     FORM with the banned line] joined with \n\n}. The lore / description are the join's (already picked and capped: soWyWordsLorePick).
//   soWyWordsFixPrompt(land: Land, failed: TermId[]) → {system: LEAD, user: FIX} — {accepted} = one `zh=word` line per non-failed key in form
//     order (量词 folded into 手机 as 手机=word（mw）when 量词 is not failed; an `off` card kind as zh=无), {failed} = zh=<the proposed word
//     through soWyWordsSafe, '' when none>｜<reason>, {blanks} = zh= per failed key (form order), {list} = the same banned list. No lore.
//   Every fill is one pass (soWyTpl): a word is never scanned for slots.
const THEATER_WEIYU_WORDS_LEAD = '这一次是给一个故事世界里的通讯方式起叫法，不是写故事。';
const THEATER_WEIYU_WORDS_FORM = [
    '这个世界里的人也带着一样随身的东西互相传话。给下面每一项起一个这个世界的人会用的叫法，照这个样子写，一行一项，「=」左边原样照抄，右边换成叫法：',
    '名字=这个世界的简称',
    '接近=照设定判断，魔法奇幻、古风仙侠、科幻里最像的一个',
    '手机=随身传话用的那样东西',
    '量词=数它用的量词',
    '群聊=几个人一起说话的地方',
    '私聊=两个人私下说话',
    '语音=留下的一段声音',
    '照片=留下的一幅画面',
    '视频=留下的一段会动的画面',
    '语音通话=隔着远直接说上话',
    '视频通话=隔着远看着对方说话',
    '转账=把钱物送给对方',
    '拍一拍=隔空碰一下对方，叫他注意',
    '撤回=把发出去的话收回',
    '位置=告诉别人自己在哪儿',
    '文件=一份要人看的文书',
    '链接=指向别处一篇东西的指引',
    '名片=把一个人介绍给别人',
    '音乐=一首曲子',
    '每个叫法两到六个字，各不相同；设定里已经有的说法照用，没有的照这个世界的气质，给出这个世界的人最可能用的叫法。位置、文件、链接、名片、音乐这五项也给出最可能的叫法，只有这个世界不可能有这样东西的，右边才写：无。',
    '{banned}',
    '回复只交这些行。',
].join('\n');
const THEATER_WEIYU_WORDS_HEAD_LORE = '【世界设定】';
const THEATER_WEIYU_WORDS_HEAD_CARD = '【角色】';
const THEATER_WEIYU_WORDS_BANNED_LINE = '右边的叫法可以和左边一样，但不能是这些已被占用的词：{list}。';
const THEATER_WEIYU_WORDS_FIX = [
    '这个世界里通讯方式的叫法，已经定下的有：',
    '{accepted}',
    '下面几项的叫法还不能用，原因写在后面；给每一项另起一个叫法，不能和已经定下的一样，也不能是这些已被占用的词：{list}。',
    '{failed}',
    '照这个样子写，一行一项，「=」左边原样照抄，右边换成新的叫法，两到六个字：',
    '{blanks}',
    '回复只交这些行。',
].join('\n');
const THEATER_WEIYU_WORDS_FIX_WHY = Object.freeze({
    dup: '和「{key}」的叫法一样',
    prefix: '以「{w}」开头，会和格式里的「{w}」混在一起',
    prefixSet: '以「{w}」（{key}的叫法）开头，会混在一起',
    prefixOf: '「{key}」的叫法「{w}」以它开头，会混在一起',
    taken: '「{w}」已被占用',
    chars: '里面有不能用的符号',
    long: '太长了',
    missing: '上一次没有给出',
    none: '这一项不能写无',
});

function soWyWordsBannedLine() {
    return soWyTpl(THEATER_WEIYU_WORDS_BANNED_LINE, { list: soWyWordsBannedList() });
}

function soWyWordsPrompt(lore) {
    const l = soWyIsObj(lore) ? lore : {};
    const text = (s) => (typeof s === 'string' ? s : '');
    const parts = [
        text(l.lore) ? THEATER_WEIYU_WORDS_HEAD_LORE + '\n' + text(l.lore) : null,
        text(l.desc) ? THEATER_WEIYU_WORDS_HEAD_CARD + '\n' + text(l.desc) : null,
        soWyTpl(THEATER_WEIYU_WORDS_FORM, { banned: soWyWordsBannedLine() }),
    ];
    return { system: THEATER_WEIYU_WORDS_LEAD, user: parts.filter(Boolean).join('\n\n') };
}

function soWyWordsFixPrompt(land, failed) {
    const L = soWyIsObj(land) ? land : {};
    const terms = soWyIsObj(L.terms) ? L.terms : {};
    const off = Array.isArray(L.off) ? L.off : [];
    const flags = soWyIsObj(L.flags) ? L.flags : {};
    const bad = Array.isArray(failed) ? failed : [];
    const zh = (k) => {
        const p = THEATER_WEIYU_WORDS_KEYS.find((x) => x[1] === k);
        return p ? p[0] : '';
    };
    const word = (k) => soWyWordsSafe(soWyOwn(terms, k) ? terms[k] : '');
    const accepted = [];
    const failedLines = [];
    const blanks = [];
    for (const [z, k] of THEATER_WEIYU_WORDS_KEYS) {
        if (bad.includes(k)) {
            const e = soWyOwn(flags, k) && soWyIsObj(flags[k]) ? flags[k] : { why: 'missing' };
            const tpl = soWyOwn(THEATER_WEIYU_WORDS_FIX_WHY, e.why) ? THEATER_WEIYU_WORDS_FIX_WHY[e.why] : THEATER_WEIYU_WORDS_FIX_WHY.missing;
            const why = soWyTpl(tpl, { key: zh(e.other), w: soWyWordsSafe(e.w) });
            failedLines.push(z + '=' + soWyWordsSafe(e.w0) + '｜' + why);
            blanks.push(z + '=');
            continue;
        }
        if (k === 'deviceMw' && !bad.includes('device')) continue;   // folded into 手机
        if (off.includes(k)) accepted.push(z + '=无');
        else if (k === 'device' && !bad.includes('deviceMw')) accepted.push(z + '=' + word('device') + '（' + word('deviceMw') + '）');
        else accepted.push(z + '=' + word(k));
    }
    const user = soWyTpl(THEATER_WEIYU_WORDS_FIX, {
        accepted: accepted.join('\n'), list: soWyWordsBannedList(), failed: failedLines.join('\n'), blanks: blanks.join('\n'),
    });
    return { system: THEATER_WEIYU_WORDS_LEAD, user };
}
