// Timings (plan decision; the hold numbers equal the scene runtime's). toastMs is a plan-added key.
const THEATER_WEIYU_TIMING = Object.freeze({
    holdMs: 2000, holdMove: 12, holdTap: 300, hintMs: 1500, waitMs: 3000, longPress: 500, undoMs: 5000,
    typeMin: 700, typeMax: 2000, bootLine: 1100, bootStep: 230, bootFly: 800, readyMs: 2300, bannerMs: 4000, toastMs: 2200,
    ringMs: 1500,   // more functions phase 2: the brief "calling…" screen before his 已取消 lands (motion on only)
});

// acform = adding contacts by hand (2026-11-21): the 添加朋友 form / the 编辑资料 page (only reachable with env.stages.add); acfind = its
// 从故事里找人 page (only with env.stages.find as well)
const THEATER_WEIYU_PAGES = ['empty', 'tabs', 'chat', 'info', 'profile', 'pick', 'sublist', 'search', 'words', 'acform', 'acfind'];

function soWyFmt(str, vars) {
    const v = soWyIsObj(vars) ? vars : {};
    return String(str == null ? '' : str).replace(/\{(\w+)\}/g, (m, k) => (soWyOwn(v, k) ? String(v[k]) : m));
}

function soWyKids(el, kids) {
    for (const k of kids) {
        if (k == null || k === false) continue;
        if (Array.isArray(k)) soWyKids(el, k);
        else if (typeof k === 'string' || typeof k === 'number') el.appendChild(el.ownerDocument.createTextNode(String(k)));
        else if (typeof k === 'object' && typeof k.nodeType === 'number') el.appendChild(k);
    }
    return el;
}

// The only way UI code makes elements: text is always a text node; there is no HTML-string input of any kind.
// attrs: class (string | array), data {name: value} → data-*, aria {name: value} → aria-*, text; any other plain attribute name.
// Event-handler attributes (on*), style, innerHTML / outerHTML / srcdoc are refused.
function soWyEl(doc, tag, attrs, ...kids) {
    const el = doc.createElement(tag);
    const a = soWyIsObj(attrs) ? attrs : {};
    const dash = (n) => String(n).replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
    for (const k of Object.keys(a)) {
        const v = a[k];
        if (v == null || v === false) continue;
        if (k === 'class') {
            for (const c of Array.isArray(v) ? v : String(v).split(/\s+/)) if (c) el.classList.add(String(c));
        } else if (k === 'text') {
            el.textContent = String(v);
        } else if (k === 'data' || k === 'aria') {
            if (!soWyIsObj(v)) continue;
            for (const n of Object.keys(v)) {
                const x = v[n];
                if (x == null || x === false || !/^[a-zA-Z][\w-]*$/.test(n)) continue;
                el.setAttribute(k + '-' + dash(n), x === true ? (k === 'aria' ? 'true' : '') : String(x));
            }
        } else if (/^on/i.test(k) || /^(style|innerhtml|outerhtml|srcdoc)$/i.test(k) || !/^[a-zA-Z][\w-]*$/.test(k)) {
            continue;
        } else {
            el.setAttribute(k, v === true ? '' : String(v));
        }
    }
    return soWyKids(el, kids);
}

// Icons come ONLY from the trusted constant THEATER_WEIYU_ICONS, inserted by HTML parsing of that constant (a <template>) — never
// model or player text, never as an XML document or a CSS data URI (the values carry no xmlns; root ruling Task 11).
// `uid` suffixes every id="…" / url(#…) so two copies on one page never share gradient ids.
function soWyIcon(doc, name, uid) {
    if (!soWyOwn(THEATER_WEIYU_ICONS, name) || typeof THEATER_WEIYU_ICONS[name] !== 'string') return null;
    let svg = THEATER_WEIYU_ICONS[name];
    const u = String(uid == null ? '' : uid).replace(/[^A-Za-z0-9_-]/g, '');
    if (u) {
        svg = svg.replace(/\bid="([^"]+)"/g, (m, id) => 'id="' + id + '-' + u + '"')
            .replace(/url\(#([^)]+)\)/g, (m, id) => 'url(#' + id + '-' + u + ')');
    }
    const t = doc.createElement('template');
    t.innerHTML = svg;
    const src = t.content.firstElementChild;
    if (!src) return null;
    const el = doc.importNode(src, true);
    el.setAttribute('aria-hidden', 'true');
    el.setAttribute('focusable', 'false');
    return el;
}

// Light DOM around the phone (styled by weiyu-host.css, which the join appends to style.css).
function soWyHostBuild(doc) {
    const T = THEATER_WEIYU_TEXT;
    return soWyEl(doc, 'div', { id: 'so-thr-weiyu-view' },
        soWyEl(doc, 'div', { id: 'so-thr-weiyu-card' },
            soWyEl(doc, 'div', { class: 'so-thr-weiyu-head' },
                soWyEl(doc, 'span', { id: 'so-thr-weiyu-title', text: T.name }),
                soWyEl(doc, 'span', { id: 'so-thr-weiyu-status', aria: { live: 'polite' } }),
                soWyEl(doc, 'button', { id: 'so-thr-weiyu-x', type: 'button', class: 'so-warn-x', aria: { label: T.hostClose }, text: '✕' })),
            soWyEl(doc, 'div', { id: 'so-thr-weiyu-host' })));
}

function soWyEnvState(phone) {
    try {
        const s = phone.env.getState();
        return soWyIsObj(s) ? s : null;
    } catch (e) {
        return null;
    }
}

function soWyEnvForeign(phone) {
    try {
        return !!phone.env.foreign();
    } catch (e) {
        return false;
    }
}

function soWyEnvFlight(phone) {
    try {
        return typeof phone.env.flight === 'function' ? phone.env.flight() || null : null;
    } catch (e) {
        return null;
    }
}

// The system's reduced-motion setting, as the join reads it (env.reducedMotion).
function soWyEnvSysReduced(phone) {
    try {
        return typeof phone.env.reducedMotion === 'function' && !!phone.env.reducedMotion();
    } catch (e) {
        return false;
    }
}

// "No motion" for the JS motion paths = the phone's resolved root flag (动画 option + the system setting, soWyApplyMotion); before the
// first apply, the system setting alone (= the behaviour before the option existed).
function soWyEnvReduced(phone) {
    if (phone.motion === 'on' || phone.motion === 'off') return phone.motion === 'off';
    return soWyEnvSysReduced(phone);
}

// 动画 (owner 2026-11-17): ONE root flag `.wy[data-wy-motion="on|off"]` that the phone's CSS (the zeroing rule) and JS (soWyEnvReduced)
// read. `state` = this render's state when the caller has it (one read per render); undefined → read it here.
function soWyApplyMotion(phone, state) {
    if (phone.dead) return;
    const st = state === undefined ? soWyEnvState(phone) : state;
    const v = soWyMotionResolve(soWyMotionOpt(st), soWyEnvSysReduced(phone));
    const was = phone.motion;   // MOTION (lane M)
    phone.motion = v;
    if (phone.root.getAttribute('data-wy-motion') !== v) phone.root.setAttribute('data-wy-motion', v);
    // MOTION (lane M): turned off → whatever is moving stops where it ends; the frame (outside the shadow root) hears the flag too
    if (was === 'on' && v !== 'on') soWyMoHalt(phone);
    if (was !== v) soWyMoMirror(phone);
}

// The system setting's live query (a change re-applies the flag without a re-render); null where there is none (jsdom without a stub).
function soWyMotionQuery(doc) {
    try {
        const w = doc.defaultView;
        const q = w && typeof w.matchMedia === 'function' ? w.matchMedia('(prefers-reduced-motion: reduce)') : null;
        return q && (typeof q.addEventListener === 'function' || typeof q.addListener === 'function') ? q : null;
    } catch (e) {
        return null;
    }
}

function soWyPicsView(phone) {
    let raw = null;
    let key = '';
    try { raw = typeof phone.env.getPics === 'function' ? phone.env.getPics() : null; } catch (e) { raw = null; }
    try { key = typeof phone.env.cardKey === 'function' ? String(phone.env.cardKey() || '') : ''; } catch (e) { key = ''; }
    const store = raw == null ? null : soWyPicStoreNorm(raw);
    const pics = store && key ? store.cards.find((c) => c.card === key) || null : null;
    return { store, key, pics, me: soWyPicMeGet(store) };
}

function soWyLater(phone, fn, ms) {
    if (phone.dead) return null;
    const id = setTimeout(() => {
        phone.timers.delete(id);
        if (!phone.dead) fn();
    }, Math.max(0, Number(ms) || 0));
    phone.timers.add(id);
    return id;
}

function soWyRootPage(phone) {
    if (soWyEnvForeign(phone)) return { k: 'empty' };
    const st = soWyEnvState(phone);
    return st && st.booted ? { k: 'tabs', tab: 'chats' } : { k: 'empty' };
}

function soWyTopBar(phone, o) {
    const d = phone.host.ownerDocument;
    const T = THEATER_WEIYU_TEXT;
    const x = soWyIsObj(o) ? o : {};
    let back = null;
    if (x.back) {
        const n = typeof x.back === 'number' && x.back > 0 ? (x.back > 99 ? '99+' : String(x.back)) : '';
        back = soWyEl(d, 'button', { type: 'button', class: 'wy-back', data: { 'wy-act': 'back' }, aria: { label: T.back } },
            soWyIcon(d, 'back'), n ? soWyEl(d, 'span', { class: 'wy-back-n', text: n }) : null);
    }
    return soWyEl(d, 'div', { class: ['wy-top', x.line ? 'wy-line' : ''] },
        soWyEl(d, 'div', { class: 'wy-top-l' }, back),
        soWyEl(d, 'div', { class: 'wy-ttl' }, x.title == null ? '' : x.title),
        soWyEl(d, 'div', { class: 'wy-top-r' }, x.right || null));
}

function soWyTabBar(phone, tab, total) {
    const d = phone.host.ownerDocument;
    const T = THEATER_WEIYU_TEXT;
    const tabs = [['chats', T.tabChats], ['contacts', T.tabContacts], ['me', T.tabMe]];
    const n = Number(total) > 0 ? Number(total) : 0;
    return soWyEl(d, 'div', { class: 'wy-tabbar', role: 'tablist' }, tabs.map(([k, label]) => {
        const on = k === tab;
        return soWyEl(d, 'button', {
            type: 'button', role: 'tab', class: ['wy-tab', on ? 'wy-on' : ''], data: { 'wy-act': 'tab', 'wy-tab': k },
            aria: { selected: on ? 'true' : 'false' },
        }, soWyIcon(d, 'tab-' + k + (on ? '-active' : '')), soWyEl(d, 'span', { class: 'wy-tab-label', text: label }),
        k === 'chats' && n ? soWyEl(d, 'span', { class: 'wy-badge', text: n > 99 ? '99+' : String(n) }) : null);
    }));
}

// Pages whose builder is not loaded yet: an empty stub with the right frame (top bar; tabs keep the tab bar).
function soWyStubPage(phone, page) {
    const d = phone.host.ownerDocument;
    const T = THEATER_WEIYU_TEXT;
    if (page.k === 'tabs') {
        const st = soWyEnvState(phone);
        const title = { chats: T.name, contacts: T.tabContacts, me: T.tabMe }[page.tab] || T.name;
        return soWyEl(d, 'div', { class: 'wy-page' }, soWyTopBar(phone, { title }), soWyEl(d, 'div', { class: 'wy-scroll' }),
            soWyTabBar(phone, page.tab, soWyTotalUnread(st)));
    }
    if (page.k === 'empty') {
        const st = soWyEnvState(phone);
        const me = st ? soWyPersonName(st, THEATER_WEIYU_ME) : '';
        return soWyEl(d, 'div', { class: ['wy-page', 'wy-empty'] }, soWyEl(d, 'div', { class: 'wy-empty-logo' }, soWyIcon(d, 'logo-tile', 'e')),
            soWyEl(d, 'div', { class: 'wy-empty-name', text: T.name }), soWyEl(d, 'p', { class: 'wy-empty-who', text: soWyFmt(T.emptyWho, { name: me }) }));
    }
    return soWyEl(d, 'div', { class: 'wy-page' }, soWyTopBar(phone, { back: phone.stack.length > 1, line: true }), soWyEl(d, 'div', { class: 'wy-scroll' }));
}

// A phone stored by a NEWER build: shown, never written, no 开机.
function soWyForeignPage(phone) {
    const d = phone.host.ownerDocument;
    const T = THEATER_WEIYU_TEXT;
    return soWyEl(d, 'div', { class: ['wy-page', 'wy-empty', 'wy-foreign'] }, soWyEl(d, 'div', { class: 'wy-empty-logo' }, soWyIcon(d, 'logo-tile', 'f')),
        soWyEl(d, 'div', { class: 'wy-empty-name', text: T.name }), soWyEl(d, 'p', { class: 'wy-empty-who', text: T.foreign }));
}

function soWyPageBuild(phone, page) {
    if (soWyEnvForeign(phone)) return soWyForeignPage(phone);
    let fn = null;
    switch (page.k) {
        case 'empty': fn = typeof soWyScreenEmpty === 'function' ? soWyScreenEmpty : null; break;
        case 'tabs': fn = typeof soWyScreenTabs === 'function' ? soWyScreenTabs : null; break;
        case 'chat': fn = typeof soWyScreenChat === 'function' ? soWyScreenChat : null; break;
        case 'info': fn = typeof soWyScreenInfo === 'function' ? soWyScreenInfo : null; break;
        case 'profile': fn = typeof soWyScreenProfile === 'function' ? soWyScreenProfile : null; break;
        case 'pick': fn = typeof soWyScreenPick === 'function' ? soWyScreenPick : null; break;
        case 'sublist': fn = typeof soWyScreenSublist === 'function' ? soWyScreenSublist : null; break;
        case 'search': fn = typeof soWyScreenSearch === 'function' ? soWyScreenSearch : null; break;   // more functions phase 1
        case 'words': fn = typeof soWyScreenWords === 'function' ? soWyScreenWords : null; break;   // 世界用语 (the editor)
        case 'acform': fn = typeof soWyScreenAcForm === 'function' ? soWyScreenAcForm : null; break;   // adding contacts by hand (the form / 编辑资料)
        case 'acfind': fn = typeof soWyScreenAcFind === 'function' ? soWyScreenAcFind : null; break;   // adding contacts by hand (从故事里找人)
        default: fn = null;
    }
    return fn ? fn(phone, page) : soWyStubPage(phone, page);
}

// Rebuilds the top page. keep = a refresh of the same page: scroll positions, the input's draft, its focus survive.
// Drafts live in phone.drafts[cid] (code-made ids only) so leaving a chat and coming back keeps the half-typed line too.
function soWyRender(phone, keep) {
    if (phone.dead) return;
    const old = phone.pageEl;
    const oldPage = phone.cur;
    // MOTION (lane M): the way soWyGo / soWyBack / soWyHome moved ('push' | 'back' | 'tab' | null), consumed by this render; a snapshot of
    // what the motions need from the page that is going (null = no motion: the flag is off, or no Web Animations)
    const nav = phone.moNav || null;
    phone.moNav = null;
    const mo = !soWyMoOn(phone) ? null : old ? soWyMoSnap(phone, old, oldPage, !!keep && oldPage === phone.stack[phone.stack.length - 1])
        : { page: null, msgs: null, typing: null, rows: null, firedAt: 0, tabBadge: null };
    const saved = { scroll: [], focus: false };
    if (old) {
        const inp = old.querySelector('[data-wy-input]');
        if (inp && oldPage && oldPage.k === 'chat') phone.drafts[oldPage.cid] = inp.value;
        saved.focus = !!inp && phone.shadow.activeElement === inp;
        for (const sc of old.querySelectorAll('.wy-scroll')) {
            // at the end = near it, or still exactly where the last render put it at the end (_wyEndTop): the arrival glide (soWyMoChat)
            // translates the list for a moment, which inflates scrollHeight — quick sends measured "not at the end" and stopped following
            // (playtest 2026-11-19 A2). A player who scrolled up moved scrollTop below that mark, so the distance alone decides then.
            const end = Number.isFinite(sc._wyEndTop) && sc.scrollTop >= sc._wyEndTop - 1;
            saved.scroll.push({ top: sc.scrollTop, bottom: end || sc.scrollHeight - sc.scrollTop - sc.clientHeight < 40 });
        }
    }
    let el = null;
    for (let guard = 0; guard < 4 && !el; guard++) {
        // one render = one read of the state / pictures (soWyMemo in ui-screens); actions always read afresh
        phone.renders = (phone.renders || 0) + 1;
        phone.rendering = true;
        try {
            el = soWyPageBuild(phone, phone.stack[phone.stack.length - 1]);
        } catch (e) {
            el = null;
        } finally {
            phone.rendering = false;
        }
        if (!el) {
            // the page's target is gone (a reset, a deleted chat): fall back to the page under it, or the root
            phone.stack.pop();
            if (!phone.stack.length) phone.stack.push(soWyRootPage(phone));
        }
    }
    const top = phone.stack[phone.stack.length - 1];
    if (!el) el = soWyStubPage(phone, top);
    el.setAttribute('data-wy-page', top.k);
    el.classList.add('wy-page');
    const same = !!keep && oldPage === top;
    if (old && old.parentNode === phone.root) {
        // MOTION (lane M): a push / back keeps the old page (inert) while it slides away; a refresh of the page that is sliding in takes
        // its slide over; everything else swaps in one frame as before
        if (mo && !same && (nav === 'push' || nav === 'back')) soWyMoKeep(phone, old, el, nav);
        else {
            if (mo && same) soWyMoCarry(phone, old, el);
            phone.root.replaceChild(el, old);
        }
    } else phone.root.insertBefore(el, phone.layer);
    phone.pageEl = el;
    phone.cur = top;
    const memo = phone.memo;   // the 动画 flag follows the stored option (this render's read of the state when the page made one)
    soWyApplyMotion(phone, memo && memo.n === phone.renders ? memo.state : undefined);
    if (mo) soWyMoPrep(phone, el, top);   // MOTION (lane M): layout classes BEFORE the scroll positions are restored
    const inp = el.querySelector('[data-wy-input]');
    if (inp && top.k === 'chat') inp.value = soWyOwn(phone.drafts, top.cid) ? phone.drafts[top.cid] : '';
    [...el.querySelectorAll('.wy-scroll')].forEach((sc, i) => {
        const follow = top.k === 'chat' && (same && saved.scroll[i] ? saved.scroll[i].bottom : !same);
        if (same && saved.scroll[i]) sc.scrollTop = top.k === 'chat' && saved.scroll[i].bottom ? sc.scrollHeight : saved.scroll[i].top;
        else if (!same && top.k === 'chat') sc.scrollTop = sc.scrollHeight;
        if (follow) sc._wyEndTop = sc.scrollTop;   // where "the end" was put (A2: read back by the next render's measurement)
    });
    if (same && saved.focus && inp) {
        try {
            inp.focus();
            inp.selectionStart = inp.value.length;
            inp.selectionEnd = inp.value.length;
        } catch (e) { /* an input that cannot take focus */ }
    }
    if (mo) soWyMoAfter(phone, mo, el, top, same, nav);   // MOTION (lane M)
    if (typeof soWyAfterRender === 'function') soWyAfterRender(phone, top, el, same);
}

// Rebuilds from env.getState(); a phone that was reset (or booted elsewhere) moves to the matching root page.
function soWyRefreshPhone(phone) {
    if (phone.dead) return;
    const root = phone.stack[0];
    const want = soWyRootPage(phone);
    if (!root || (want.k === 'empty') !== (root.k === 'empty')) phone.stack = [want];
    soWyRender(phone, true);
}

function soWyApplyTheme(phone) {
    if (phone.dead) return;
    let sk = null;
    try { sk = phone.env.skin(); } catch (e) { sk = null; }
    const s = soWyIsObj(sk) ? sk : {};
    phone.host.setAttribute('data-wy-theme', soWyThemeOf(s.classes, s.bg));
    let w = 0;
    try { w = phone.host.clientWidth || phone.host.getBoundingClientRect().width || 0; } catch (e) { w = 0; }
    if (soWyFit(w).wide) phone.host.setAttribute('data-wy-wide', '');
    else phone.host.removeAttribute('data-wy-wide');
}

function soWyGo(phone, page) {
    if (phone.dead || !soWyIsObj(page) || !THEATER_WEIYU_PAGES.includes(page.k) || soWyEnvForeign(phone)) return;
    const p = {};
    for (const k of ['k', 'tab', 'cid', 'pid', 'mode', 'f']) if (soWyOwn(page, k) && page[k] != null) p[k] = page[k];
    soWyMenuDrop(phone);
    phone.stack.push(p);
    phone.moNav = 'push';   // MOTION (lane M)
    soWyRender(phone, false);
}

function soWyBack(phone) {
    if (phone.dead || phone.stack.length < 2) return;
    // 从故事里找人: ‹ after an add = 完成 (→ 通讯录, where the new people carry 「新」); without an add it is today's back
    const top = phone.stack[phone.stack.length - 1];
    if (top && top.k === 'acfind' && Array.isArray(top.added) && top.added.length && typeof soWyAcFindDone === 'function') return soWyAcFindDone(phone);
    soWyMenuDrop(phone);
    phone.stack.pop();
    phone.moNav = 'back';   // MOTION (lane M)
    soWyRender(phone, false);
}

function soWyHome(phone, tab) {
    if (phone.dead) return;
    soWyMenuDrop(phone);
    const root = soWyRootPage(phone);
    if (root.k === 'tabs' && ['chats', 'contacts', 'me'].includes(tab)) root.tab = tab;
    // MOTION (lane M): from a deeper page = back; another tab of the list = the tab cross-fade; the same tab = nothing moves
    const was = phone.stack[phone.stack.length - 1];
    phone.moNav = phone.stack.length > 1 ? 'back' : was && was.k === 'tabs' && root.k === 'tabs' && was.tab !== root.tab ? 'tab' : null;
    phone.stack = [root];
    soWyRender(phone, false);
}

// Floating things that belong to one page (menus, sheets) — everything in the layer except toasts, banners and the live call scene's
// screen (.wy-cs: it belongs to the call, not to a page — only the call itself closes it).
function soWyMenuDrop(phone) {
    if (!phone.layer) return;
    const fade = soWyMoOn(phone);   // MOTION (lane M): a menu / sheet fades out (soWyMoClosePop) instead of vanishing
    for (const el of [...phone.layer.children]) {
        if (el.classList.contains('wy-toast') || el.classList.contains('wy-banner') || el.classList.contains('wy-cs')) continue;
        if (fade && el.classList.contains('wy-pop-wrap')) soWyMoClosePop(phone, el);
        else el.remove();
    }
}

function soWyToast(phone, text, opts) {
    if (phone.dead) return null;
    const d = phone.host.ownerDocument;
    const o = soWyIsObj(opts) ? opts : {};
    for (const t of phone.layer.querySelectorAll('.wy-toast')) t.remove();
    let act = null;
    if (soWyIsObj(o.action) && typeof o.action.fn === 'function') {
        act = soWyEl(d, 'button', { type: 'button', class: 'wy-toast-act', data: { 'wy-act': 'toast-act' }, text: String(o.action.label == null ? '' : o.action.label) });
        act._wyFn = o.action.fn;
    }
    const el = soWyEl(d, 'div', { class: ['wy-toast', o.so ? 'wy-so' : ''], role: 'status' }, soWyEl(d, 'span', { text: String(text == null ? '' : text) }), act);
    phone.layer.appendChild(el);
    soWyLater(phone, () => el.remove(), o.ms || THEATER_WEIYU_TIMING.toastMs);
    return el;
}

function soWyBanner(phone, info) {
    if (phone.dead || !soWyIsObj(info)) return null;
    const d = phone.host.ownerDocument;
    for (const b of phone.layer.querySelectorAll('.wy-banner')) b.remove();
    const el = soWyEl(d, 'div', { class: 'wy-banner', role: 'button', tabindex: '0', data: { 'wy-act': 'banner' } },
        soWyEl(d, 'span', { class: 'wy-banner-logo' }, soWyIcon(d, 'logo-tile', 'bn')),
        soWyEl(d, 'span', { class: 'wy-banner-body' }, soWyEl(d, 'span', { class: 'wy-banner-who', text: String(info.who == null ? '' : info.who) }),
            soWyEl(d, 'span', { class: 'wy-banner-text', text: String(info.text == null ? '' : info.text) })));
    el._wyCid = typeof info.cid === 'string' ? info.cid : '';
    phone.layer.appendChild(el);
    soWyLater(phone, () => el.remove(), THEATER_WEIYU_TIMING.bannerMs);
    return el;
}

// The one action table: core actions here, then each later block's soWy…Act (typeof-guarded) until one answers true.
function soWyAct(phone, act, el, ev) {
    if (act === 'back') return soWyBack(phone);
    if (act === 'tab') return soWyHome(phone, el.getAttribute('data-wy-tab'));
    if (act === 'toast-act') {
        const fn = el._wyFn;
        const toast = el.closest('.wy-toast');
        if (toast) toast.remove();
        if (typeof fn === 'function') fn();
        return;
    }
    if (act === 'banner') {
        const cid = el._wyCid;
        el.remove();
        if (cid && soWyChat(soWyEnvState(phone), cid)) soWyGo(phone, { k: 'chat', cid });
        return;
    }
    if (typeof soWyScreensAct === 'function' && soWyScreensAct(phone, act, el, ev)) return;
    if (typeof soWyBootAct === 'function') soWyBootAct(phone, act, el, ev);
}

function soWyEvent(phone, type, ev) {
    if (typeof soWyScreensEvent === 'function' && soWyScreensEvent(phone, type, ev)) return;
    if (typeof soWyBootEvent === 'function') soWyBootEvent(phone, type, ev);
}

function soWyMount(hostEl, env) {
    const doc = hostEl.ownerDocument;
    const shadow = hostEl.shadowRoot || hostEl.attachShadow({ mode: 'open' });
    shadow.replaceChildren();
    const style = doc.createElement('style');
    style.textContent = THEATER_WEIYU_CSS;
    const root = soWyEl(doc, 'div', { class: 'wy' });
    const layer = soWyEl(doc, 'div', { class: 'wy-layer' });
    root.appendChild(layer);
    shadow.append(style, root);
    const phone = {
        host: hostEl, shadow, root, layer, env, stack: [], notes: {}, drafts: {}, timers: new Set(), dead: false, pageEl: null, cur: null,
    };
    phone.refresh = () => soWyRefreshPhone(phone);
    phone.refreshTheme = () => soWyApplyTheme(phone);
    phone.go = (page) => soWyGo(phone, page);
    phone.back = () => soWyBack(phone);
    phone.home = (tab) => soWyHome(phone, tab);
    phone.toast = (text, opts) => soWyToast(phone, text, opts);
    phone.banner = (info) => soWyBanner(phone, info);
    phone.later = (fn, ms) => soWyLater(phone, fn, ms);
    // one delegated listener set on the shadow root, keyed by data-wy-act
    // MOTION (lane M): a page that is sliding away (.wy-mo-ghost, inert) never answers a tap or a key
    const actOf = (ev) => (ev.target && typeof ev.target.closest === 'function' && !ev.target.closest('.wy-mo-ghost') ? ev.target.closest('[data-wy-act]') : null);
    const onClick = (ev) => {
        if (phone.dead) return;
        const t = actOf(ev);
        if (!t || !root.contains(t) || t.disabled || t.getAttribute('aria-disabled') === 'true') return;
        soWyAct(phone, t.getAttribute('data-wy-act'), t, ev);
    };
    const onKey = (ev) => {
        if (phone.dead) return;
        const t = actOf(ev);
        // a focusable non-button carrying an action (a list row, the banner) answers Enter / Space like a button
        if (t && t === ev.target && !/^(BUTTON|TEXTAREA|INPUT|SELECT)$/.test(t.tagName) && (ev.key === 'Enter' || ev.key === ' ') && !ev.repeat) {
            ev.preventDefault();
            soWyAct(phone, t.getAttribute('data-wy-act'), t, ev);
            return;
        }
        soWyEvent(phone, 'keydown', ev);
    };
    const pass = (type) => (ev) => {
        if (!phone.dead) soWyEvent(phone, type, ev);
    };
    const listeners = [['click', onClick, false], ['keydown', onKey, false]];
    for (const type of ['keyup', 'input', 'change', 'pointerdown', 'pointermove', 'pointerup', 'pointercancel', 'contextmenu']) listeners.push([type, pass(type), false]);
    listeners.push(['beforeinput', pass('beforeinput'), false]);   // A17 (2026-11-19): the 世界用语 editor's 「最多 N 个字」 hint
    listeners.push(['scroll', pass('scroll'), true]);
    for (const [type, fn, cap] of listeners) shadow.addEventListener(type, fn, cap);
    // the page is hidden → every hold control stops (Task 16 wires each control's _stop)
    const onVis = () => {
        if (phone.dead) return;
        for (const h of shadow.querySelectorAll('[data-wy-hold]')) if (typeof h._stop === 'function') h._stop();
    };
    doc.addEventListener('visibilitychange', onVis);
    let ro = null;
    const RO = doc.defaultView ? doc.defaultView.ResizeObserver : null;
    if (typeof RO === 'function') {
        ro = new RO(() => soWyApplyTheme(phone));
        ro.observe(hostEl);
    }
    // 动画: the system's reduced-motion setting changed → re-resolve the root flag (跟随系统 follows it live)
    const mq = soWyMotionQuery(doc);
    const onMq = () => {
        if (!phone.dead) soWyApplyMotion(phone);
    };
    if (mq) {
        if (typeof mq.addEventListener === 'function') mq.addEventListener('change', onMq);
        else mq.addListener(onMq);
    }
    const moUnwire = soWyMoWire(phone);   // MOTION (lane M): press feedback, scroll states, gestures
    phone.destroy = () => {
        if (phone.dead) return;
        // the live call scene: closing the phone (or the join closing it on a chat change) hangs up a live call / stops a ringing one
        if (typeof soWyCsLeave === 'function') {
            try { soWyCsLeave(phone); } catch (e) { /* leaving never breaks the close */ }
        }
        // MOTION (lane M): with motion on, the screen keeps its last picture while the frame plays its leave (soWyMoLinger)
        const linger = soWyMoOn(phone);
        phone.dead = true;
        for (const id of phone.timers) clearTimeout(id);
        phone.timers.clear();
        doc.removeEventListener('visibilitychange', onVis);
        for (const [type, fn, cap] of listeners) shadow.removeEventListener(type, fn, cap);
        moUnwire();
        if (ro) ro.disconnect();
        if (mq) {
            if (typeof mq.removeEventListener === 'function') mq.removeEventListener('change', onMq);
            else if (typeof mq.removeListener === 'function') mq.removeListener(onMq);
        }
        if (linger) soWyMoLinger(phone);
        else shadow.replaceChildren();
    };
    soWyApplyTheme(phone);
    soWyApplyMotion(phone);
    phone.stack = [soWyRootPage(phone)];
    soWyRender(phone, false);
    // the live call scene: a phone opened while this page still runs a live call goes straight to its panel (over that chat)
    if (typeof soWyCsResume === 'function') soWyCsResume(phone);
    soWyMoPower(phone);   // MOTION (lane M): the screen wakes up (Tier 3)
    return phone;
}

// The only path from the UI to env.call: refresh right after starting (the player's own line and the typing row show while the
// call runs) and after the result; the result becomes a per-chat note. A tap that lands on a running call (busy) keeps old notes.
async function soWyDo(phone, kind, args, onProgress) {
    if (!phone || phone.dead) return { error: 'gone' };
    const a = soWyIsObj(args) ? args : {};
    // the AI auto-reply switch OFF (2026-11-20): every send path ends here, so this ONE line turns each into the zero-call `put` (stored, no request)
    if (kind === 'send' && typeof soWyArHolds === 'function' && soWyArHolds(phone)) kind = 'put';
    const key = typeof a.cid === 'string' && a.cid ? a.cid : '*' + kind;
    if (!soWyEnvFlight(phone)) delete phone.notes[key];
    const c0 = typeof a.cid === 'string' ? soWyChat(soWyEnvState(phone), a.cid) : null;
    const had = c0 ? new Set(c0.msgs.map((m) => m.id)) : null;
    let p;
    try {
        p = Promise.resolve(phone.env.call(kind, a, onProgress));
    } catch (e) {
        p = Promise.resolve({ error: soWyErrText(e) });
    }
    phone.refresh();
    let r;
    try {
        r = await p;
    } catch (e) {
        r = { error: soWyErrText(e) };
    }
    if (phone.dead) return r;
    soWyNoteFor(phone, kind, key, r);
    if (soWyIsObj(r) && r.ok && had) soWyReveal(phone, a.cid, had);
    phone.refresh();
    return r;
}

function soWyChatOpen(phone, cid) {
    const top = phone.stack[phone.stack.length - 1];
    return !!top && top.k === 'chat' && top.cid === cid;
}

// The open chat is being looked at: new lines there count as read (one commit, only when something changed).
function soWyReadOpen(phone, cid) {
    if (phone.dead || !soWyChatOpen(phone, cid)) return;
    const st = soWyEnvState(phone);
    if (!soWyChat(st, cid)) return;
    const c = soWyClone(st);
    if (soWyMarkRead(c, cid)) phone.env.commit(c, 'read');
}

// After an ok: the new lines of others in the OPEN chat come in one by one (typeMin–typeMax each, by length; a time / sys line rides
// with the next one); reduced motion → all at once. Lines that landed in a chat the player is not looking at simply wait, unread.
function soWyReveal(phone, cid, had) {
    const TM = THEATER_WEIYU_TIMING;
    const c = soWyChat(soWyEnvState(phone), cid);
    if (!c) return;
    const fresh = c.msgs.filter((m) => !had.has(m.id) && m.src !== 'me');
    if (!fresh.length || !soWyChatOpen(phone, cid) || soWyEnvReduced(phone)) {
        phone.reveal = null;
        soWyReadOpen(phone, cid);
        return;
    }
    const content = (m) => !!m && m.t !== 'time' && m.t !== 'sys';
    const dur = (m) => {
        const n = Array.from(String(m && m.v != null ? m.v : '')).length;
        return Math.max(TM.typeMin, Math.min(TM.typeMax, TM.typeMin + n * 45));
    };
    const rv = { cid, ids: fresh.map((m) => m.id) };
    const nextContent = () => fresh.find((m) => rv.ids.includes(m.id) && content(m));
    phone.reveal = rv;
    const step = () => {
        if (phone.reveal !== rv) return;
        while (rv.ids.length) {
            const id = rv.ids.shift();
            if (content(fresh.find((m) => m.id === id))) break;
        }
        if (!rv.ids.length) {
            phone.reveal = null;
            soWyReadOpen(phone, cid);
        }
        phone.refresh();
        if (phone.reveal === rv) soWyLater(phone, step, dur(nextContent()));
    };
    soWyLater(phone, step, dur(nextContent()));
}

// ---- Task 16: the hold-to-load control (ported from the scene runtime's holdCtl; h / T / S.flight / CAN_MORE → the `o` argument) ---
//
// soWyHold(doc, o) — o = { label, hint, aria, ms, hintMs?, blocked(), fire() }. A press-and-hold is the ONLY way it spends a call:
// pointerdown (primary button) starts the timer and the fill; it fires after o.ms. An early pointerup, pointercancel (the browser took
// the gesture to scroll), lostpointercapture, a move of more than holdMove px, blur, or the page hidden (soWyMount's visibilitychange
// listener → _stop) cancels it; a press shorter than holdTap ms shows o.hint for hintMs. Enter / Space held works the same (key repeat
// ignored). click is always preventDefault (a tap never fires); contextmenu is prevented; blocked() true → never starts, never fires.
function soWyHold(doc, o) {
    const TM = THEATER_WEIYU_TIMING;
    const x = soWyIsObj(o) ? o : {};
    const ms = Number(x.ms) > 0 ? Number(x.ms) : TM.holdMs;
    const hintMs = Number(x.hintMs) > 0 ? Number(x.hintMs) : TM.hintMs;
    const blocked = () => {
        try { return typeof x.blocked === 'function' && !!x.blocked(); } catch (e) { return true; }
    };
    let cur = String(x.label == null ? '' : x.label);
    const txt = soWyEl(doc, 'span', { class: 'wy-hold-t', text: cur });
    const b = soWyEl(doc, 'button', { type: 'button', class: ['wy-so', 'wy-hold'], data: { 'wy-hold': '' }, aria: { label: String(x.aria == null ? '' : x.aria) } },
        soWyEl(doc, 'span', { class: 'wy-hold-fill', aria: { hidden: 'true' } }), txt);
    b.style.setProperty('--wy-hold-ms', ms + 'ms');
    let timer = null;
    let hintT = null;
    let armed = false;
    let t0 = 0;
    let sx = 0;
    let sy = 0;
    const stop = () => {
        if (timer) clearTimeout(timer);
        timer = null;
        armed = false;
        const was = b.classList.contains('holding');
        b.classList.remove('holding');
        if (was && typeof soWyMoHoldDrain === 'function') soWyMoHoldDrain(b, true); /* MOTION-HOOK (lane M): the 200 ms drain */
    };
    const hint = () => {
        if (!x.hint) return;
        txt.textContent = String(x.hint);
        clearTimeout(hintT);
        hintT = setTimeout(() => { if (b.isConnected) txt.textContent = cur; }, hintMs);
    };
    const start = () => {
        if (armed || blocked()) return false;
        armed = true;
        t0 = Date.now();
        if (typeof soWyMoHoldDrain === 'function') soWyMoHoldDrain(b, false); /* MOTION-HOOK (lane M): a new press ends a running drain */
        void b.offsetWidth; // restart the fill transition from empty
        b.classList.add('holding');
        timer = setTimeout(() => {
            timer = null;
            armed = false;
            b.classList.remove('holding');
            if (!blocked() && b.isConnected && typeof x.fire === 'function') {
                if (typeof soWyMoHoldFire === 'function') soWyMoHoldFire(b); /* MOTION-HOOK (lane M): the completion pop */
                x.fire();
            }
        }, ms);
        return true;
    };
    const release = () => {
        if (!armed) return;
        const quick = Date.now() - t0 < TM.holdTap;
        stop();
        if (quick) hint();
    };
    const isKey = (e) => e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar';
    b.addEventListener('pointerdown', (e) => {
        if (e.button != null && e.button !== 0) return;
        sx = e.clientX || 0;
        sy = e.clientY || 0;
        if (start() && e.pointerId != null && typeof b.setPointerCapture === 'function') {
            try { b.setPointerCapture(e.pointerId); } catch (er) { /* a pointer that cannot be captured */ }
        }
    });
    b.addEventListener('pointerup', release);
    b.addEventListener('pointercancel', stop);
    b.addEventListener('lostpointercapture', () => { if (armed) stop(); });
    b.addEventListener('pointermove', (e) => {
        if (armed && (Math.abs((e.clientX || 0) - sx) > TM.holdMove || Math.abs((e.clientY || 0) - sy) > TM.holdMove)) stop();
    });
    b.addEventListener('contextmenu', (e) => e.preventDefault());
    b.addEventListener('keydown', (e) => {
        if (!isKey(e)) return;
        e.preventDefault();
        e.stopPropagation();
        if (e.repeat) return;
        start();
    });
    b.addEventListener('keyup', (e) => {
        if (!isKey(e)) return;
        e.preventDefault();
        release();
    });
    b.addEventListener('blur', stop);
    b.addEventListener('click', (e) => e.preventDefault());
    b._stop = stop;
    b._label = (t) => {
        cur = String(t == null ? '' : t);
        txt.textContent = cur;
    };
    return b;
}

// ---- the cause line (pt8, owner's playtest 2026-11-18) -------------------------------------------------------------------------------
// soWyCauseLine(r) → '' | ONE line saying why a soWyCall result failed, for the screen (always through soWyCauseClean: credentials gone,
// ≤ THEATER_WEIYU_CAUSE_CAP characters). {error} → the error text itself (soWyCauseErr); {failed, cause} → the join's real error (detail)
// when there is one, else 空回复 / 回复的格式不对，没法用（n 字）+ the finish reason in plain words (soWyCauseFinish). Everything else (ok / busy / wait / aborted / stale, a
// refusal before any request — 'gone', 'call') → ''. Set as text, never as HTML.
function soWyCauseLine(r) {
    try {
        if (!soWyIsObj(r) || r.ok) return '';
        const T = THEATER_WEIYU_TEXT;
        if (r.error != null) return soWyCauseErr(r.error);
        if (!r.failed || !soWyIsObj(r.cause)) return '';
        const c = r.cause;
        if (typeof c.detail === 'string' && c.detail.trim()) return soWyCauseErr(c.detail);
        const f = soWyCauseFinish(c.finish);
        const n = Number(c.chars) > 0 ? Math.floor(Number(c.chars)) : 0;
        if (!n) return soWyCauseClean(T.causeEmpty + f);
        return soWyCauseClean(soWyFmt(T.causeUnread, { n }) + f);
    } catch (e) {
        return '';
    }
}

// B1 (playtest 2026-11-19): the model's finish reason as the cause line's tail — never the raw English token for a known one. → '' for the
// normal end (stop / end_turn / …) or none · ' · 被截断' (length / max_tokens / …) · ' · 被内容过滤拦了' (content_filter / safety / …) ·
// '（<token>）' for anything else (kept, so a report still carries it).
const THEATER_WEIYU_FINISH_NORMAL = ['stop', 'end_turn', 'stop_sequence', 'eos', 'finish_reason_stop', 'completed', 'complete'];
const THEATER_WEIYU_FINISH_CUT = ['length', 'max_tokens', 'max_output_tokens', 'model_length', 'finish_reason_max_tokens', 'max_tokens_exceeded'];
function soWyCauseFinish(finish) {
    const T = THEATER_WEIYU_TEXT;
    const f = String(finish == null ? '' : finish).trim();
    const k = f.toLowerCase();
    if (!f || THEATER_WEIYU_FINISH_NORMAL.includes(k)) return '';
    if (THEATER_WEIYU_FINISH_CUT.includes(k)) return ' · ' + T.causeCut;
    if (/filter|safety|recitation|blocklist|prohibited|spii|refusal/.test(k)) return ' · ' + T.causeFiltered;
    return '（' + f + '）';
}

// An error text as the cause line: a provider's JSON error body after an HTTP status is read down to its message (「HTTP 429 Too Many
// Requests · rate limit exceeded」 — a cut / unreadable body stays as it is); a network failure / a time-out with no HTTP status gets the
// short label in front (连不上网络 · … / 超时 · …, the join's 「错误：」 then dropped). Always soWyCauseClean'ed.
function soWyCauseErr(raw) {
    const T = THEATER_WEIYU_TEXT;
    let s = String(raw == null ? '' : raw).trim();
    const j = /^([\s\S]*?\bHTTP \d{3}\b[^{]*?)\s*(\{[\s\S]*\})\s*$/.exec(s);
    if (j) {
        let m = '';
        try {
            const o = JSON.parse(j[2]);
            const e = soWyIsObj(o) ? o.error : null;
            m = typeof e === 'string' ? e : soWyIsObj(e) && typeof e.message === 'string' ? e.message : typeof o.message === 'string' ? o.message : '';
        } catch (x) {
            m = '';
        }
        if (m.trim()) s = j[1].trim() + ' · ' + m.trim();
    }
    if (!/\bHTTP \d{3}\b/.test(s)) {
        const bare = s.replace(/^错误：\s*/, '');
        if (/failed to fetch|networkerror|network error|load failed|fetch failed|ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|ERR_NETWORK|ERR_INTERNET_DISCONNECTED|ERR_CONNECTION/i.test(s)) {
            s = T.causeNet + ' · ' + bare;
        } else if (/timed? ?out|timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(s)) {
            s = T.causeTimeout + ' · ' + bare;
        }
    }
    return soWyCauseClean(s);
}

// failed → bad (send: noReply) + the cause line (why) · wait → the reason, cleared after waitMs · error → its cause line · aborted ·
// busy / stale → unchanged · ok → cleared
function soWyNoteFor(phone, kind, key, r) {
    const T = THEATER_WEIYU_TEXT;
    if (!soWyIsObj(r)) return;
    if (r.ok) delete phone.notes[key];
    else if (r.failed) {
        const n = kind === 'send' ? { kind: 'noReply', text: T.noReply } : { kind: 'bad', text: T.bad };
        const why = soWyCauseLine(r);
        if (why) n.why = why;
        phone.notes[key] = n;
    }
    else if (typeof r.wait === 'string' && r.wait) {
        const n = { kind: 'wait', text: r.wait };
        phone.notes[key] = n;
        soWyLater(phone, () => {
            if (phone.notes[key] !== n) return;
            delete phone.notes[key];
            phone.refresh();
        }, THEATER_WEIYU_TIMING.waitMs);
    } else if (r.error != null) phone.notes[key] = { kind: 'error', text: soWyCauseLine(r) || String(r.error) };
    else if (r.aborted) phone.notes[key] = { kind: 'aborted', text: T.aborted };
}

// ---- MOTION (lane M) ---------------------------------------------------------------------------------------------------------
//
// The phone's motion: the designer's mock-up (docs/superpowers/specs/2026-11-16-weiyu-phone-frame-mockup.html §3 and its MOTION table),
// three tiers. Owner: "less like clicking and scrolling through spreadsheets". Rules: only transform / opacity move; nothing blocks input
// (a page that is leaving is inert and lets every tap through, the arriving page is live from its first frame, the next tap cuts any
// motion short); everything ≤ ~400 ms except the deliberate ones (the hold charge, the power-on). ALL of it runs only when soWyMoOn(phone):
// the resolved 动画 flag (phone.motion, soWyApplyMotion) is 'on' AND the browser has the Web Animations API. Otherwise every path here is
// skipped and the phone is today's instant one (jsdom has no Web Animations: the unit suite sees exactly that). The CSS of every motion is
// the MOTION (lane M) section of weiyu.css, each rule under .wy[data-wy-motion="on"] (关 = the zeroing rule). Timers: soWyLater only.

const THEATER_WEIYU_MO = Object.freeze({
    push: 300, back: 260, pushEase: 'cubic-bezier(.2,.8,.2,1)', backEase: 'cubic-bezier(.3,.6,.2,1)', drift: '-24%', dim: 0.28,
    tab: 180, tabEase: 'cubic-bezier(.2,.8,.2,1)', tabShift: 14, icon: 300, iconEase: 'cubic-bezier(.2,1.6,.4,1)',
    close: 140, pressOff: 90, pressMove: 10, glide: 260, glideEase: 'cubic-bezier(.2,.8,.2,1)', condense: 4, fired: 600, newMax: 8,
    linger: 260, rowMove: 340, edge: 28, swipeDone: 0.35, swipeFling: 0.5, rip: 450, menu: 200, menuEase: 'cubic-bezier(.2,1.3,.4,1)',
    shared: 340, sharedEase: 'cubic-bezier(.3,.7,.1,1)', band: 60, bandRest: 110, bandBack: 420, bandEase: 'cubic-bezier(.2,1.35,.4,1)',
    // the hold's early-release drain: the mock-up's MOTION table, "Hold charge feel" (early release drains in 200 ms) = weiyu.css's fill
    // transition while on (0.2s cubic-bezier(0.4, 0, 0.2, 1)) — soWyMoHoldDrain
    drain: 200, drainEase: 'cubic-bezier(.4,0,.2,1)',
});

function soWyMoCan(phone) {
    try {
        const w = phone.host.ownerDocument.defaultView;
        return !!w && typeof w.Element === 'function' && typeof w.Element.prototype.animate === 'function';
    } catch (e) {
        return false;
    }
}

// THE gate of every motion path.
function soWyMoOn(phone) {
    return !!phone && !phone.dead && phone.motion === 'on' && soWyMoCan(phone);
}

// el.animate, tagged (soWyMoAnims / soWyMoHalt find the phone's own animations by the id); null when it cannot run.
function soWyMoAnim(el, frames, opts) {
    try {
        const a = el.animate(frames, opts);
        a.id = 'wy-mo';
        return a;
    } catch (e) {
        return null;
    }
}

function soWyMoAnims(el, deep) {
    try {
        return typeof el.getAnimations === 'function' ? el.getAnimations(deep ? { subtree: true } : undefined).filter((a) => a.id === 'wy-mo') : [];
    } catch (e) {
        return [];
    }
}

// An element's current transform / opacity (mid-animation included) — where a motion that takes over starts.
function soWyMoNow(el, prop) {
    try {
        const v = el.ownerDocument.defaultView.getComputedStyle(el)[prop || 'transform'];
        return v == null ? null : String(v);
    } catch (e) {
        return null;
    }
}

function soWyMoKid(el, cls) {
    for (const c of el ? el.children : []) if (c.classList.contains(cls)) return c;
    return null;
}

// What the motions need from the page that is going, read BEFORE the new one is built in: message rows and the typing row (a refresh
// of the open chat), list rows (a refresh of a list), a hold control that just fired. sameish = this render refreshes the same page.
function soWyMoSnap(phone, old, page, sameish) {
    const s = { page: page || null, msgs: null, typing: null, rows: null, firedAt: 0, tabBadge: null };
    const h = old.querySelector('[data-wy-hold]');
    if (h && Date.now() - (Number(h._wyMoFired) || 0) < THEATER_WEIYU_MO.fired) s.firedAt = Number(h._wyMoFired);
    const tb = old.querySelector('.wy-tab .wy-badge');
    s.tabBadge = tb ? tb.textContent : '';
    if (!sameish || !page) return s;
    try {
        if (page.k === 'chat') {
            s.msgs = new Map();
            for (const r of old.querySelectorAll('[data-wy-msg]')) {
                // t: the line's kind (his 撤回 turns a line into a recall in place — same id; integration 2026-11-17)
                s.msgs.set(r.getAttribute('data-wy-msg'), { top: r.getBoundingClientRect().top, el: r, open: !!r.querySelector('.wy-vtext, .wy-peekpill'), t: r.getAttribute('data-wy-t') });
            }
            const ty = old.querySelector('.wy-typing');
            if (ty) s.typing = (ty.querySelector('.wy-bubble') || ty).getBoundingClientRect();
            const sc = soWyMoKid(old, 'wy-scroll');
            if (sc) s.view = sc.getBoundingClientRect();
        } else if (page.k === 'tabs' || page.k === 'sublist') {
            s.rows = new Map();
            for (const r of old.querySelectorAll('[data-wy-row]')) {
                const pv = r.querySelector('.wy-pv');
                const bd = r.querySelector('.wy-avw .wy-badge');
                s.rows.set(r.getAttribute('data-wy-row'), { top: r.getBoundingClientRect().top, pv: pv ? pv.textContent : '', badge: bd ? bd.textContent || '•' : '' });
            }
        }
    } catch (e) { /* no layout: nothing to compare */ }
    return s;
}

// Push / back: the old page stays in the phone (absolute, inert, aria-hidden) while it slides away; a transition still running is ended
// first (its outgoing page goes now; where it stood is handed on, so a back that cuts a push short starts from there).
function soWyMoKeep(phone, old, el, nav) {
    const prev = soWyMoDropGhost(phone);
    const from = soWyMoNow(old);
    for (const a of soWyMoAnims(old)) a.cancel();
    old.classList.remove('wy-mo-top');
    phone.root.insertBefore(el, old);
    old.classList.add('wy-mo-ghost');
    if (nav === 'back') old.classList.add('wy-mo-over');
    old.setAttribute('inert', '');
    old.setAttribute('aria-hidden', 'true');
    const hand = phone.moHand || null;   // the edge swipe hands over where its finger left the two pages (Tier 2)
    phone.moHand = null;
    phone.moGhost = {
        el: old, inEl: el, nav, fresh: true, dim: null, timer: null,
        from: hand && hand.from ? hand.from : from && from !== 'none' ? from : null,
        prev: hand ? hand : prev && prev.nav === 'push' && nav === 'back' ? prev : null,
    };
}

// Ends a transition now (or only `only`, when it is still the current one): the outgoing page and the dim go; → where they stood.
function soWyMoDropGhost(phone, only) {
    const g = phone.moGhost;
    if (!g || (only && g !== only)) return null;
    phone.moGhost = null;
    if (g.timer) {
        clearTimeout(g.timer);
        phone.timers.delete(g.timer);
    }
    const out = { nav: g.nav, transform: soWyMoNow(g.el), dim: g.dim ? Number(soWyMoNow(g.dim, 'opacity')) : null };
    for (const a of soWyMoAnims(g.el).concat(g.dim ? soWyMoAnims(g.dim) : [])) a.cancel();
    g.el.remove();
    if (g.dim) g.dim.remove();
    if (g.inEl) g.inEl.classList.remove('wy-mo-top');
    return out;
}

// The slide itself (Tier 1): push = the new page comes in from the right over the old one, which drifts left under a dim; back = the
// reverse (the leaving page on top). The dim is a sibling of the pages (between them), so a refresh of the arriving page never loses it.
function soWyMoSlide(phone, el, nav) {
    const M = THEATER_WEIYU_MO;
    const g = phone.moGhost;
    if (!g || !g.fresh) return;
    g.fresh = false;
    const push = nav === 'push';
    const o = { duration: push ? M.push : M.back, easing: push ? M.pushEase : M.backEase };
    const keep = Object.assign({ fill: 'forwards' }, o);
    g.dim = soWyEl(phone.host.ownerDocument, 'div', { class: 'wy-mo-dim', aria: { hidden: 'true' } });
    phone.root.insertBefore(g.dim, phone.layer);
    if (push) {
        const fly = soWyMoSharedPrep(phone, g.el, el);   // Tier 3: measured at rest, before the slide moves anything
        el.classList.add('wy-mo-top');
        soWyMoAnim(el, [{ transform: 'translateX(100%)' }, { transform: 'none' }], o);
        soWyMoAnim(g.el, [{ transform: g.from || 'none' }, { transform: 'translateX(' + M.drift + ')' }], keep);
        soWyMoAnim(g.dim, [{ opacity: 0 }, { opacity: M.dim }], keep);
        // Tier 2: a chat's last ≤ 8 items settle in, bottom first (CSS .wy-mo-si, 28 ms apart)
        const msgs = el.querySelector('.wy-msgs');
        if (msgs) [...msgs.children].reverse().slice(0, M.newMax).forEach((n, i) => { n.classList.add('wy-mo-si'); n.style.setProperty('--wy-mo-i', String(i)); });
        if (fly) fly();   // Tier 3: the avatar + name fly from the row into the header
    } else {
        const p = g.prev;
        const start = p && p.transform && p.transform !== 'none' ? p.transform : 'translateX(' + M.drift + ')';
        soWyMoAnim(g.el, [{ transform: g.from || 'none' }, { transform: 'translateX(100%)' }], keep);
        soWyMoAnim(el, [{ transform: start }, { transform: 'none' }], o);
        soWyMoAnim(g.dim, [{ opacity: p && Number.isFinite(p.dim) ? p.dim : M.dim }, { opacity: 0 }], keep);
    }
    g.timer = soWyLater(phone, () => soWyMoDropGhost(phone, g), o.duration + 30);
}

// A refresh of the page that is sliding in (a reply landing mid-push): the new copy takes over the old copy's slide where it stands.
function soWyMoCarry(phone, from, to) {
    for (const a of soWyMoAnims(from)) {
        const fx = a.effect;
        if (fx && typeof fx.getKeyframes === 'function' && a.playState !== 'finished') {
            const b = soWyMoAnim(to, fx.getKeyframes(), fx.getTiming());
            if (b && a.currentTime != null) b.currentTime = a.currentTime;
        }
        a.cancel();
    }
    const g = phone.moGhost;
    if (g && g.inEl === from) {
        g.inEl = to;
        if (from.classList.contains('wy-mo-top')) to.classList.add('wy-mo-top');
    }
}

// Layout classes a motion needs, set before the scroll positions are restored: a page whose top bar sits right above its scroller gets the
// overlaid bar (content scrolls under it; the bar condenses — soWyMoScrolled).
function soWyMoPrep(phone, el, page) {
    if (!soWyMoOn(phone)) return;
    const top = soWyMoKid(el, 'wy-top');
    const sc = soWyMoKid(el, 'wy-scroll');
    if (top && sc && top.nextElementSibling === sc) el.classList.add('wy-mo-ovl');
    soWyMoHeadAv(phone, el, page);   // Tier 3
}

// The top bar condenses once its scroller has moved (> 4 px); the tab bar lifts while there is more list under it.
function soWyMoScrolled(sc) {
    const page = sc && sc.parentElement;
    if (!page || !page.classList.contains('wy-page')) return;
    const top = soWyMoKid(page, 'wy-top');
    if (top) top.classList.toggle('wy-mo-cond', sc.scrollTop > THEATER_WEIYU_MO.condense);
    const tb = soWyMoKid(page, 'wy-tabbar');
    if (tb) tb.classList.toggle('wy-mo-lift', sc.scrollTop + sc.clientHeight < sc.scrollHeight - 2);
}

// After every render with motion on: the page's chrome states, the hold's completion pop carried over, then the motion of this render.
function soWyMoAfter(phone, s, el, top, same, nav) {
    if (!soWyMoOn(phone)) return;
    const sc = soWyMoKid(el, 'wy-scroll');
    if (sc) soWyMoScrolled(sc);
    if (s.firedAt) {
        const h = el.querySelector('[data-wy-hold]');
        if (h) h.classList.add('wy-mo-fired');   // the old control was replaced right after it fired: the pop plays on the new one, once
    }
    const g = phone.moGhost;
    if (g && g.fresh && g.inEl === el) soWyMoSlide(phone, el, nav);
    else if (nav === 'tab') soWyMoTab(phone, s, el, top);
    else if (same && top && top.k === 'chat') soWyMoChat(phone, s, el);
    if (top && (top.k === 'tabs' || top.k === 'sublist') && sc) soWyMoRows(phone, same ? s : null, el, sc);   // Tier 2
    const tb = el.querySelector('.wy-tab .wy-badge');   // Tier 2: the tab's unread count changed → it pops
    if (same && tb && s.tabBadge !== null && tb.textContent !== s.tabBadge) tb.classList.add('wy-mo-pop');
}

// Tab switch (Tier 1): the content cross-fades ±14 px toward the tab's side; the active icon pops .7 → 1.
function soWyMoTab(phone, s, el, top) {
    const M = THEATER_WEIYU_MO;
    const order = ['chats', 'contacts', 'me'];
    const a = order.indexOf(s.page && s.page.k === 'tabs' ? s.page.tab : '');
    const b = order.indexOf(top && top.tab);
    const sc = soWyMoKid(el, 'wy-scroll');
    const dx = b >= a ? M.tabShift : -M.tabShift;
    if (sc) soWyMoAnim(sc, [{ opacity: 0, transform: 'translateX(' + dx + 'px)' }, { opacity: 1, transform: 'none' }], { duration: M.tab, easing: M.tabEase });
    const icon = el.querySelector('.wy-tab.wy-on svg');
    if (icon) soWyMoAnim(icon, [{ transform: 'scale(.7)' }, { transform: 'none' }], { duration: M.icon, easing: M.iconEase });
}

// A refresh of the open chat. Tier 1: lines that were not there before arrive (own vs incoming differ — CSS .wy-mo-new; the last 8 at
// most); when the chat followed its end, the column glides by what was added instead of jumping. Tier 2: a line that went (deleted, cut by
// a regenerate) folds away where it stood while the lines after it glide up (FLIP, only what is in view); an opened voice text / a peeked
// recall drops in; a recall folds a phantom bubble into its grey line; a 拍一拍 wobbles the nudged person's picture. Tier 3: the typing
// bubble grows into the reply (soWyMoGrow).
function soWyMoChat(phone, s, el) {
    const M = THEATER_WEIYU_MO;
    if (!s.msgs) return;
    const list = el.querySelector('.wy-msgs');
    const sc = soWyMoKid(el, 'wy-scroll');
    if (!list || !sc) return;
    const rows = [...el.querySelectorAll('[data-wy-msg]')];
    const ids = new Set(rows.map((r) => r.getAttribute('data-wy-msg')));
    const fresh = rows.filter((r) => !s.msgs.has(r.getAttribute('data-wy-msg')));
    let view = null;
    const shifts = [];
    try {
        view = sc.getBoundingClientRect();
        for (const r of rows) {
            const o = s.msgs.get(r.getAttribute('data-wy-msg'));
            if (o) shifts.push([r, o.top - r.getBoundingClientRect().top, o]);
        }
    } catch (e) {
        return;
    }
    const d0 = shifts.length ? shifts[shifts.length - 1][1] : 0;
    const uniform = shifts.every(([, d]) => Math.abs(d - d0) < 1);
    const grown = s.typing ? soWyMoGrow(phone, s, el, fresh, uniform ? d0 : 0) : null;   // Tier 3
    for (const r of fresh.slice(-M.newMax)) if (r !== grown) r.classList.add('wy-mo-new');
    const ty = el.querySelector('.wy-typing');
    if (ty && !s.typing) ty.classList.add('wy-mo-new');
    if (uniform) {
        if (Math.abs(d0) >= 1 && Math.abs(d0) < sc.clientHeight) soWyMoAnim(list, [{ transform: 'translateY(' + d0 + 'px)' }, { transform: 'none' }], { duration: M.glide, easing: M.glideEase });
    } else {
        const near = (y) => y > view.top - 200 && y < view.bottom + 200;
        for (const [r, d, o] of shifts) if (Math.abs(d) >= 1 && near(o.top)) soWyMoAnim(r, [{ transform: 'translateY(' + d + 'px)' }, { transform: 'none' }], { duration: M.glide, easing: M.glideEase });
    }
    // Tier 2: what went folds away where it stood (a copy of the old line, laid over the scroller; in view only)
    const old = s.view || view;
    for (const [id, o] of s.msgs) {
        if (ids.has(id) || !o.el || o.top < old.top - 60 || o.top > old.bottom) continue;
        soWyMoFold(phone, sc, view, o);
    }
    const st = phone.memo && phone.memo.state;
    const chat = st && phone.cur && phone.cur.k === 'chat' ? soWyChat(st, phone.cur.cid) : null;
    const msgOf = (id) => (chat ? chat.msgs.find((m) => m.id === id) : null);
    // his own 撤回 (the menu, lane D) changes the kind of a line that was already there: it arrives as a recall too (integration)
    const recalled = rows.filter((r) => r.classList.contains('wy-recall') && s.msgs.has(r.getAttribute('data-wy-msg')) && s.msgs.get(r.getAttribute('data-wy-msg')).t !== 'recall');
    for (const r of recalled) r.classList.add('wy-mo-new');
    for (const r of fresh.concat(recalled)) {
        // Tier 2: a recall folds a phantom bubble away into its grey line
        if (r.classList.contains('wy-recall') && r.classList.contains('wy-mo-new')) {
            const m = msgOf(r.getAttribute('data-wy-msg'));
            const ph = soWyEl(el.ownerDocument, 'span', { class: ['wy-mo-phantom', m && m.u === THEATER_WEIYU_ME ? 'wy-mo-phantom-me' : ''], aria: { hidden: 'true' } });
            r.appendChild(ph);
            soWyLater(phone, () => ph.remove(), 340);
        }
        // Tier 2: 拍一拍 — the nudged person's latest picture in this chat wobbles
        if (r.classList.contains('wy-nudge')) {
            const m = msgOf(r.getAttribute('data-wy-msg'));
            const avs = m && m.to ? [...list.querySelectorAll('.wy-m > .wy-av')].filter((a) => a.getAttribute('data-wy-pid') === m.to) : [];
            const a = avs[avs.length - 1];
            if (a) soWyMoAnim(a, [{ transform: 'none' }, { transform: 'rotate(-12deg) translateX(-2px)', offset: 0.2 }, { transform: 'rotate(9deg)', offset: 0.45 },
                { transform: 'rotate(-5deg)', offset: 0.7 }, { transform: 'rotate(2deg)', offset: 0.85 }, { transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.3,.7,.4,1)' });
        }
    }
    // Tier 2: an opened voice text / a peeked recall drops in (the voice bar's waves pulse as if it played)
    for (const [r, , o] of shifts) {
        const x = r.querySelector('.wy-vtext, .wy-peekpill');
        if (!x || o.open) continue;
        x.classList.add('wy-mo-vt');
        const svg = r.querySelector('.wy-voice svg');
        if (svg) soWyMoAnim(svg, [{ opacity: 1 }, { opacity: 0.3 }, { opacity: 1 }, { opacity: 0.3 }, { opacity: 1 }], { duration: 600, easing: 'ease-in-out' });
    }
}

// Tier 2: a line that went folds away (shrinks to .55 and fades, 220 ms) at the place it stood, over the scroller; then the copy goes.
function soWyMoFold(phone, sc, view, o) {
    const c = o.el.cloneNode(true);
    c.classList.remove('wy-mo-new', 'wy-mo-si');
    c.classList.add('wy-mo-folding');
    c.setAttribute('aria-hidden', 'true');
    c.setAttribute('inert', '');
    c.removeAttribute('data-wy-msg');
    for (const x of c.querySelectorAll('[data-wy-act]')) x.removeAttribute('data-wy-act');
    if (!sc.classList.contains('wy-mo-rel')) sc.classList.add('wy-mo-rel');
    c.style.top = Math.round(o.top - view.top + sc.scrollTop) + 'px';
    sc.insertBefore(c, sc.firstChild);   // never after the hold line: it stays the conversation's last child (lane D; integration)
    const mb = c.querySelector('.wy-mb') || c;
    soWyMoAnim(mb, [{ transform: 'none', opacity: 1 }, { transform: 'scale(.55) translateY(-6px)', opacity: 0 }], { duration: 220, easing: 'cubic-bezier(.4,0,1,1)', fill: 'forwards' });
    soWyMoAnim(c, [{ opacity: 1 }, { opacity: 0 }], { duration: 220, easing: 'ease', fill: 'forwards' });
    soWyLater(phone, () => c.remove(), 240);
}

// Tier 2 · the chat list after a render: on a refresh, a row that moved (a reply landed and sorted it to the top) slides from where it was
// (FLIP, 340 ms), its preview swaps in and the row glows (900 ms), its badge pops; then the reveal-once of rows below the fold.
function soWyMoRows(phone, s, el, sc) {
    const M = THEATER_WEIYU_MO;
    const rows = [...el.querySelectorAll('[data-wy-row]')];
    if (!rows.length) return;
    if (s && s.rows) {
        let view = null;
        try { view = sc.getBoundingClientRect(); } catch (e) { view = null; }
        for (const r of rows) {
            const o = s.rows.get(r.getAttribute('data-wy-row'));
            if (!o) continue;
            const pv = r.querySelector('.wy-pv');
            if (pv && pv.textContent !== o.pv) {
                r.classList.add('wy-mo-glow');
                pv.classList.add('wy-mo-swap');
            }
            const bd = r.querySelector('.wy-avw .wy-badge');
            if (bd && (bd.textContent || '•') !== o.badge) bd.classList.add('wy-mo-pop');
            let d = 0;
            try { d = o.top - r.getBoundingClientRect().top; } catch (e) { d = 0; }
            if (Math.abs(d) >= 1 && view && o.top < view.bottom + 200) {
                if (d > 0) r.classList.add('wy-mo-up');   // the row coming up passes over the others
                soWyMoAnim(r, [{ transform: 'translateY(' + d + 'px)' }, { transform: 'none' }], { duration: M.rowMove, easing: M.glideEase });
                soWyLater(phone, () => r.classList.remove('wy-mo-up'), M.rowMove + 20);
            }
        }
    }
    soWyMoReveal(phone, sc, rows);
}

// Tier 2 · rows reveal once: a row that is below the fold the first time its list shows rises in (fade + 16 px) when it first scrolls into
// view; remembered per chat (phone.moSeen), so a row never re-animates — not on a refresh, not when the list comes back.
function soWyMoReveal(phone, sc, rows) {
    if (phone.moIO) {
        phone.moIO.disconnect();
        phone.moIO = null;
    }
    const IO = phone.host.ownerDocument.defaultView.IntersectionObserver;
    if (typeof IO !== 'function') return;
    const seen = phone.moSeen || (phone.moSeen = new Set());
    let bottom = 0;
    try { bottom = sc.getBoundingClientRect().bottom; } catch (e) { return; }
    const io = new IO((es) => {
        for (const en of es) {
            if (!en.isIntersecting) continue;
            const r = en.target;
            io.unobserve(r);
            seen.add(r.getAttribute('data-wy-row'));
            if (soWyMoOn(phone)) r.classList.add('wy-mo-rv');
            r.classList.remove('wy-mo-pre');
        }
    }, { root: sc, threshold: 0.12 });
    let any = false;
    for (const r of rows) {
        const cid = r.getAttribute('data-wy-row');
        if (seen.has(cid)) continue;
        if (r.getBoundingClientRect().top < bottom) {
            seen.add(cid);
            continue;
        }
        r.classList.add('wy-mo-pre');
        io.observe(r);
        any = true;
    }
    if (any) phone.moIO = io;
    else io.disconnect();
}

// Tier 3 · typing → bubble: the first new line of someone else takes the typing bubble's place and size and opens to its own (260 ms); its
// words fade in (160 ms after 110 ms); a typing row that stays (more lines to come) glides down from where it was. → that line (it then
// skips the plain arrival) or null. d0 = the column's glide this render (the start is where the eye last saw the typing bubble).
function soWyMoGrow(phone, s, el, fresh, d0) {
    const r = fresh.find((x) => x.classList.contains('wy-m') && x.getAttribute('data-wy-side') !== 'me');
    const b = r ? r.querySelector('.wy-mb > .wy-bubble, .wy-mb > .wy-big, .wy-mb > .wy-frame') : null;
    const r0 = s.typing;
    if (!b || !r0 || !r0.width) return null;
    let r1 = null;
    try { r1 = b.getBoundingClientRect(); } catch (e) { return null; }
    if (!r1.width || !r1.height) return null;
    const dx = r0.left - r1.left;
    const dy = r0.top - r1.top - d0;
    b.style.transformOrigin = '0 0';
    soWyMoAnim(b, [{ transform: 'translate(' + dx + 'px, ' + dy + 'px) scale(' + (r0.width / r1.width) + ', ' + (r0.height / r1.height) + ')' }, { transform: 'none' }],
        { duration: 260, easing: 'cubic-bezier(.2,.9,.3,1)' });
    if (b.classList.contains('wy-bubble') && !b.classList.contains('wy-voice')) {
        const tx = soWyEl(b.ownerDocument, 'span', { class: 'wy-mo-tx' });
        while (b.firstChild) tx.appendChild(b.firstChild);
        b.appendChild(tx);
        soWyMoAnim(tx, [{ opacity: 0 }, { opacity: 1 }], { duration: 160, delay: 110, fill: 'backwards' });
    }
    for (const x of r.querySelectorAll(':scope > .wy-av, .wy-mb > .wy-mn')) soWyMoAnim(x, [{ opacity: 0 }, { opacity: 1 }], { duration: 200, easing: 'ease' });
    const ty = el.querySelector('.wy-typing');
    if (ty) {
        try {
            const dd = r0.top - (ty.querySelector('.wy-bubble') || ty).getBoundingClientRect().top - d0;
            if (Math.abs(dd) >= 1) soWyMoAnim(ty, [{ transform: 'translateY(' + dd + 'px)' }, { transform: 'none' }], { duration: 260, easing: THEATER_WEIYU_MO.glideEase });
        } catch (e) { /* no layout */ }
    }
    return r;
}

// Tier 3 · the chat header's picture (a 24 px copy of the chat's list picture beside the title — only while motion runs; the target of the
// shared element). Added after the page is built (the screens are untouched): the title's text moves into .wy-mo-tt (it keeps the ellipsis).
// Integration (2026-11-17): it IS the list row's 48 px picture shown at half size (CSS .wy-mo-hav) — the same label (soWyAvLabel), gradient,
// mosaic rows and corner as the row, so the flying copy (the row's picture scaled by .5) lands on exactly what it becomes; the title stays
// centred (a spacer as wide as the picture on its other side, CSS .wy-mo-ttl::after).
function soWyMoHeadAv(phone, el, page) {
    if (!page || page.k !== 'chat' || typeof soWyMosaicEl !== 'function') return;
    const top = soWyMoKid(el, 'wy-top');
    const ttl = top ? top.querySelector('.wy-ttl') : null;
    if (!ttl || ttl.querySelector('.wy-mo-hav')) return;
    const st = phone.memo && phone.memo.n === phone.renders ? phone.memo.state : soWyEnvState(phone);
    const chat = soWyChat(st, page.cid);
    if (!chat) return;
    let av = null;
    const was = phone.rendering;
    phone.rendering = true;   // reuse this render's read of the state (soWyMemo)
    try { av = soWyMosaicEl(phone, chat, 48); } catch (e) { av = null; } finally { phone.rendering = was; }
    if (!av) return;
    const d = el.ownerDocument;
    const tt = soWyEl(d, 'span', { class: 'wy-mo-tt' });
    while (ttl.firstChild) tt.appendChild(ttl.firstChild);
    ttl.append(soWyEl(d, 'span', { class: 'wy-mo-hav', aria: { hidden: 'true' } }, av), tt);
    ttl.classList.add('wy-mo-ttl');
}

// Tier 3 · the shared element: opening a chat from its list row, the row's picture and name fly into the chat's header (340 ms) while the
// page slides in. Measured at rest (before the slide); → start() or null (no row in view, no header picture).
function soWyMoSharedPrep(phone, ghost, el) {
    const top = phone.cur;
    if (!top || top.k !== 'chat') return null;
    const row = [...ghost.querySelectorAll('[data-wy-row]')].find((r) => r.getAttribute('data-wy-row') === top.cid);
    const sAv = row ? row.querySelector('.wy-avw > .wy-av, .wy-avw > .wy-mos') : null;
    const sNm = row ? row.querySelector('.wy-nm') : null;
    const tAv = el.querySelector('.wy-mo-hav > *');
    const tNm = el.querySelector('.wy-mo-tt');
    if (!sAv || !sNm || !tAv || !tNm) return null;
    let W; let a0; let a1; let n0; let n1; let f0; let f1;
    try {
        const cs = el.ownerDocument.defaultView.getComputedStyle;
        W = phone.root.getBoundingClientRect();
        a0 = sAv.getBoundingClientRect();
        a1 = tAv.getBoundingClientRect();
        n0 = sNm.getBoundingClientRect();
        n1 = tNm.getBoundingClientRect();
        f0 = parseFloat(cs(sNm).fontSize) || 16;
        f1 = parseFloat(cs(tNm).fontSize) || 16.5;
    } catch (e) {
        return null;
    }
    if (!a0.width || !a1.width || a0.bottom < W.top || a0.top > W.bottom) return null;
    return () => {
        const M = THEATER_WEIYU_MO;
        const mk = (src, r) => {
            const c = src.cloneNode(true);
            c.classList.add('wy-mo-fly');
            c.setAttribute('aria-hidden', 'true');
            Object.assign(c.style, { left: (r.left - W.left) + 'px', top: (r.top - W.top) + 'px', width: r.width + 'px', height: r.height + 'px' });
            phone.layer.appendChild(c);
            return c;
        };
        const ca = mk(sAv, a0);
        const cn = mk(sNm, n0);
        Object.assign(cn.style, { width: 'auto', whiteSpace: 'nowrap', overflow: 'visible', lineHeight: n0.height + 'px' });
        const ns = f1 / f0;
        const o = { duration: M.shared, easing: M.sharedEase, fill: 'forwards' };
        soWyMoAnim(ca, [{ transform: 'none' }, { transform: 'translate(' + (a1.left - a0.left) + 'px, ' + (a1.top - a0.top) + 'px) scale(' + (a1.width / a0.width) + ')' }], o);
        soWyMoAnim(cn, [{ transform: 'none' }, { transform: 'translate(' + (n1.left - n0.left) + 'px, ' + (n1.top - n0.top + (n1.height - n0.height * ns) / 2) + 'px) scale(' + ns + ')' }], o);
        tAv.style.opacity = '0';
        tNm.style.opacity = '0';
        sAv.style.visibility = 'hidden';
        sNm.style.visibility = 'hidden';
        soWyLater(phone, () => {
            tAv.style.opacity = '';
            tNm.style.opacity = '';
            ca.remove();
            cn.remove();
        }, M.shared + 10);
    };
}

// A menu / sheet closes (Tier 1): it stops being a .wy-pop-wrap at once (every check for an open menu sees none), fades for 140 ms with
// no pointer events, then goes.
function soWyMoClosePop(phone, w) {
    w.classList.remove('wy-pop-wrap');
    w.classList.add('wy-mo-gone');
    w.setAttribute('inert', '');
    w.setAttribute('aria-hidden', 'true');
    soWyLater(phone, () => w.remove(), THEATER_WEIYU_MO.close + 20);
}

// The hold control fired (MOTION-HOOK in soWyHold): the completion pop on this control — and, through soWyMoSnap, on the copy the very
// next render puts in its place.
function soWyMoHoldFire(b) {
    b._wyMoFired = Date.now();
    const root = typeof b.closest === 'function' ? b.closest('.wy') : null;
    if (root && root.getAttribute('data-wy-motion') === 'on' && typeof b.animate === 'function') b.classList.add('wy-mo-fired');
}

// The hold control (MOTION-HOOKs in soWyHold): any drain still running ends (a new press: the charge starts afresh from empty); then,
// on = an early end of a charge (release, cancel, move, blur, page hidden — called just AFTER .holding went), the fill drains from where
// it stands to empty over the full THEATER_WEIYU_MO.drain. Left alone, the class change starts the fill's CSS transition back to empty,
// a REVERSAL of the charge, which the browser shortens in proportion to how far the charge had got (a release at a third drained in
// ~60 ms). So: read where that transition starts (the charge's current scale), cancel the fill's own transform transition(s) (the fill
// then rests at the base style, scaleX(0) — nothing left that could resume charging once the drain ends), and animate scaleX(k) →
// scaleX(0) — both ends as scaleX, never a matrix (Chromium cannot interpolate a matrix into the singular scaleX(0): it flips half-way).
// No fill-mode: when the drain ends the fill shows its resting empty style. Other animations on the fill are left alone. A completed hold
// never comes here (its own pop). Only when the root's flag is on and the browser has Web Animations.
function soWyMoHoldDrain(b, on) {
    const fill = typeof b.querySelector === 'function' ? b.querySelector('.wy-hold-fill') : null;
    if (!fill) return;
    const old = fill._wyMoDrain;
    fill._wyMoDrain = null;
    if (old) {
        try { old.cancel(); } catch (e) { /* already gone */ }
    }
    if (!on) return;
    const root = typeof b.closest === 'function' ? b.closest('.wy') : null;
    if (!root || root.getAttribute('data-wy-motion') !== 'on' || typeof fill.animate !== 'function') return;
    const m = /^matrix(?:3d)?\(\s*([-+.\deE]+)/.exec(soWyMoNow(fill) || '');
    const k = m ? Math.min(1, Math.max(0, Math.round(Number(m[1]) * 1e4) / 1e4)) : NaN;
    if (!(k > 0)) return;   // empty already / unreadable: the CSS transition as it is
    try {
        if (typeof fill.getAnimations === 'function') {
            for (const a of fill.getAnimations()) if (a && a.transitionProperty === 'transform') a.cancel();
        }
    } catch (e) { /* nothing to cancel */ }
    const M = THEATER_WEIYU_MO;
    fill._wyMoDrain = soWyMoAnim(fill, [{ transform: 'scaleX(' + k + ')' }, { transform: 'scaleX(0)' }], { duration: M.drain, easing: M.drainEase });
}

function soWyMoUnpress(phone, later) {
    const r = phone.moPress;
    const b = phone.moLp;
    phone.moLp = null;
    if (b) b.classList.remove('wy-mo-lp');
    if (!r) return;
    phone.moPress = null;
    if (later) soWyLater(phone, () => r.classList.remove('wy-mo-press'), THEATER_WEIYU_MO.pressOff);
    else r.classList.remove('wy-mo-press');
}

// Pointer / scroll / wheel listeners of the motion (capture phase on the shadow root, alongside soWyMount's own) + an observer of the
// layer (a menu opening). → unwire().
function soWyMoWire(phone) {
    const M = THEATER_WEIYU_MO;
    const sh = phone.shadow;
    const w = phone.host.ownerDocument.defaultView;
    let raf = 0;
    const pending = new Set();
    const onDown = (ev) => {
        if (!soWyMoOn(phone) || (ev.button != null && ev.button !== 0)) return;
        const t = ev.target && typeof ev.target.closest === 'function' ? ev.target : null;
        soWyMoUnpress(phone, false);
        if (!t || t.closest('.wy-mo-ghost')) return;
        // Tier 1: the row dips on pointer-down; Tier 2: a ripple from the press point
        const row = t.closest('.wy-row, .wy-prow');
        if (row && phone.root.contains(row)) {
            row.classList.add('wy-mo-press');
            phone.moPress = row;
            if (row.classList.contains('wy-row')) soWyMoRipple(phone, row, ev);
        }
        // Tier 2: a pressed bubble dips (the menu, if this becomes a long press, rises from it) — not under 消息菜单 = 长按气泡, where lane D's
        // lift (.wy-lp) is the press feedback and hands over to the rising menu by itself (integration: one motion per press)
        const bub = t.closest('.wy-bubble, .wy-big, .wy-frame');
        if (bub && !bub.closest('[data-wy-hold], .wy-pop-wrap, .wy-typing, .wy-menu-hold') && phone.root.contains(bub)) {
            bub.classList.add('wy-mo-lp');
            phone.moLp = bub;
        }
        if (phone.moPress || phone.moLp) phone.moPressAt = { x: ev.clientX || 0, y: ev.clientY || 0 };
        soWyMoSwipeStart(phone, ev);   // Tier 2: from the left edge
    };
    const onUp = (ev) => {
        soWyMoUnpress(phone, true);
        soWyMoSwipeEnd(phone, ev);
    };
    const onMove = (ev) => {
        const p = phone.moPressAt;
        if ((phone.moPress || phone.moLp) && p && Math.hypot((ev.clientX || 0) - p.x, (ev.clientY || 0) - p.y) > M.pressMove) soWyMoUnpress(phone, false);
        soWyMoSwipeMove(phone, ev);
    };
    // the click that ends a swipe is not a tap on whatever lies under the finger
    const onClick = (ev) => {
        if (phone.moEat && Date.now() - phone.moEat < 400) {
            phone.moEat = 0;
            ev.stopPropagation();
            ev.preventDefault();
        }
    };
    const onScroll = (ev) => {
        const sc = ev.target;
        if (!soWyMoOn(phone) || !sc || !sc.classList || !sc.classList.contains('wy-scroll')) return;
        if (phone.moPress || phone.moLp) soWyMoUnpress(phone, false);
        pending.add(sc);
        if (raf) return;
        raf = w.requestAnimationFrame(() => {
            raf = 0;
            for (const x of pending) if (x.isConnected) soWyMoScrolled(x);
            pending.clear();
        });
    };
    const onWheel = (ev) => soWyMoBand(phone, ev);   // Tier 3: rubber-band ends
    const L = [['pointerdown', onDown], ['pointerup', onUp], ['pointercancel', onUp], ['pointermove', onMove], ['click', onClick], ['scroll', onScroll]];
    for (const [type, fn] of L) sh.addEventListener(type, fn, true);
    sh.addEventListener('wheel', onWheel, { capture: true, passive: true });
    // Tier 2: a menu that opens over a message rises from that message (soWyMoMenu); observed, so the screens need no hook
    let mo = null;
    if (typeof w.MutationObserver === 'function') {
        mo = new w.MutationObserver((recs) => {
            if (!soWyMoOn(phone)) return;
            for (const r of recs) for (const n of r.addedNodes) if (n.nodeType === 1 && n.classList.contains('wy-pop-wrap')) soWyMoMenu(phone, n);
        });
        mo.observe(phone.layer, { childList: true });
    }
    return () => {
        for (const [type, fn] of L) sh.removeEventListener(type, fn, true);
        sh.removeEventListener('wheel', onWheel, { capture: true });
        if (mo) mo.disconnect();
        if (phone.moIO) {
            phone.moIO.disconnect();
            phone.moIO = null;
        }
        if (raf) {
            try { w.cancelAnimationFrame(raf); } catch (e) { /* gone */ }
        }
    };
}

// Tier 2 · the ripple: from the press point, 450 ms, 18 % of the accent (CSS .wy-mo-rip); the row clips it.
function soWyMoRipple(phone, row, ev) {
    let r = null;
    try { r = row.getBoundingClientRect(); } catch (e) { return; }
    const s = Math.max(r.width, r.height) * 2.2;
    const rip = soWyEl(row.ownerDocument, 'span', { class: 'wy-mo-rip', aria: { hidden: 'true' } });
    Object.assign(rip.style, { width: s + 'px', height: s + 'px', left: ((ev.clientX || 0) - r.left - s / 2) + 'px', top: ((ev.clientY || 0) - r.top - s / 2) + 'px' });
    row.appendChild(rip);
    soWyLater(phone, () => rip.remove(), THEATER_WEIYU_MO.rip + 30);
}

// Tier 2 · the menu rises from the bubble: a menu that opens over a message (anything in the layer that is not the ⊕ menu or a sheet —
// those have their own CSS) scales .82 → 1 in 200 ms from the pressed bubble's edge (the edge nearest the menu, at the bubble's centre).
function soWyMoMenu(phone, wrap) {
    const pop = [...wrap.children].find((c) => !c.classList.contains('wy-backdrop'));
    if (!pop || pop.classList.contains('wy-pop-plus') || pop.classList.contains('wy-sheet')) return;
    const mid = phone.menu && phone.menu.mid;
    const row = mid && phone.pageEl ? [...phone.pageEl.querySelectorAll('[data-wy-msg]')].find((r) => r.getAttribute('data-wy-msg') === mid) : null;
    const b = row ? row.querySelector('.wy-bubble, .wy-big, .wy-frame, .wy-sys-t') || row : phone.moLp;
    let ox = '50%';
    let oy = '100%';
    try {
        const pr = pop.getBoundingClientRect();
        if (b && pr.width) {
            const br = b.getBoundingClientRect();
            ox = Math.max(0, Math.min(pr.width, br.left + br.width / 2 - pr.left)) + 'px';
            oy = pr.top >= br.top ? '0px' : pr.height + 'px';
        }
    } catch (e) { /* no layout */ }
    pop.style.transformOrigin = ox + ' ' + oy;
    soWyMoAnim(pop, [{ opacity: 0, transform: 'scale(.82)' }, { opacity: 1, transform: 'none' }], { duration: THEATER_WEIYU_MO.menu, easing: THEATER_WEIYU_MO.menuEase });
}

// Tier 2 · edge swipe back: a press within 28 px of the page's left edge on a page that has one under it. It becomes a swipe once it moves
// right more than 6 px (and more right than down); then the page follows the finger with the page under it (built for the swipe, inert)
// drifting in from −24 % under a fading dim. Release past 35 % of the width or faster than 0.5 px/ms = back (the slide takes over from
// where the finger left it); otherwise both snap back (260 ms). A tap there stays a tap.
function soWyMoSwipeStart(phone, ev) {
    if (phone.moSwipe || phone.stack.length < 2 || !phone.pageEl) return;
    const page = phone.pageEl;
    const t = ev.target;
    if (!page.contains(t) || t.closest('textarea, input, [data-wy-hold]')) return;
    let R = null;
    try { R = page.getBoundingClientRect(); } catch (e) { return; }
    if (!R.width || (ev.clientX || 0) - R.left > THEATER_WEIYU_MO.edge) return;
    const now = Date.now();
    phone.moSwipe = { x0: ev.clientX || 0, y0: ev.clientY || 0, id: ev.pointerId, on: false, page, W: R.width, lastX: ev.clientX || 0, lastT: now, v: 0, dx: 0 };
}

function soWyMoSwipeMove(phone, ev) {
    const M = THEATER_WEIYU_MO;
    const sw = phone.moSwipe;
    if (!sw || (sw.id != null && ev.pointerId != null && ev.pointerId !== sw.id)) return;
    const dx = (ev.clientX || 0) - sw.x0;
    const dy = (ev.clientY || 0) - sw.y0;
    if (!sw.on) {
        if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(dx)) {
            phone.moSwipe = null;
            return;
        }
        if (dx <= 6 || dx < Math.abs(dy)) return;
        if (!soWyMoOn(phone) || !soWyMoSwipeBegin(phone, sw, ev)) {
            phone.moSwipe = null;
            return;
        }
    }
    const now = Date.now();
    sw.v = ((ev.clientX || 0) - sw.lastX) / Math.max(1, now - sw.lastT);
    sw.lastX = ev.clientX || 0;
    sw.lastT = now;
    sw.dx = Math.max(0, dx);
    const p = Math.min(1, sw.dx / sw.W);
    sw.page.style.transform = 'translateX(' + sw.dx + 'px)';
    sw.under.style.transform = 'translateX(' + (-24 * (1 - p)).toFixed(2) + '%)';
    sw.dim.style.opacity = (M.dim * (1 - p)).toFixed(3);
}

// The page under the current one, built for the swipe (the same builder a back would use; inert, never answering) + the dim.
function soWyMoSwipeBegin(phone, sw, ev) {
    soWyMoDropGhost(phone);
    soWyMoUnpress(phone, false);
    const below = phone.stack[phone.stack.length - 2];
    let el = null;
    phone.renders = (phone.renders || 0) + 1;
    phone.rendering = true;
    try { el = soWyPageBuild(phone, below); } catch (e) { el = null; } finally { phone.rendering = false; }
    if (!el) return false;
    el.classList.add('wy-page', 'wy-mo-ghost');
    el.setAttribute('data-wy-page', below.k);
    el.setAttribute('inert', '');
    el.setAttribute('aria-hidden', 'true');
    el.style.transform = 'translateX(' + THEATER_WEIYU_MO.drift + ')';
    phone.root.insertBefore(el, sw.page);
    soWyMoPrep(phone, el, below);
    const sc = soWyMoKid(el, 'wy-scroll');
    if (sc && below.k === 'chat') sc.scrollTop = sc.scrollHeight;
    if (sc) soWyMoScrolled(sc);
    const dim = soWyEl(phone.host.ownerDocument, 'div', { class: 'wy-mo-dim', aria: { hidden: 'true' } });
    dim.style.opacity = String(THEATER_WEIYU_MO.dim);
    phone.root.insertBefore(dim, phone.layer);
    for (const a of soWyMoAnims(sw.page)) a.cancel();
    sw.page.classList.add('wy-mo-top');
    try { if (ev.pointerId != null && typeof sw.page.setPointerCapture === 'function') sw.page.setPointerCapture(ev.pointerId); } catch (e) { /* fine */ }
    sw.under = el;
    sw.dim = dim;
    sw.on = true;
    return true;
}

function soWyMoSwipeEnd(phone, ev) {
    const M = THEATER_WEIYU_MO;
    const sw = phone.moSwipe;
    if (!sw || (sw.id != null && ev && ev.pointerId != null && ev.pointerId !== sw.id)) return;
    phone.moSwipe = null;
    if (!sw.on) return;
    phone.moEat = Date.now();
    const done = !!ev && ev.type !== 'pointercancel' && (sw.dx > sw.W * M.swipeDone || sw.v > M.swipeFling) && phone.pageEl === sw.page && soWyMoOn(phone);
    if (done) {
        // the back slide starts from where the finger left both pages (soWyMoKeep reads the hand)
        phone.moHand = { from: sw.page.style.transform, transform: sw.under.style.transform, dim: Number(sw.dim.style.opacity) };
        sw.under.remove();
        sw.dim.remove();
        soWyBack(phone);
        return;
    }
    const o = { duration: M.back, easing: M.backEase };
    soWyMoAnim(sw.page, [{ transform: sw.page.style.transform || 'none' }, { transform: 'none' }], o);
    sw.page.style.transform = '';
    soWyMoAnim(sw.under, [{ transform: sw.under.style.transform }, { transform: 'translateX(' + M.drift + ')' }], Object.assign({ fill: 'forwards' }, o));
    soWyMoAnim(sw.dim, [{ opacity: Number(sw.dim.style.opacity) }, { opacity: M.dim }], Object.assign({ fill: 'forwards' }, o));
    soWyLater(phone, () => {
        sw.under.remove();
        sw.dim.remove();
        if (!phone.moGhost || phone.moGhost.inEl !== sw.page) sw.page.classList.remove('wy-mo-top');
    }, M.back + 30);
}

// Tier 3 · rubber-band ends (wheel / trackpad): scrolling on past the top or the end stretches the list up to 60 px; 110 ms after the last
// wheel step it springs back (420 ms). Touch ends are left to the platform (iOS bounces, Android stretches inner scrollers natively).
function soWyMoBand(phone, ev) {
    const M = THEATER_WEIYU_MO;
    if (!soWyMoOn(phone) || !ev.deltaY) return;
    const sc = ev.target && typeof ev.target.closest === 'function' ? ev.target.closest('.wy-scroll') : null;
    if (!sc || sc.closest('.wy-mo-ghost') || !phone.root.contains(sc)) return;
    const atTop = sc.scrollTop <= 0;
    const atEnd = sc.scrollTop + sc.clientHeight >= sc.scrollHeight - 1;
    if (!((atTop && ev.deltaY < 0) || (atEnd && ev.deltaY > 0))) return;
    const st = sc._wyMoBand || (sc._wyMoBand = { acc: 0, t: null });
    st.acc = Math.min(500, st.acc + Math.abs(ev.deltaY));
    const off = M.band * (1 - Math.exp(-st.acc / 160)) * (ev.deltaY < 0 ? 1 : -1);
    for (const a of soWyMoAnims(sc)) a.cancel();
    sc.style.transform = 'translateY(' + off.toFixed(1) + 'px)';
    if (st.t) {
        clearTimeout(st.t);
        phone.timers.delete(st.t);
    }
    st.t = soWyLater(phone, () => {
        st.t = null;
        st.acc = 0;
        const from = sc.style.transform;
        sc.style.transform = '';
        if (from) soWyMoAnim(sc, [{ transform: from }, { transform: 'none' }], { duration: M.bandBack, easing: M.bandEase });
    }, M.bandRest);
}

// 动画 turned off (or the phone goes): every running motion of the phone ends where it ends — kept pages and fading menus go now, the
// phone's own animations are cancelled (elements back at rest).
function soWyMoHalt(phone) {
    soWyMoDropGhost(phone);
    soWyMoUnpress(phone, false);
    const sw = phone.moSwipe;
    phone.moSwipe = null;
    if (sw && sw.page) sw.page.style.transform = '';
    if (phone.moIO) {
        phone.moIO.disconnect();
        phone.moIO = null;
    }
    for (const a of soWyMoAnims(phone.root, true)) a.cancel();
    for (const el of phone.root.querySelectorAll('.wy-mo-gone, .wy-mo-dim, .wy-mo-pwr, .wy-mo-fly, .wy-mo-folding, .wy-mo-phantom, .wy-mo-ghost')) el.remove();
    for (const el of phone.root.querySelectorAll('.wy-mo-pre')) el.classList.remove('wy-mo-pre');
}

// The frame (outside the shadow root) follows the phone's flag: env.onMotion(flag) — the join mirrors it onto #so-thr-weiyu-card.
function soWyMoMirror(phone) {
    try {
        if (phone.env && typeof phone.env.onMotion === 'function') phone.env.onMotion(phone.motion);
    } catch (e) { /* the frame keeps its last flag */ }
}

// destroy() with motion on: the screen keeps its last picture (inert) while the frame plays its leave, then empties — unless a new phone
// was mounted into the same host meanwhile (mount empties the shadow root itself; this one then has nothing to do).
function soWyMoLinger(phone) {
    const sh = phone.shadow;
    const root = phone.root;
    root.setAttribute('inert', '');
    setTimeout(() => {
        if (root.parentNode === sh) sh.replaceChildren();
    }, THEATER_WEIYU_MO.linger);
}

// Tier 3 · power-on: when the phone opens, the screen starts black and wakes with a green bloom from the centre (600 ms, deliberate; CSS
// .wy-mo-pwr). It never takes a tap (pointer-events: none) and goes after 800 ms.
function soWyMoPower(phone) {
    if (!soWyMoOn(phone)) return;
    const p = soWyEl(phone.host.ownerDocument, 'div', { class: 'wy-mo-pwr', aria: { hidden: 'true' } });
    phone.root.appendChild(p);
    soWyLater(phone, () => p.remove(), 800);
}
