    const sum = soThrBoardSumOn()
        ? '<div class="so-hint" id="so-thr-board-sum-note" data-so-bt="sumStatement"></div>' + num('sumAtLabel', 'so-thr-board-sum-at', 'sumAt') + num('sumKeepLabel', 'so-thr-board-sum-keep', 'sumKeep')
        : '';
