    if (!ctx || typeof ctx.setExtensionPrompt !== 'function') return false;
    const quiet = soThrBoardQuietOpen();   // quiet 正在拼 = 这一格只能是空的（借用期间也写：空值带不进任何请求；挪开期间写 = 小剧场不再放回原文）
