    soThrBoardGenType = type == null ? null : String(type);
    let ctx = null;
    try { ctx = getCtx(); } catch (e) { ctx = null; }
    // 群聊里这一格恒空，不记账（ST 群聊外层那一趟永远不发 AFTER_DATA）
