const THEATER_AUTO_FAILED = (name, why) => `自动场景「${name}」没写成：${why}`;
const THEATER_AUTO_NO_HELPER = '没有检测到酒馆助手：自动场景先不贴进主聊天（没有它，贴进去只会显示成一大段代码）';
