    paint(soEstimateTokens(lastPrompt));
    if (u && u.input != null) return;
    let count = null;
    try { const c = getCtx(); count = c && typeof c.getTokenCountAsync === 'function' ? c.getTokenCountAsync : null; } catch (e) { count = null; }
    if (!count) return;
