    if (i.code === 'invalid_type') return '必须是' + (DIAG_TYPE_ZH[i.expected] || '另一种类型');
    if (i.code === 'invalid_value' || i.code === 'invalid_enum_value') return '只能是：' + (i.values || []).map(diagValShow).join('、');
