    if (i.origin === 'string') return small ? (excl ? `长度必须多于 ${n} 个字` : `长度不能少于 ${n} 个字`) : (excl ? `长度必须少于 ${n} 个字` : `长度不能超过 ${n} 个字`);
    if (i.origin === 'array' || i.origin === 'set') return small ? (excl ? `必须多于 ${n} 项` : `至少要有 ${n} 项`) : (excl ? `必须少于 ${n} 项` : `最多只能有 ${n} 项`);
