// —— 自动功能（plan Task 6）——
// 每个「每条回复后自动跑」的开关在这里有一份镜像（data-so-mirror，没有 id）：镜像不存任何状态，改它 = 驱动原控件（soSetV2MirrorSet），
// 画它 = 读设置（soSetV2PaintMirrors）。每行：标题 + 「设置 ›」（去那个模式自己的设置栏）、一句说明、一行原因（停用 / 不会跑时才有字）。
function soSetV2PaneAuto() {
    const C = SET_V2_COPY;
    const go = (target) => (target ? `<button type="button" class="so-set-go" data-so-go="${target}">${C.autoGo}</button>` : '');
    const row = (key, head, desc, target, extra) => `<div class="so-auto-row" data-so-auto="${key}"><div class="so-line so-auto-head">${head}${go(target)}</div>${extra || ''}<div class="so-hint so-auto-desc">${desc}</div><div class="so-hint so-auto-why" hidden></div></div>`;
    const check = (key, title) => `<label class="so-check"><input type="checkbox" data-so-mirror="${key}"><span>${title}</span></label>`;
    const rows = [];
    if (ENABLE_AUTO_DIAGNOSE) rows.push(row('diag', check('diag', C.autoDiag), C.a3Diag, 'diagnose'));
    if (ENABLE_REPLY_FIX) {
        rows.push(row('fix', `<label class="so-check so-auto-t"><span>${C.autoFix}</span><span class="so-badge">${C.autoFixBadge}</span><select data-so-mirror="fix" aria-label="${C.autoFix}"><option value="off">${C.autoFixOff}</option><option value="fix">${C.autoFixFix}</option>${ENABLE_FIX_CUSTOM_TASK ? `<option value="custom">${C.autoFixCustom}</option>` : ''}</select></label>`, C.a3Fix, 'fix'));
    }
    if (ENABLE_NEXT_BEAT) rows.push(row('nbeat', check('nbeat', C.autoNbeat), C.a3Nbeat, 'advisor'));
    if (ENABLE_THEATER) {
        const boxes = THEATER_SCENES.map((sc) => `<label class="so-check"><input type="checkbox" data-so-mirror="scene:${sc}"><span>${THEATER_SCENE_ICONS[sc] || ''} ${THEATER_SCENE_NAMES[sc] || sc}</span></label>`).join('');
        rows.push(row('scene', `<span class="so-line-t so-auto-t">${C.autoScene}</span>`, C.a3Scene, 'tab:thr', `<div class="so-chipset">${boxes}</div>`));
    }
    // 📱 微谕「跟着剧情更新」（plan Task 7，Stage 2 旗）：原开关在手机「我」页里（手机开着才有）——这份镜像直接走手机那颗开关的同一个 setter。
    // 设置都在手机里，所以这一行没有「设置 ›」。
    if (soThrWeiyuSyncOn()) rows.push(row('wysync', check('wysync', C.autoWy), C.a4, ''));
    const pointer = ENABLE_MODE_CONN ? `<div class="so-line so-auto-pointer"><span class="so-hint so-line-t">${C.autoPointer}</span><button type="button" class="so-set-go" data-so-go="tab:conn">${C.autoPointerGo}</button></div>` : '';
    return soSetV2Group('so-set-auto', C.g5, 'auto', `<div class="so-lead">${C.g8}</div>${pointer}${rows.join('')}<div class="so-hint so-auto-foot">${C.autoFoot}</div>`);
}

