    if (soPresetUse(s, 'fixManual').curated) add('fixManual', 'rule:span');   // 选段同理（手动校正的内置破限）
    const lb = soPresetUse(s, 'lorebook');
    if (lb.curated || lb.jb) add('lorebook', 'rule:smart');
    const dg = soPresetUse(s, 'diagnose');
    if (PRESET_STD_SCAN_FOLLOWS && (dg.curated || dg.jb)) add('diagnose', 'rule:scan');
    // 🎚 Stage 3（addendum A-6）：参谋 / 小剧场在这次更新之前就开着「跟酒馆实时走」= 🧭 下一拍 / IF 的变量推导从此也按实时发（每条回复多一条大请求）。
