    if (kind === 'carry') return C.carry;
    if (typeof kind === 'string' && kind.startsWith('live:')) {   // 🎚 Stage 3（A-6）
        const L = LIVE_ALL_COPY;
        const lf = kind.slice(5);
        return (Object.hasOwn(L.feat, lf) && Object.hasOwn(L.mode, owner)) ? L.liveNote(L.feat[lf], L.mode[owner]) : '';
    }
