    const room = convoStreamKey;
    const chatKey = fixChatKey();
    const sig = j.signal || null;
    let clearDots = typeof j.clearTyping === 'function' ? j.clearTyping : () => {};
    let stop = null;        // 拼提示词那一刻闸没过（换了预设 / 那份还没挑…）的 Status
    let mine = null;        // 引擎登记的那一趟（soThrRun），第一次 onState / beforeAssemble 时认下
