    const name = (st && typeof st.name === 'string') ? st.name : '';
    const msg = reason === 'unpicked' ? LIVE_COPY.unpicked(name) : String((st && st.text) || LIVE_COPY.engine);
    const e = Object.assign(new Error(msg), { soLive: true, soLiveRefused: { reason, name, owner, feature: r.feature || '', auto } });
